WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[11167] = { title = "The New Plague", description = "Not long after Arthas condemned us to this wretched existence, we in the Royal Apothecary Society endeavored to create a plague of our own.  A plague that would devour all flesh: living, dead or undead.\n\nWe've succeeded in creating this plague and we're here to hand deliver it to the Scourge's doorstep.\n\nThe Alliance intercepted the ship carrying the latest strain engineered in our Undercity laboratories.  Head to the wreckage southeast of here and salvage whatever containers you can.", objectives = "" }
WordHunterWoW_QuestEN[11168] = { title = "Spiking the Mix", description = "I've a feeling the long trip across the sea is affecting the effectiveness of our plague.  What is needed is a potent toxin to boost the potency of the strain.\n\nThe crabs near this beach are a distant relative of the much smaller brown-shelled tidecrawler.  The smaller tropical variety produces a paralytic toxin strong enough to knock out an ogre.\n\nAs we all know bigger is better!  The much larger glands on the local variety should prove more potent.  Bring me a few!", objectives = "" }
WordHunterWoW_QuestEN[11170] = { title = "Test at Sea", description = "We've just received word of reinforcements coming to the aid of the Alliance forces.  Their timing couldn't be better!\n\nWe're in sore need of test subjects and these North Fleet reservists will do nicely!\n\nTake these plague vials with you and speak to Camille, the Bat Handler.  Tell her you need to commandeer a riding bat for a special assignment for us.\n\nOnce you're at sea, drop the vials on the reinforcement fleet.  I can't wait to see the results!", objectives = "" }
WordHunterWoW_QuestEN[11175] = { title = "My Daughter", description = "Tell me, is it true? Did the explorers that went into Whisper Gulch go mad?\n\nMy daughter is the overseer of the Explorers' League that went north to some place called Steel Gate. With the horrible events that have befallen us, I fear for her safety.\n\nPlease, {class}, I am too old to make the journey. Her name is Irena. Will you go make certain that she is alright?", objectives = "" }
WordHunterWoW_QuestEN[11176] = { title = "See to the Operations", description = "Our work out here is really just beginning. But now that we've brought these flying machines in from Westguard Keep, it should really pick up.\n\nThe problem is that we're lacking enough qualified pilots. And with things getting worse in the Rivenwood to the north, I'd like to get things wrapped up here quickly and then head back home.\n\nIf you can lend a hand, go have a chat with one of my chief archaeologists. You'll find them next to the flying machines on the north and south sides of the site.", objectives = "" }
WordHunterWoW_QuestEN[11182] = { title = "Root Causes", description = "All things in nature seek a balance. It is only through the interference of those not in tune with that harmony that the balance is shifted.\n\nYou waste your efforts when you kill the whelps and drakes. The real culprits behind the expansion of these magically burning woods are the newly awakened vrykul and their master, Skeld Drakeson.\n\nIf it's blood on your hands that you seek, start with them. You will find their lair on the south side of the Ember Clutch.", objectives = "" }
WordHunterWoW_QuestEN[11187] = { title = "Mage-Lieutenant Malister", description = "THIS IS OUTRAGEOUS! Those proto-drakes are attacking the keep!\n\nBeasts such as that should have been scared off when you took care of their clutches and whelps.\n\nYou did take care of them, right?\n\n{name}, this calls for more direct action. Speak with my advisor, Mage-Lieutenant Malister. He'll provide you with the means to get at those infernal creatures.", objectives = "" }
WordHunterWoW_QuestEN[11188] = { title = "Two Wrongs...", description = "Now that we've riled up these Ember Clutch proto-drakes, they may be inclined to continue their attacks upon the keep. This will not do.\n\nI hate to compound one wrong with another, but in this case it would appear that we will have to destroy the creatures. A regrettable course of action, but one that we need to undertake regardless.\n\nTake my wand. I've been experimenting with increasing its range, but it doesn't pack much of a punch. However, what it will do is get a proto-drake's attention.", objectives = "" }
WordHunterWoW_QuestEN[11190] = { title = "One Size Does Not Fit All", description = "Lad, who's the genius that made our cannons a non-standard size? Now we have ta make special cannonballs ta shoot out o' the infernal contraptions!\n\nI would look kindly on ye if ye would go out and find the balls we've already shot. No doubt with the way these louts shoot they be all o'er the place ta the south and east.\n\n<The cannoneer spaces his hands apart to give you an idea of how big the cannonballs are.>\n\nThat would be faster than us making 'em from scratch fer a certainty.", objectives = "" }
WordHunterWoW_QuestEN[11196] = { title = "Warlord of the Amani", description = "Da Amani been rebuildin' their forces and dey raised up a new warlord to lead dem, {name}. He be called Daakara da Invincible, but we be seein' whether he lives up to the name or not.\n\nYa must first defeat all his lieutenants to clear da way before ya can face this Daakara. Defeat him and put an end to da ambitions of da Zandalari and da Amani!\n\n\n", objectives = "" }
WordHunterWoW_QuestEN[11199] = { title = "Report to Scout Knowles", description = "{name}, now that those damnable proto-creatures have been dealt with, I've another task for you.\n\nOne of my scouts has reported back some suspicious activity by the Forsaken to the south. It looks like they're up to no good at the vrykul village known as Halgrind.\n\nI want you to personally take over the investigation down there. Speak with Scout Knowles to find out what he's uncovered and proceed from there.\n\nHis last reported position is at the Ember Spear Tower, just to the west of Halgrind.", objectives = "" }
WordHunterWoW_QuestEN[11202] = { title = "Mission: Eternal Flame", description = "The Forsaken are up to no good and from what I can tell, those plague tanks of sludge are a big part of it.\n\nIf I may suggest, sir, we should probably destroy them before they can get any more use out of the things. I took the liberty of preparing a bundle of torches from the Ember Clutch. These things have been burning for days!\n\nHere, I'm sure you can put them to better use than I in destroying those tanks.", objectives = "" }
WordHunterWoW_QuestEN[11208] = { title = "Delivery for Drazzit", description = "Drazzit will expect to hear something from me soon, but I don't think the site is secure enough for me to leave. If you have time, would you be willing to take some of the salvaged cargo down to him at Mudsprocket?\n\nIf you haven't been there yet, it's a small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking for is Drazzit Dripvalve.", objectives = "" }
WordHunterWoW_QuestEN[11211] = { title = "Help for Mudsprocket", description = "When that goblin... what's her name... Boxie, Foxy... Moxie, that's it! Anyway, when she came through here on her way to the zeppelin wreck, she said the town of Mudsprocket was having some problems.\n\nThat crashed zeppelin was bringing them fresh supplies. If you follow the road south from here, past the Stonemaul Ruins, you'll eventually come to Mudsprocket.\n\nWhy don't you check in with Drazzit Dripvalve down there and see if there's anything you can do to help?", objectives = "" }
WordHunterWoW_QuestEN[11212] = { title = "Tabetha's Farm", description = "Deep in the heart of the swamp lives an old woman named Tabetha. We've never really known much about her, save that she's a good deal older than she appears. She's helped us from time to time and helped keep the peace here between the Horde and our forces.\n\nShe used to keep in regular contact, but we haven't received one lately.\n\nCould you check in with her when you have time? Just follow the road beyond North Point Tower, where it turns south and into the Quagmire. You can see her farm from the road.", objectives = "" }
WordHunterWoW_QuestEN[11213] = { title = "Check Up on Tabetha", description = "A human woman named Tabetha lives on a small farm near the middle of the marsh. Ordinarily, I wouldn't associate with a human, but her help has proven useful at times.\n\nUnfortunately, she's been out of touch for quite some time now and I'm looking for someone to travel down to her farm to see if everything's all right.\n\nIf you follow the road south out of the village, then into the swamp's interior, you'll find her farm near the middle of the Quagmire.", objectives = "" }
WordHunterWoW_QuestEN[11215] = { title = "Help Mudsprocket", description = "The Steamwheedle Cartel's new outpost in the southern part of the marsh isn't faring so well. The zeppelin carrying supplies to Mudsprocket crashed, leaving them without vital tools, food, and medical supplies.\n\nFollow the road down south and into the marsh's interior. You'll pass by Tabetha's Farm and the Stonemaul Ruins before the road brings you to Mudsprocket. Offer any help you can provide to the town's leadership.", objectives = "" }
WordHunterWoW_QuestEN[11218] = { title = "Danger! Explosives!", description = "{name}, the captain's tasked me with a mission. I'd like you to help.\n\nA bunch of my fellow Explorers' League people went nuts digging up stuff in the Whisper Gulch just to the north. They're attacking anyone trying to get in!\n\nThe captain is only concerned with the ore for the keep. Lucky for us, I have just the thing to do the trick.\n\nGet in there, blow up the ore, and bring it back along with any gems you find. Running this place isn't cheap you know!\n\nI gotta warn you though, that ore is strange!", objectives = "" }
WordHunterWoW_QuestEN[11219] = { title = "Stop the Fires!", description = "The Horde's children need you, {name}.  The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village!  You must put out those fires!\n\nGrab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames.  Extinguish all the fires and thwart the Headless Horseman!", objectives = "" }
WordHunterWoW_QuestEN[11220] = { title = "The Headless Horseman", description = "Until the head of the Headless Horseman is destroyed, his rampage will not end.\n\nThe Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades.  Go to his pumpkin shrine and speak these words:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nThis will rouse the fiend.  Destroy the head of the Horseman and he will plague us no longer.", objectives = "" }
WordHunterWoW_QuestEN[11221] = { title = "Reports from the Field", description = "Our mission in Northrend is to destroy Arthas.  The Alliance are but an obstacle that we'll crush wherever we find them.\n\nWe've managed to destroy their easternmost fleet; but the survivors have barricaded themselves on the Derelict Strand, south of here.\n\nOur forces should've overwhelmed their make-shift defenses long ago, but we underestimated their will to live.  Seek my officers in the field, Dark Ranger Lyana and Deathstalker Razael and get them to report on the situation.", objectives = "" }
WordHunterWoW_QuestEN[11224] = { title = "Send Them Packing", description = "I've heard rumors of bad happenings in the Whisper Gulch to the north. Most of the Explorers' League went down into that place, and some say they went mad with what they discovered.\n\nThat doesn't change the fact that they took most of our mules and equipment with them, though. I won't lose those mules!\n\nIf you find yourself in there, and happen across any of my mules, just get up close on them and threaten them with a raised hand. They'll spook and come home for sure.", objectives = "" }
WordHunterWoW_QuestEN[11227] = { title = "Let Them Eat Crow", description = "The high executor wants me to use my dogs to sniff out enemy scouts, but I can tell you right now these plaguehounds aren't going anywhere until they're properly fed.\n\nIf our military doesn't understand that these beasts are picky enough to not eat the rubbish they've given me, then they can't expect them to be of any use in the field.\n\nYou seem to have some time on your hands, why don't you take one of these dogs out hunting for crows out west?  Their meat isn't very tasty to us, but my boys love it!", objectives = "" }
WordHunterWoW_QuestEN[11228] = { title = "Hell Has Frozen Over...", description = "Fordragon's got another thing coming if he thinks the group of green-gilled scrubs he sent to defend this port can hold out much longer.\n\n<Macalroy raises an eyebrow as he examines your equipment.>\n\nYou, however, might fare a bit better.\n\nThe importance of holding this port cannot be stated enough; and with those monsters flying overhead, the situation around here has gone from bad to worse.\n\nReport to Vice Admiral Keller just northwest of here and let him know that you're all out of bubble gum.", objectives = "" }
WordHunterWoW_QuestEN[11229] = { title = "The Windrunner Fleet", description = "We have the Windrunner, the Queen's Reprisal and the Oblivion stationed just east of the Derelict Strand.  Send orders to the fleet's commander, Captain Harker, that they're to destroy the Alliance's cannons.\n\nSpeak to our bat handler, Camille, and ask for passage to the fleet's location.  Be quick, {name}, every minute we spend fighting the Alliance is a minute we could've spent fighting Arthas.", objectives = "" }
WordHunterWoW_QuestEN[11230] = { title = "Ambushed!", description = "This should have been a walk in the park.  Their forces are hungry, injured and ill equipped.  Yet somehow, we walked right into their trap.\n\nWe approached these reefs from the south to gain cover and were immediately boarded by the Alliance dogs.\n\nI'm sorry to say, if you want our cannons to fire at anything, you're going to have to help us take our ships back.", objectives = "" }
WordHunterWoW_QuestEN[11231] = { title = "Of Keys and Cages", description = "The captain may not care, but from the little we know, the vrykul are conducting heinous rites in some sort of 'awakening' ritual up north in Gjalerbron.\n\nThey're using living sacrifices to fuel their unholy rituals!\n\n{class}, you must put a stop to this! It matters not who or what is in those cages, they must be freed. I'd bet that the vrykul hold the keys.\n\nThe Light knows the last thing we need is more of those strange vrykul walking about, or worse yet, them wakening something even more evil!", objectives = "" }
WordHunterWoW_QuestEN[11232] = { title = "Guide Our Sights", description = "We should be able to kill our way back to our guns.  Unfortunately, visibility is less than desirable so you will have to mark our targets from the ground.\n\nTake these smoke flares with you and use them to mark the locations of the cannons along the northern wall in the Derelict Strand, west of here, where the Alliance are holding out.\n\nLet Lyana know as soon as the way is clear for the ground troops.  We can take care of ourselves over here.", objectives = "" }
WordHunterWoW_QuestEN[11233] = { title = "Landing the Killing Blow", description = "You've proven yourself in the field of battle, {name}.  You might very well have changed the tides in our favor.\n\nI've an important assignment for you now.  I'm not sure how much longer the weakness we've exposed is going to last, so we must use the element of surprise to our advantage.\n\nI want you to use the confusion created by our attack and go behind enemy lines to assassinate their leaders.  In order of rank, they are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric.  Good luck, {class}.", objectives = "" }
WordHunterWoW_QuestEN[11234] = { title = "Report to Anselm", description = "Let's send word back to old Anselm then.  Victory has come later than expected, but better late than never.  Tell him it will take our forces a few hours at most to finish off the stragglers here.\n\nGlory to the Banshee Queen!", objectives = "" }
WordHunterWoW_QuestEN[11235] = { title = "Dealing With Gjalerbron", description = "And now we have a different problem. My scouts that have lived to return have informed me that the vrykul are up to no good at their main fortress to the north.\n\nThey call the place Gjalerbron, though you'd pronounce the 'Gj' as if it were an 'Sh'. Odd creatures.\n\nBut that's not important; what is, is that you get up there and put an end to the lives of as many of those creatures as you can while trying to figure out what they're up to.\n\nI know that I can count on you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[11236] = { title = "Necro Overlord Mezhen", description = "The Scourge are at Gjalerbron and they have necromancers with them! They must be working to bring the vrykul into Arthas' fold.\n\nI want the leader of these necrolords eliminated!\n\nDo whatever it takes, {name}, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nI will not see the vrykul successfully allied with the Scourge!\n\nLook for Mezhen on the platform in the rear right section of Gjalerbron.", objectives = "" }
WordHunterWoW_QuestEN[11237] = { title = "Gjalerbron Attack Plans", description = "These plans detail an imminent attack upon Westguard Keep. It would appear that the frost wyrm, Glacion, who circles overhead is to be used for the offensive.\n\nSurely Mage-Lieutenant Malister would be of some assistance in this matter. Deliver the plans to him at the keep to the south.", objectives = "" }
WordHunterWoW_QuestEN[11238] = { title = "The Frost Wyrm and its Master", description = "You were right to bring this to me, {name}. You must venture to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile!\n\nEven now, as we speak here, the frost wyrm may be on its way.\n\nHowever, if I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd {name}, please bring me the horn. We wouldn't want it falling back into the wrong hands.", objectives = "" }
WordHunterWoW_QuestEN[11239] = { title = "In Service to the Light", description = "Your service has been exemplary, {name}, but there is something that is troubling me: the Scourge.\n\nThe Light cannot abide their presence, and neither shall we. I hope that it is not asking you too much, but I would have you return north to Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in the Waking Halls beneath Gjalerbron as well.\n\nPurification is the key to salvation, my child. Make us proud!", objectives = "" }
WordHunterWoW_QuestEN[11240] = { title = "Leader of the Deranged", description = "So, I hate to say it, pal, but while you were out, the captain took a keener interest in that place.\n\nLooks like he wants my old Explorers' League boss in there dead. My guess would be that we're gearing up for an offensive to clear out the rest of them, and the captain wants their head lopped off, as it were.\n\nDo me a favor? Head back into Whisper Gulch and put an end to Squeeg Idolhunter. From what I remember, my guess would be that he's in the cave in the northwest corner.", objectives = "" }
WordHunterWoW_QuestEN[11241] = { title = "Trail of Fire", description = "Thanks for bailing me out of this mess, {name}.  I was not looking forward to what these Alliance scumbags had in store for me.\n\nLet's get out of here and see if we can get back at them somehow.  Is that a campfire over there?", objectives = "" }
WordHunterWoW_QuestEN[11242] = { title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.", objectives = "" }
WordHunterWoW_QuestEN[11243] = { title = "If Valgarde Falls...", description = "If Valgarde falls, our primary supply line into Northrend will cease to exist. From there it'll only be a matter of time before we're all servants of the Lich King. Now I don't know about you, but I've got a wife and three kids back in Elwynn and I'll be damned if I'll go down without a fight.\n\nThe situation here is critical and we can use all the manpower you're able to muster. Get to the front gate and help the guards defend the city against the invading monsters!", objectives = "" }
WordHunterWoW_QuestEN[11244] = { title = "Rescuing the Rescuers", description = "We'd been here for a month when those malformed giants appeared out of thin air. We were ill-prepared for any sort of attack and paid dearly for our complacency. An entire archaeology team was lost and several townsfolk were abducted and taken to the ruins. We've been on the defensive ever since.\n\nTo make matters worse, the scouts we sent to rescue our people have been harpooned by the vrykul and left for dead in the forest directly north of Valgarde. Dislodge those harpoons and free our scouts!\n", objectives = "" }
WordHunterWoW_QuestEN[11245] = { title = "Towers of Certain Doom", description = "Sir, as we move through Skorn, we have to bring down those towers!\n\nIf you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom for us!\n\nHowever, we do have it within our means to call in cannon volleys from Westguard Keep. To do so, we need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't get too close!", objectives = "" }
WordHunterWoW_QuestEN[11246] = { title = "Gruesome, But Necessary", description = "We've had reports that these vrykul can rise from the dead; not unlike the Scourge, but a different kind of undeath.\n\nLet's not take any chances.\n\nHere, take my machete. As we move through this place, you'll need to carve up the remains of the vrykul that we take down. I'd do it, but I have a sensitive stomach.\n\n<The sergeant smirks.>\n\nI spent all morning sharpening it, so it should do the job.", objectives = "" }
WordHunterWoW_QuestEN[11247] = { title = "Burn Skorn, Burn!", description = "Captain Adams gave me strict instructions to make sure that a good deal of infrastructure damage was inflicted on this site.\n\nHowever, since you're in charge out here, that's at your discretion, sir.\n\nMay I suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn? All we have to do is get inside each and throw this torch.", objectives = "" }
WordHunterWoW_QuestEN[11248] = { title = "Operation: Skornful Wrath", description = "{name}, I must now ask you to undertake an operation so hazardous, so deadly, that only you can see it through.\n\nThe vrykul fortress, Skorn, sits on our eastern border. My scouts inform me that those 'giants' are poised to strike us, and with my forces scattered all over the fjord, I don't have the men to take the place by force.\n\nInstead, you're going to use your cunning. I've sent a sergeant ahead with the details. Show this command insignia at Skorn and he'll reveal himself and follow your orders.", objectives = "" }
WordHunterWoW_QuestEN[11249] = { title = "Stop the Ascension!", description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.", objectives = "" }
WordHunterWoW_QuestEN[11250] = { title = "All Hail the Conqueror of Skorn!", description = "We -- well, you -- have done everything that we were sent here to accomplish sir. I must say that it's been a pleasure taking orders from such a fine, young {race}.\n\nThe captain is sure to want to hear of your success, but if you decide to stay out here for whatever reason, I am at your disposal.", objectives = "" }
WordHunterWoW_QuestEN[11251] = { title = "Fresh Legs", description = "It's come at great cost, but we've completed our inspection of the site.\n\nThe news isn't good. Nearly everyone has been slain or captured. Only a few veteran guards remain unaccounted for.\n\nThe scouts have done all we can here. You must pick up where we've left off.\n\nSounds of a skirmish are coming from up the hill to the northeast. Have a look, {class}. We can only hope there are some who have survived, and that they may have some intel we can use against this enemy.", objectives = "" }
WordHunterWoW_QuestEN[11253] = { title = "Sniff Out the Enemy", description = "Now that this rascal's belly's full, maybe he will be more willing to cooperate.  Here's his leash, just come get him from his cage whenever you're ready to take him.\n\nI don't know what Anselm expects you to find, but look for clues wherever it is that the dog takes you.", objectives = "" }
WordHunterWoW_QuestEN[11254] = { title = "The Dragonskin Map", description = "Upon closer inspection, the scroll appears to be a heavily-illustrated map of the fjord.  The location of various villages are depicted in what seem to be tribal symbols.\n\nThe location of Vengeance Landing is marked with a disproportionately large skull.\n\nThis map will almost certainly be of military value to High Executor Anselm.", objectives = "" }
WordHunterWoW_QuestEN[11255] = { title = "Prisoners of Wyrmskull", description = "This battle is far from over, {name}. If our people are still alive inside that village, someone has to go and get 'em.\n\n<Vice Admiral Keller nods at you.>\n\nHead north and enter Wyrmskull Village. Once there, look for our people. If they are imprisoned you'll need to find a way to break them out.\n\nMaybe they'll have some more information about what it is that we're actually fighting.", objectives = "" }
WordHunterWoW_QuestEN[11256] = { title = "Skorn Must Fall!", description = "{name}, the vrykul fortress, Skorn, sits to the south. Its strange giants have recently awakened and have begun to spread, attacking us wherever they can.\n\nMy scouts inform me that they are poised to strike at us here, but I do not have the strength to repel such a force. Instead, we will prepare to leave north to less dangerous lands.\n\nI ask that you use your cunning to buy us time. I've sent a brave ahead with the details. Show this emblem at Skorn and he'll reveal himself and do all he can to aid you.", objectives = "" }
WordHunterWoW_QuestEN[11257] = { title = "Gruesome, But Necessary", description = "Our elders say that these vrykul may be able to rise from the dead; not unlike the walking dead you call the Scourge, but a different kind of undeath.\n\nWe should not take any chances.\n\nHere, take my machete. As we move through this place, carve up the remains of the vrykul that we slay.\n\nI spent the morning sharpening it, so it should cleave even through their thick bones.", objectives = "" }
WordHunterWoW_QuestEN[11258] = { title = "Burn Skorn, Burn!", description = "Chieftain Ashtotem ordered me to destroy many buildings here.\n\nHowever, you are in charge, so it falls to your hands, {name}.\n\nI suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn. All we have to do is get inside each and set them ablaze with this torch.", objectives = "" }
WordHunterWoW_QuestEN[11259] = { title = "Towers of Certain Doom", description = "As we move through Skorn, we must destroy the towers.\n\nIf you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom.\n\nHowever, we can call in wind rider air strikes from Camp Winterhoof. To do so, we need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't get too close.", objectives = "" }
WordHunterWoW_QuestEN[11260] = { title = "Stop the Ascension!", description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.", objectives = "" }
WordHunterWoW_QuestEN[11261] = { title = "The Conqueror of Skorn!", description = "You have done everything that we were sent here to do, {class}. I must admit that you fight well. Your people are not as strange as I first thought.\n\nChieftain Ashtotem is certain to want to hear of your success, but if you decide to stay out here for whatever reason, I will continue to fight at your side.", objectives = "" }
WordHunterWoW_QuestEN[11262] = { title = "Ingvar Must Die!", description = "Of our entire recon party, only I remain.\n\nThese vrykul are relentless fighters. Given their numbers and their savage tactics, our only hope is to bring down their leader and pray it brings chaos to their ranks.\n\nIngvar is his name. Bring me his head!", objectives = "" }
WordHunterWoW_QuestEN[11263] = { title = "Dealing With Gjalerbron", description = "My longrunners that have lived to return have informed me that the vrykul have awakened at their main fortress to the west.\n\nIt is a forbidden place known as Gjalerbron. The longrunners tell me that the vrykul are performing strange rituals.\n\nWe cannot allow this to continue.\n\nAre you willing to continue to assist us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing and attack us here?", objectives = "" }
WordHunterWoW_QuestEN[11264] = { title = "Necro Overlord Mezhen", description = "The dead ones are at Gjalerbron and they have necromancers with them?\n\nWe must eliminate the leader of these necrolords.\n\nDo whatever it takes, {name}, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nWe cannot afford to see the vrykul successful in whatever they are doing with these undead creatures!\n\nLook for Mezhen on the platform in the rear right section of Gjalerbron.", objectives = "" }
WordHunterWoW_QuestEN[11265] = { title = "Of Keys and Cages", description = "From the little we know, the vrykul are conducting unnatural rites in an 'awakening' ritual to the west in Gjalerbron.\n\nThey're using living sacrifices to fuel their rituals.\n\n{name}, you must stop this. It matters not who or what is in those cages, they must be freed. I would guess that the vrykul hold the keys.\n\nThe last thing we need is more of those strange vrykul threatening us, or worse, them wakening something even more evil....", objectives = "" }
WordHunterWoW_QuestEN[11266] = { title = "Gjalerbron Attack Plans", description = "These plans detail an imminent attack upon Camp Winterhoof. It would appear that the frost wyrm, Glacion, who circles overhead, is to be used for the offensive.\n\nSurely Celea Frozenmane would be of some assistance in this matter. Deliver the plans to her at the camp to the east.", objectives = "" }
WordHunterWoW_QuestEN[11267] = { title = "The Frost Wyrm and its Master", description = "Your instincts were right to bring this to me, but my wind riders cannot fight a dragon. You must venture west to Gjalerbron and slay the frost wyrm and its master, Wyrmcaller Vile!\n\nEven now it may be on its way!\n\nIf I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd {name}, bring me the horn. We wouldn't want it falling back into the wrong hands!", objectives = "" }
WordHunterWoW_QuestEN[11268] = { title = "The Walking Dead", description = "Your assistance to us has been tremendous, {name}, but there is something that is troubling me: these so-called Scourge.\n\nThe spirits of the land and air, the waters and the fire below the world, would not abide their presence, but seem to do nothing about them. We will see to it that they are dealt with!\n\nPerhaps it is asking too much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!", objectives = "" }
WordHunterWoW_QuestEN[11269] = { title = "Down to the Wire", description = "The vanguard of the Alliance force will be arriving within days. The soldiers will be expecting their winter gear to be prepared, but I've still got more cloaks to make.\n\nI've been using spotted hippogryph down for the cloaks' linings, but my stock won't last!\n\nYou've got to help me, {name}. Captain Adams will have my hide if those cloaks aren't ready in time! Bring me all the down you can find out there. It's dropped to the ground by molting hippogryphs flying over the wilderness around the fort.", objectives = "" }
WordHunterWoW_QuestEN[11270] = { title = "War is Hell", description = "We're slowly finishing off the remnants of Stormwind's North Fleet stationed on this coast.  The bodies to the west are a testament to how brutal this confrontation has been.\n\nThis does not happen to bother my refined aesthetics, but it does present a danger to our lives.\n\nIn the lands of the Lich King, the dead are a weapon that can rise against us at any point in time.  Take this torch - you're going to make sure that doesn't happen.", objectives = "" }
WordHunterWoW_QuestEN[11271] = { title = "Hasty Preparations", description = "The down of the spotted hippogryph is prized by my people and used for everything from fletching to ceremonial clothing. We're making preparations to leave the post, so this is the last chance I'll get to gather it this season.\n\nWith your help, I'll have enough to make sure everyone has the equipment they need for the long trek into the hills. Conditions worsen very quickly up there and a storm can blow in without warning.\n\nThe down can be found all over the ground in the area surrounding the post.", objectives = "" }
WordHunterWoW_QuestEN[11272] = { title = "A Score to Settle", description = "This elf prince thinks he can come to my town, insult my queen, kill my men and get away with it? He thinks we're going to stand by while the hordes of Utgarde build up to launch an attack?\n\nNot in a million years.\n\nYou're going to walk right into Utgarde and kill him. I want Arthas to know that we've arrived and we're playing for keeps.\n\nReport to Dark Ranger Marrah inside Utgarde Keep when the deed is done and she'll tie up any... loose ends.", objectives = "" }
WordHunterWoW_QuestEN[11273] = { title = "The Human League", description = "We were on the brink of an archaeological breakthrough when those monsters attacked! Sadly, I was the only one to make it back to Valgarde. Now I don't know if my crew is dead or alive, but the artifacts we uncovered on that dig must be found!\n\nIf you're heading into Wyrmskull Village, will you keep an eye out for my team? If there's any hope of recovering that information, we must pursue it!\n\nSearch for Pulroy first. He was the last one I saw before I made my escape.", objectives = "" }
WordHunterWoW_QuestEN[11274] = { title = "Zedd's Probably Dead", description = "To whomever finds this journal:\n\nThese bloodthirsty monsters have taken up residence in the ruins of Wyrmskull. What they want or why they're here is a mystery. In any case, the artifacts are not safe with those beast-men around.\n\nZedd and I made a new discovery while hiding out: a cipher to decode the tablets! Unfortunately Zedd and I were separated late last night. He had the cipher. Tablets were with Glorenfeld and Daegarn. Location unknown...\n\nFind Zedd.\n\n-Pulroy", objectives = "" }
WordHunterWoW_QuestEN[11275] = { title = "Making the Horn", description = "My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever.\n\nTo prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts.\n\nBring me the best dire ram horns you can find, {name}, and I'll select one from among them.", objectives = "" }
WordHunterWoW_QuestEN[11276] = { title = "And Then There Were Two...", description = "There's no sign of the cipher on Zedd. After carefully searching the area you discover some writing in the dirt:\n\n\"Glor and Dae inside catacombs. Have cipher and tablets.\"\n\nPerhaps you should head into the catacombs located just north of here and search for Glorenfeld and Daegarn. The bridge crossing the worg pit will lead you right to the tunnel leading down into the catacombs.", objectives = "" }
WordHunterWoW_QuestEN[11277] = { title = "The Depths of Depravity", description = "They're keepin' Daegarn locked up in a cage at the large fightin' ring nearby. From what I've gathered, the Dragonflayers bring out their prisoners to battle against their most powerful gladiators. They dump the losers in the basement where Scourge necromancers turn 'em into ghoulies! It's horrifying!\n\nBut first things first! The tablets are strewn about all across this dungeon. Let's get those recovered before you go off tryin' to be a hero.", objectives = "" }
WordHunterWoW_QuestEN[11278] = { title = "Return to Valgarde", description = "'Tis a shame we lost two of our best dwarves while uncovering these relics. They sacrificed their lives to keep this information safe.\n\n<Glorenfeld wraps the cipher and tablets in a tattered cloth.>\n\nTake these back to Valgarde. McSorf will know what to do with the find.\n\nAs for me? I'll be alright on my own. I've gotten this far in one piece!", objectives = "" }
WordHunterWoW_QuestEN[11279] = { title = "Green Eggs and Whelps", description = "This new plague that we're working on is wonderful and I think we should expand its testing.\n\nHow about testing it on proto-whelps?!\n\nJust think of the possibilities. The ability to infect not only humanoids, but extend our reach to any creature!\n\nHere, I've hoarded an extra plague canister for the right time and place, and you look like the right person.\n\nSpray the eggs at Ember Clutch to the northwest, then get specimens from the plagued proto-whelps that hatch.", objectives = "" }
WordHunterWoW_QuestEN[11280] = { title = "Draconis Gastritis", description = "Wait, that gives me an idea! What if it didn't kill the whelps because it was sprayed on the outside of their eggs?\n\n{name}, we have to get the plague inside of them!\n\nI know! I've got some plagued meat here. Take it to the Ember Clutch and get them to eat it!\n\nBut no, we're thinking too small. Let's get one of the proto-drakes flying overhead to come down and eat it.\n\nYes!\n\nStay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.", objectives = "" }
WordHunterWoW_QuestEN[11281] = { title = "Mimicking Nature's Call", description = "The horn has been roughed out, but before I make the traditional carvings, I want to be certain that it will work. Ahota tells me that he tests his horns at the foot of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters have used the acoustics of frozen water in this way for generations. I can't wait to learn more!\n\nWill you help me test out the horn? If I've done everything right, you may even attract a yeti, so be prepared! Bring the horn back once you've tested it. ", objectives = "" }
WordHunterWoW_QuestEN[11282] = { title = "A Lesson in Fear", description = "When you've been in lots of fight like Gorth, you learn that to beat enemy good you have to make them really scared to die!\n\nBut these vrykuls not afraid.  You kill one and another comes... screaming louder and with a bigger weapon than the one before.\n\nOnly thing that makes vrykuls afraid is when we kill the biggest and baddest vrykul of all.\n\nGo fight the Winterskorn across the blockade until hero vrykuls show up!  Then you kill them dead and put queen's flag on corpses.  They must learn to fear!", objectives = "" }
WordHunterWoW_QuestEN[11283] = { title = "Baleheim Bodycount", description = "Them vrykuls just keeps coming and coming out from town west of here.  No end in sight!\n\nGorth has an idea.  You go INSIDE town and kill them Winterskorn there.  THEN they stop coming here!", objectives = "" }
WordHunterWoW_QuestEN[11284] = { title = "The Yeti Next Door", description = "Maybe if the sentries won't help me, you will? I'm the foreman of the mine just across the bridge. My men are mining ore for the weapons our expeditionary force will need to carve a path into the Grizzly Hills.\n\nA giant yeti has invaded the mine, blocking the tunnel we need to expand! We've tried yelling at him and smoking him out, but nothing's worked.\n\nMaybe you could rouse it from its sleep with a meal of meat from the frosthorn rams in the snowy areas around town? Please? We're desperate!", objectives = "" }
WordHunterWoW_QuestEN[11285] = { title = "Baleheim Must Burn!", description = "Killing the Winterskorns maybe not enough.  Maybe we burn their houses too!  Uh... and their bridges.  We should burn whole town to be safe!\n\nYou take this torch.  Go to Baleheim, to the west, and burn EVERYTHING!  That teach them good.", objectives = "" }
WordHunterWoW_QuestEN[11286] = { title = "The Artifacts of Steel Gate", description = "I came out here for a different reason; an old friend of mine has been calling to me in my dreams. But now that I see these small things with their machines making a big hole in the ground, it makes my blood boil.\n\nFrom what I can see, these dwarves, as they are known, are digging up artifacts; artifacts that could be important to our past.\n\nI want you to go down there and get these things for me. Don't let any of those dwarves stand in your way.", objectives = "" }
WordHunterWoW_QuestEN[11287] = { title = "Find Sage Mistwalker", description = "{class}, I grow worried that my son, Sage Mistwalker, has been gone for such a long time. The land is cruel and deadly.\n\nHe spoke of a recurring vision that he had of a wolf, and went west with a small group of longrunners to seek its source. I believe the name of the place he mentioned was Steel Gate.\n\nWill you find him? I want to make sure that no ill has befallen him.", objectives = "" }
WordHunterWoW_QuestEN[11288] = { title = "The Shining Light", description = "<Ares gasps for air as he tries to speak.>\n\nI am an envoy of the Argent Crusade, charged with a sacred duty.\n\nOur forces were decimated in the Plaguelands. By the light of dawn, the artifact was cleansed and made pure once more. So many perished in the wake of its redemption.\n\nThere is still a chance... still time.\n\nThe artifact was hurled into the den of the fallen, far below us. Guarded by the unmerciful dead.\n\n<Ares' body glows with blinding light.>\n\nLight. Will. Protect. You.\n", objectives = "" }
WordHunterWoW_QuestEN[11289] = { title = "Guided by Honor", description = "<Ares smiles.>\n\nGlory to the Light. You have done it!\n\n<Ares coughs.>\n\nTake the artifact and return it to Valgarde. Lord Irulon Trueblade awaits its return.\n\nFight with honor, friend. Always. Honor.\n\n<Ares dies.>", objectives = "" }
WordHunterWoW_QuestEN[11290] = { title = "Dragonflayer Battle Plans", description = "While we were able to gather very little information as to the whereabouts of Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull Village.\n\nIntelligence gathered from the rescued soldiers indicates that Yanis guards Dragonflayer battle plans.\n\nI need you to go back to Wyrmskull and recover those plans. Kill any vrykul that get in your way - including Yanis!", objectives = "" }
WordHunterWoW_QuestEN[11291] = { title = "To Westguard Keep!", description = "<Vice Admiral Keller rolls up the battle plans.>\n\nWe've got all the information we need to keep Valgarde protected. You must take these battle plans to Westguard Keep, located on the western fjord cliff wall. Speak with the flight master assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards Westguard.\n\nOnce there, find Captain Adams. He's the one in charge. Adams will know what to do with these plans.", objectives = "" }
WordHunterWoW_QuestEN[11292] = { title = "Preying Upon the Weak", description = "Glad to meet you. I've come here from the Grizzly Hills to do business with your cohorts. My people maintain a large outpost there, and you'd do well to visit it when you head north.\n\nI've set up traps in the woodlands and snowy areas around here. With the meat and the furs from the creatures they capture, I'll have plenty to barter with the townspeople.\n\nI can offer you a share of my profits if you're willing to help gather prey from the traps. Beware though, you won't be the only predator out there.", objectives = "" }
WordHunterWoW_QuestEN[11293] = { title = "Bark for the Barleybrews!", description = "We need to get the word out about the Barleybrews at Brewfest.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.  I'll make things easy though, I'll lend you a racing ram for 4 minutes.  Use the reins to let him go, but try not to tire him out.", objectives = "" }
WordHunterWoW_QuestEN[11294] = { title = "Bark for the Thunderbrews!", description = "It's time to let people know that the Thunderbrew have heard their cries for good brew.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.\n\nWe'll make it easy though.  We'll lend you a ram for 4 minutes.\n\nBe careful with going too fast though since you won't find any apple crates in Ironforge...  We can't take the chance of helping out the Barleybrew messengers.", objectives = "" }
WordHunterWoW_QuestEN[11295] = { title = "The Offensive Begins", description = "No one seems to know very much about the vrykul.  Our records show no signs of activity in their lands for centuries.  Yet here they are, just as we move against Arthas.\n\nThe map you retrieved makes it clear that we'll have to defeat them if our forces are to get any further into Northrend.\n\nOne of my best sergeants, an abomination known as Gorth, oversees the blockade beyond the lift.  Assist him in launching a pre-emptive strike on Baleheim.  If a vrykul attack occurs, it will be launched from there.", objectives = "" }
WordHunterWoW_QuestEN[11296] = { title = "Rivenwood Captives", description = "Something, most likely the walking dead known as the Scourge, has agitated the creatures hereabouts.\n\nWhile escorting the sage here, we lost most of our hunting force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the north.\n\nI must stay here to protect the small force we have left, but you... you could see if my longrunners are still alive, trapped within the riven widow's cocoons.\n\nWould you do this, stranger?", objectives = "" }
WordHunterWoW_QuestEN[11297] = { title = "Keeping Watch on the Interlopers", description = "Even the earth cannot hold back the tide of death washing over it. Corpses walk the land, spreading their putrefaction with alarming speed.\n\nA small expedition has made its way up the western cliffs and rests near Whisper Gulch. Take a look for yourself, {name}. See if you can learn their purpose and dissuade them from bringing their poisons into our lands. Travel southwest from the post, toward the cliffs overlooking the western beach. Their camp will be west of the excavation at Steel Gate.", objectives = "" }
WordHunterWoW_QuestEN[11298] = { title = "What's in That Brew?", description = "To the southeast is an area called Whisper Gulch. It's overrun with members of the Explorers' League who've gone mad! They attacked our caravan as it passed through the area, and they've harried our foraging parties as well.\n\nI must know what's causing this madness! I suspect that whatever they're drinking from the kegs scattered around the gulch contributes to their insanity. I want you to steal the kegs from those dwarves while they're busy mining away.", objectives = "" }
WordHunterWoW_QuestEN[11299] = { title = "The Ring of Judgment", description = "You might have already seen the room where Daegarn is being held while you were gatherin' the tablets. It's through this corridor and then down a set of steps. Daegarn will be in the room at the bottom of the steps - locked up tight!\n\nGet down there and find him. At the very least you might be able to get the cipher from him.", objectives = "" }
WordHunterWoW_QuestEN[11300] = { title = "Stunning Defeat at the Ring", description = "Oluf will come out if you defeat the other gladiators. That's 'bout the only way we're getting' that cipher back. Put on your whompin' boots and get busy in the Ring of Judgment. If you do manage to get the cipher back, return it to Glorenfeld o'er near the entrance to these catacombs.\n\nMe? Don't worry about me! We're on the brink of discovering the missing link to human-kind!", objectives = "" }
WordHunterWoW_QuestEN[11301] = { title = "Brains! Brains! Brains!", description = "Has Malthus drawn you in with his blather about beer kegs and crazy dwarves?\n\nI'm not questioning that the dwarves are crazy, but I don't think stealing their beer is going to do any good.\n\nWhat we need is brains. Lots of brains. We'll get down to the bottom of this mystery in no time, and perhaps even find a new component for the plague.\n\nTake this saw, go southeast into the Whisper Gulch, and kill yourself some dwarves. Use the saw to help you harvest the brains and bring them back here.", objectives = "" }
WordHunterWoW_QuestEN[11302] = { title = "The Enigmatic Frost Nymphs", description = "When we first scouted locations for the fort, we encountered hostile creatures at two of the glades here in the north. When we passed the snow-covered one directly south of the town, the dryads there watched us with interest, but did not attack.\n\nWe were tired and worn down by the weather. They could've easily killed several of our men, but they didn't.\n\nPerhaps, in reaching out to them, we might discover unexpected allies. Are you willing to travel to the Frozen Glade and make contact with them?", objectives = "" }
WordHunterWoW_QuestEN[11303] = { title = "The Ambush", description = "The vrykuls in Baleheim is completely defeated, no doubt about it.  But still their leader stays in town and won't give up.\n\nGorth sends Lydell and his assassins to make good ambush to the northwest.  You talk to Lydell and figure out how to get Vrykul chieftain to come out.  Then you kill him.  You kill him real good.", objectives = "" }
WordHunterWoW_QuestEN[11304] = { title = "New Agamand", description = "I'm afraid our equipment isn't exactly the best here at Vengeance Landing.  After all it's a military controlled outpost.\n\nI will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do.\n\nYou must hurry, {name}.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!", objectives = "" }
WordHunterWoW_QuestEN[11305] = { title = "A Tailor-Made Formula", description = "We've been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won't drop dead.\n\nLet's face it, {name}, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul's biology.\n\nHalgrind's chieftain fled the town after we took it over; you'll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.", objectives = "" }
WordHunterWoW_QuestEN[11306] = { title = "Apply Heat and Stir", description = "You've done well so far, {name}.  I'd like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague.\n\nTake this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.", objectives = "" }
WordHunterWoW_QuestEN[11307] = { title = "Field Test", description = "Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind.  If all goes according to plan, they will disintegrate immediately as the plague devours their innards!\n\nYou will find Halgrind north of here.  Our plaguebringers are deploying the previous strain there - shouldn't be hard to spot.", objectives = "" }
WordHunterWoW_QuestEN[11308] = { title = "Time for Cleanup", description = "Being the practical man that I am, I'm going to declare our research here a success.  After all, what army can't be stopped by turning its rank and file against each other?\n\nI will send word of our achievements to Vengeance Landing soon enough.  But first I need you to take care of cleaning up our experimentation site.\n\nSee \"Hacksaw\" Jenny about making you a custom abomination.  One packing some explosive power if you catch my drift.", objectives = "" }
WordHunterWoW_QuestEN[11309] = { title = "Parts for the Job", description = "So Harris wants a demolition job, eh?  Yeah, I can help out.\n\nYou're gonna have to get me some parts, though.  I can't afford to use up my choice components on something that's gonna get blown up.\n\nFirst of all, I'm going to need shoveltusk ligaments... way better than the human kind.\n\nI will also need a pound of flesh.  A fellow known as Anton sells cheap meat.  He travels up and down the road to the west.", objectives = "" }
WordHunterWoW_QuestEN[11310] = { title = "Warning: Some Assembly Required", description = "Well, here you are!  Our friend's going to be somewhat... unstable.  So I suggest not putting him together until reaching Halgrind.\n\nOnce you're there, use the abomination to round up as many vrykul as you can before self-destructing.\n\nCome back with whatever's left once you're done.  I can always use more body parts!", objectives = "" }
WordHunterWoW_QuestEN[11311] = { title = "Suppressing the Elements", description = "If you are to survive here, as we have, you must learn to face the environment's challenges head on. The elements will claim your life if you're not vigilant, as the proliferation of elementals in these northern hills shows.\n\nWe must cull the elementals one last time before we can leave this place. Are you willing to aid us while we continue to make preparations?\n\nYou must kill any iceshard elementals or howling cyclones you encounter in the snowy hills surrounding the outpost.", objectives = "" }
WordHunterWoW_QuestEN[11312] = { title = "The Frozen Glade", description = "For generations, my people have told tales of frost nymphs cavorting in glades hidden away in the wilderness. I used to search for them as a child, against the advice of my parents, until I nearly froze to death.\n\nThese days, it isn't necessary to comb the forests for them. They've decided to reveal themselves for reasons I can only guess, but I don't think the change can be ignored. Venture southeast to the Frozen Glade and seek out the nymphs, but beware; you will pass the Twisted Glade on your way.", objectives = "" }
WordHunterWoW_QuestEN[11313] = { title = "Spirits of the Ice", description = "The ice elementals surrounding our glade were once our companions, but a volatile and destructive force has swept through the land, turning them against us!\n\nThis is but one of the horrors my sisters and I have endured. We have revealed ourselves to you in the hope that you will help us stave off the decay that has crept into our glades and poisoned our sisters!\n\nWe've been gathering the cores of the ice elementals and keeping them safe so that one day, we might be able to restore them. Will you help?", objectives = "" }
WordHunterWoW_QuestEN[11314] = { title = "The Fallen Sisters", description = "To the southwest was a glade that used to look much like this one. Mysterious forces and alien magics are reshaping the land. The glade has thawed, the sisters living there driven mad by the sudden change.\n\nWe thought to reach out to them, but they attacked us. I fear many may be beyond saving, but I cannot give up hope.\n\nTake my pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.", objectives = "" }
WordHunterWoW_QuestEN[11315] = { title = "Wild Vines", description = "The sisters who lived in the Vibrant Glade, to the southwest, used to tend to gorgeous beds of scarlet ivy, but the same force that has driven them mad has transformed their beloved ivy.\n\nThe vines now grasp at the feet of the unwary, or lash at any who approach the glade. Before we can reclaim the glade, the vines must be tamed and uprooted.\n\nClear as much of the ivy as you are able. It has already begun to grow out of control.", objectives = "" }
WordHunterWoW_QuestEN[11316] = { title = "Spawn of the Twisted Glade", description = "The glade to the west has been transformed into a hideous place called the Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the glade.\n\nI cannot guess where the creatures came from or what horrible forces animate them, but they must be dealt with!\n\nI fear that if they are allowed to dominate the glade, they will poison it beyond redemption. Clear the glade of these creatures who murdered our sisters.", objectives = "" }
WordHunterWoW_QuestEN[11317] = { title = "The Cleansing", description = "We braved the Rivenwood because of my troubled dreams concerning my worg life-friend, Ulfang. He has called out for help, and you must go to him.\n\nBut, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nFirst, you must cleanse your inner turmoil.\n\nThere is a shrine that sits at the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it from the western base of the mountain.\n\nMeditate there and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[11318] = { title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams? Well I hope you're ready for speed. BUT before I let you loose in the world, you'll need to show me that you can handle these fine creatures.\n\nSo here's the deal: I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each. If you need instructions how to handle the ram, talk to my apprentice, Pol Amberstill.", objectives = "" }
WordHunterWoW_QuestEN[11319] = { title = "Seeds of the Blacksouled Keepers", description = "The glade to the northwest, now the Twisted Glade, used to be home to a number of keepers of the glade. Together with the sisters, they saw to the glade's upkeep.\n\nWhen the glade changed, the sisters died, but somehow the keepers managed to survive. Now, they seed the land with poisonous spores that wither healthy greenery.\n\nI'll give you one of the cores from the ice elementals. Once you've destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.", objectives = "" }
WordHunterWoW_QuestEN[11321] = { title = "Did Someone Say \"Souvenir?\"", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", objectives = "" }
WordHunterWoW_QuestEN[11322] = { title = "The Cleansing", description = "Of late I've had nightmares concerning a worg named Ulfang. He has called out for help, and you must go to him.\n\nHowever, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nBut first, you must cleanse your inner turmoil through meditation.\n\nThere is a shrine that sits at the top of Frostblade Peak, far to the northeast. A single path leads up to it from the western base of the mountain.\n\nMeditate there to cleanse yourself and then return to me.", objectives = "" }
WordHunterWoW_QuestEN[11323] = { title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger.\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", objectives = "" }
WordHunterWoW_QuestEN[11324] = { title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Mistwalker that I am once more the alpha worg!", objectives = "" }
WordHunterWoW_QuestEN[11325] = { title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger!\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", objectives = "" }
WordHunterWoW_QuestEN[11326] = { title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Moonleaf that I am once more the alpha worg!", objectives = "" }
WordHunterWoW_QuestEN[11327] = { title = "Mission: Package Retrieval", description = "Well darn, we need some of that plague-stuff.\n\nI know!\n\nWhile you were destroying the vats, I happened to spy one of the apothecaries from New Agamand being pulled into Halgrind by the vrykul down in there. Poor fella'.\n\n{name}, I'd bet anything that apothecary has the goods on him. Think you could go into Halgrind and retrieve his package?", objectives = "" }
WordHunterWoW_QuestEN[11328] = { title = "Mission: Forsaken Intel", description = "Right, so I think you should get this stuff over to Peppy Wrongnozzle back at the keep. She's something of an amateur alchemist, but she's the only one we've got.\n\nOne thing about Peppy; she does love her drink. So, you'll likely find her at the tavern 'soaking up the atmosphere'.\n\nI'm sure she'll know what to do.", objectives = "" }
WordHunterWoW_QuestEN[11329] = { title = "I'll Try Anything!", description = "I never want to see another barrel of salted fish as long as I live! Filling barrels day in and day out, and there are still more to be filled!\n\nI wish I hadn't used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I'm lucky if I can catch a fish an hour!\n\nI hear the northern barbfish make pretty good bait, but who's crazy enough to dive into a freezing cold lake and hack up the water plants in search of them? Not me... but maybe, just maybe, I can persuade you to...", objectives = "" }
WordHunterWoW_QuestEN[11330] = { title = "Absholutely... Thish Will Work!", description = "Voila, inshtant plague vacshine!\n\nBut I sure as heck am not going to try thish on myself. And I know you don't want to be my tesht shubject!\n\nOh, I've got... I've got an idea!\n\nWe've got a vrykul prishoner being held down in the cells under the keep. Why don't you take thish mix I whipped up down there, and get that giant to drink it ...hic?!", objectives = "" }
WordHunterWoW_QuestEN[11331] = { title = "You Tell Him ...Hic!", description = "Here'sh the deal. I'm not going to the captain with thish news. I'm an amateur alchemist, thish ishn't my job, and I'm on break!\n\nBeshides, he'sh a big grumpkin... and you know him better than I do!\n\nSho, jusht go up into the keep and tell him. I'm sure he'll be reashonable about the whole thing ...hic.\n\n<Peppy turns back to her drinking.>", objectives = "" }
WordHunterWoW_QuestEN[11332] = { title = "Mission: Plague This!", description = "The Royal Apothecary Society thinks they're going to perfect a new plague to melt us down where we stand?!\n\nNot on my watch!\n\nGet out to the courtyard and speak with Greer Orehammer. He's got a gryphon and some bombs ready for you. I want you to bomb the plague tanks at New Agamand to smithereens!", objectives = "" }
WordHunterWoW_QuestEN[11333] = { title = "Into the World of Spirits", description = "While the Explorers' League may discern bits and pieces of the past through their archaeological findings and the Vice Admiral might extract some knowledge of the present through brute force, the truth lies with the spirits.\n\nWith the proper reagents I am able to see into the spirit world. It is there that the past, present and future of Northrend resides.\n\nIf you wish to learn more, I will require my reagent pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of here.", objectives = "" }
WordHunterWoW_QuestEN[11334] = { title = "He Shoots, He Scores!", description = "[PH] Shoot a marked target.", objectives = "" }
WordHunterWoW_QuestEN[11343] = { title = "The Echo of Ymiron", description = "The spirit world has fallen under the sway of the Lich King. Fearsome creatures made of pure nightmare now stand watch over the realm of the elements. I sense that these val'kyr are guarding a terrible secret.\n\nI am too old and weak to survive another journey. You must go in my place, {name}.\n\nTake this incense burner to Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the northeast! Avoid the val'kyr at all costs lest they make you a permanent fixture in their world.", objectives = "" }
WordHunterWoW_QuestEN[11344] = { title = "Anguish of Nifflevar", description = "All that we know of the vrykul indicates that they only recently appeared in Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? Surely if the vrykul had previously existed in Northrend we would have known.\n\nYou must press on to Nifflevar. To get there you must go northeast, through Wyrmskull Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the fjord.\n\nUse the incense burner once you arrive at Nifflevar and search the area for clues.", objectives = "" }
WordHunterWoW_QuestEN[11345] = { title = "Prizes for Pellets", description = "[PH] Shoot a marked target.", objectives = "" }
WordHunterWoW_QuestEN[11346] = { title = "The Book of Runes", description = "The vast rocky area to the southeast, Giants' Run, has been overrun by Iron Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, then carving runes on them.\n\nI can't fathom their motives, but I suspect they're somehow trying to turn the giants into weapons. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me, {name}.", objectives = "" }
WordHunterWoW_QuestEN[11348] = { title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", objectives = "" }
WordHunterWoW_QuestEN[11349] = { title = "Mastering the Runes", description = "I've got a set of picks, hammers, and chisels with me, but they won't work for carving these runes. The tools used by the Iron Dwarves are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nI believe I know how it works, but without a set of those tools, I can't be certain. Look for kits resembling mine near the Iron Dwarf pavilions at Giants' Run and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[11350] = { title = "The Book of Runes", description = "Chieftain Ashtotem dispatched me on a scouting mission to Giants' Run, a broad, rocky plateau to the southeast, past the Frozen Glade.\n\nThe area has been taken over by Iron Dwarves who seem to be altering the giants as they emerge from the earth.\n\nThe iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me. It's the only way we'll understand their plans.", objectives = "" }
WordHunterWoW_QuestEN[11351] = { title = "Mastering the Runes", description = "I think I've figured out what the Iron Dwarves are doing. The tools they use are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nIf I had a set of those tools, I could mimic the runes in the book. I captured one of these boxes from one of the pavilions at Giants' Run, but it was empty. Look for similar boxes and recover a set of tools from them.", objectives = "" }
WordHunterWoW_QuestEN[11352] = { title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", objectives = "" }
WordHunterWoW_QuestEN[11354] = { title = "WANTED: Nazan's Riding Crop", description = "Today I have a buyer who is interested in a piece that's held by the mount of Illidan's herald. I, of course, speak of Vazruden the Herald and his dragon mount, Nazan.\n\nIf you want the finder's fee that I offer in return, find them flying above the Ramparts at Hellfire Citadel and return with the dragon's riding crop.\n\nMy sources tell me that the item in question is personally held by the dragon. It is said that Nazan refuses to allow Vazruden to strike him with it.", objectives = "" }
WordHunterWoW_QuestEN[11355] = { title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. What their ultimate destination is, I do not know.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey.\n\nUse this pick to deactivate the runes on the giants' corpses and return with your findings.", objectives = "" }
WordHunterWoW_QuestEN[11356] = { title = "Costumed Orphan Matron", description = "During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages.  Those poor children would love to see a real {class} like yourself!\n\nWhy don't you visit them?  You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst.  Speak to the children's ward, a costumed orphan matron, and she'll introduce you to the children.", objectives = "" }
WordHunterWoW_QuestEN[11357] = { title = "Masked Orphan Matron", description = "For Hallow's End, several orphans were taken on a trip to different Horde villages. The orphan matrons thought it would be good for them to see real heroes adventuring in the field.\n\nWhy don't you visit them? A brave {class} like yourself could strengthen their spirits with tales of your valor! Go to Razor Hill in Durotar, Brill in Tirisfal Glades, or Falconwing Square in Eversong Woods. Speak with the masked orphan matron and she'll introduce you to the children.", objectives = "" }
WordHunterWoW_QuestEN[11358] = { title = "The Lodestone", description = "If we can locate what's luring the giants northwest, we might be able to stop them before they reach their destination.\n\nAlthough I was able to decipher many of the runes on the samples you brought me, the ones I don't know concern me the most. When I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn.", objectives = "" }
WordHunterWoW_QuestEN[11359] = { title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be the most powerful of the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. After the expeditionary force arrives, our soldiers will be able to isolate and defeat the remaining giants and oust their Iron Dwarf masters from their camps.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", objectives = "" }
WordHunterWoW_QuestEN[11360] = { title = "Fire Brigade Practice", description = "With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?\n\nNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", objectives = "" }
WordHunterWoW_QuestEN[11361] = { title = "Fire Training", description = "The grunts set up a fire training area outside the village. These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter!\n\nHead west out of Razor Hill, then turn right as you pass the village's wall. Find the training area, then grab buckets and toss them on the practice fires.", objectives = "" }
WordHunterWoW_QuestEN[11362] = { title = "WANTED: Keli'dan's Feathered Stave", description = "There is no accounting for taste. Take my most recent buyer for instance.\n\nThere is a blood orc within Hellfire Citadel known as Keli'dan the Breaker. He bears a most mundane stave; certainly nothing to take a second glance at. And yet, this is what my customer wishes.\n\nWho am I to say no?\n\nIf you desire my compensation, you will find him and his stave within the Blood Furnace.", objectives = "" }
WordHunterWoW_QuestEN[11363] = { title = "WANTED: Bladefist's Seal", description = "Today I have a very wealthy collector in need of something very unique indeed.\n\nWarchief Kargath Bladefist carries upon his person his seal of command, which he uses to sign all official documents. I want you to retrieve it for me.\n\nYou will find him deep within the Shattered Halls. No doubt you will have to wade through a veritable army to get to him. I have no doubt that you will succeed.", objectives = "" }
WordHunterWoW_QuestEN[11364] = { title = "WANTED: Shattered Hand Centurions", description = "Do you question your master? Neither does Mah'duun.\n\nThe blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel.\n\nIf you want the bounty, you will not return until you have slain them all.", objectives = "" }
WordHunterWoW_QuestEN[11365] = { title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. I know nothing of their goals, nor of their destination.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey. Fell some of these giants.\n\nTake this pick with you and use it on the corpses of the runed stone giants. It will deactivate the runes. Once you've tested enough giants, return to me with your findings.", objectives = "" }
WordHunterWoW_QuestEN[11366] = { title = "The Lodestone", description = "We must find what's luring the giants northwest, so we can stop them before they reach their destination.\n\nWhile the rune samples gave us some clues, the unknown runes worry me.\n\nWhen I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn about the identity of this lodestone.", objectives = "" }
WordHunterWoW_QuestEN[11367] = { title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be a kind of keystone for the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and dedicate them to eliminating the last of the runed giants. Without their giants, the Iron Dwarves cannot stand against us.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", objectives = "" }
WordHunterWoW_QuestEN[11368] = { title = "WANTED: The Heart of Quagmirran", description = "I have an unusual request. A certain wealthy individual that I am in contact with off-world is interested in a macabre piece.\n\nSpecifically, she wants the heart of Quagmirran.\n\nI hear that the beast has three, but one will suffice for our purposes. As I understand it, you can find Quagmirran resting within a deep pool of water at the Slave Pens.", objectives = "" }
WordHunterWoW_QuestEN[11369] = { title = "WANTED: A Black Stalker Egg", description = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies.\n\nI have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction.\n\nIf you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.", objectives = "" }
WordHunterWoW_QuestEN[11370] = { title = "WANTED: The Warlord's Treatise", description = "While it is known that Warlord Kalithresh of the naga is a great warrior in his own right, there are fewer who know that he has codified all of his knowledge.\n\nOne of my customers is aware of it though, and is keenly interested in obtaining his treatise.\n\nI ask that you travel to the Steamvault in Coilfang Reservoir and obtain this book for me.", objectives = "" }
WordHunterWoW_QuestEN[11371] = { title = "WANTED: Coilfang Myrmidons", description = "Mah'duun hears and obeys, and I now ask you to be my instrument.\n\nIt has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir.\n\nI will accept nothing less than their utter annihilation.", objectives = "" }
WordHunterWoW_QuestEN[11372] = { title = "WANTED: The Headfeathers of Ikiss", description = "I've recently been approached by a tauren whose husband is about to be elevated to chieftain. She wishes to make a special addition to his headdress.\n\nSpecifically, she wants to obtain the headfeathers from the dastardly Talon King Ikiss.\n\nIf you are interested in collecting my reward, travel to Auchindoun's Sethekk Halls and find him.", objectives = "" }
WordHunterWoW_QuestEN[11373] = { title = "WANTED: Shaffar's Wondrous Pendant", description = "Today I have a personal request of you, yet the reward will certainly match the danger.\n\nMy family has a 'history', shall we say, with Nexus-Prince Shaffar and his followers. If the amulet he wears were to fall into my hands then surely that would mean that he had been dealt with.\n\nIf the bounty I am offering is of interest to you then journey to his lair within Auchindoun's Mana-Tombs.", objectives = "" }
WordHunterWoW_QuestEN[11374] = { title = "WANTED: The Exarch's Soul Gem", description = "Within Auchindoun's Auchenai Crypts many unsavory experiments are undertaken in the pursuit of a greater understanding of the necromantic arts. Many are the spirits that are tortured or destroyed therein.\n\nI have a customer who is interested in the liberation of one of those spirits. I have been informed that this spirit is contained within a soul gem held by none other than Exarch Maladaar himself.\n\nSeek him out within the crypts with all due haste and return to me with the gem.", objectives = "" }
WordHunterWoW_QuestEN[11375] = { title = "WANTED: Murmur's Whisper", description = "When I'm done speaking, you may not want to take this commission.\n\nI have an eccentric client who specializes in the study of dead realities. It is rumored that the being known as Murmur destroyed the last world from which he was summoned. The professor is interested in examining his 'whisper' as he called it to understand how it is that Murmur accomplished such a feat.\n\nWill you journey to the Shadow Labyrinth within Auchindoun and retrieve it for me?", objectives = "" }
WordHunterWoW_QuestEN[11376] = { title = "WANTED: Malicious Instructors", description = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth.\n\nGo to Auchindoun, seek them out, kill them all.\n\nIf you cannot accomplish so simple a task, we do not have anything further to say to one another.", objectives = "" }
WordHunterWoW_QuestEN[11377] = { title = "Revenge is Tasty", description = "I'm providing the catering for some unusual party guests tonight.  One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly.\n\nThey've requested something special for his get well party: Kaliri Stew.\n\nI can loan you my cooking pot so you can whip up a batch of stew for me.  The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.", objectives = "" }
WordHunterWoW_QuestEN[11378] = { title = "WANTED: The Epoch Hunter's Head", description = "The tastes of my customers range from the mundane to the exotic. And sometimes they want to do very mundane things with the exotic objects they seek.\n\nSuch is the case with my latest request. My client, who shall remain nameless, wishes to obtain the head of the Epoch Hunter to mount on his wall.\n\n{class}, will you find a way to travel back in time to Old Hillsbrad and procure said head for my trophy-hunting patron?", objectives = "" }
WordHunterWoW_QuestEN[11379] = { title = "Super Hot Stew", description = "I'm trying to invent something with some real zing.  But to be honest, I'm more of an idea goblin these days.  I've lost my sense of adventure.\n\nBut you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other.\n\nI want you to take my beloved cooking pot and head out to Blade's Edge.  Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.", objectives = "" }
WordHunterWoW_QuestEN[11380] = { title = "Manalicious", description = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight.\n\nUnfortunately, mana berries are only found in the eco-domes of Netherstorm.  Just don't bother looking around Stormspire--it's picked clean.\n\nI could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!", objectives = "" }
WordHunterWoW_QuestEN[11381] = { title = "Soup for the Soul", description = "Death is in the air.  I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul.\n\nAnd I know a fellow cook when I see one!  Would you like to help me out and get a cut of the profits?\n\nHere, take my cooking pot, gather some clefthoof meat and I'll let you in on a little secret.  What makes my soup so good for the soul?  It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.", objectives = "" }
WordHunterWoW_QuestEN[11382] = { title = "WANTED: Aeonus's Hourglass", description = "I swear that some of my customers are crazy. There are possessions that you go after, and there are ones that you dare not even think of!\n\nMy current client is clearly over-the-top insane. He covets the hourglass that Aeonus holds.\n\nYes, you heard right, Aeonus of the Infinite Dragonflight!\n\nWho am I to argue since he's paying a king's ransom? So, ready to go to the Caverns of Time and travel to the Black Morass to retrieve it for me?", objectives = "" }
WordHunterWoW_QuestEN[11383] = { title = "WANTED: Rift Lords", description = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords. But, Mah'duun does not know exactly when.\n\nI know that does not make sense, but the voice on the winds was not more specific.\n\nTravel to the Black Morass through the Caverns of Time and the way shall be made clear.", objectives = "" }
WordHunterWoW_QuestEN[11384] = { title = "WANTED: A Warp Splinter Clipping", description = "Not long ago, I was approached by a kaldorei druidess with a touching request. And plenty of gold, of course!\n\nIt would appear that the forces of Darnassus wish to restore an ancient of the arcane known as Warp Splinter. The giant tree has been confused or corrupted, I'm not certain, but you'll find it inside of the Botanica at Tempest Keep.\n\nShe said that all they would need to regrow him was a small clipping.", objectives = "" }
WordHunterWoW_QuestEN[11385] = { title = "WANTED: Sunseeker Channelers", description = "It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today.\n\nThey are to be found within the Botanica at Tempest Keep.\n\nYou want the bounty, you kill the channelers.", objectives = "" }
WordHunterWoW_QuestEN[11386] = { title = "WANTED: Pathaleon's Projector", description = "I always assumed that Pathaleon the Calculator used magic to project his image across Outland. Apparently I was wrong.\n\nMy latest customer tells me that the blood elf uses a mechanical device for his communication with the leaders of Prince Kael'thas's special projects. As I understand it, he acquired it from the Zaxxis rebels in the Netherstorm.\n\nMy client wishes to obtain the projector. Why don't you pay Pathaleon a visit? He can be found within the Mechanar at Tempest Keep.", objectives = "" }
WordHunterWoW_QuestEN[11387] = { title = "WANTED: Tempest-Forge Destroyers", description = "There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled.\n\nGo to Tempest Keep, find the tempest-forge destroyers and destroy them.\n\nThen you may return to collect the bounty.", objectives = "" }
WordHunterWoW_QuestEN[11388] = { title = "WANTED: The Scroll of Skyriss", description = "Today's client seeks something truly unique.\n\nIt is said that Harbinger Skyriss is a servant of the Old Gods. It is also said that he carries a large scroll that contains their instructions for his domination of life in the universe on their behalf.\n\nMy current buyer wishes to get his hands on that scroll, nevermind that he won't be able to read the language upon it.\n\nTravel to Tempest Keep's Arcatraz and get it for me, will you, {class}?", objectives = "" }
WordHunterWoW_QuestEN[11389] = { title = "WANTED: Arcatraz Sentinels", description = "The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help.\n\nMah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels.\n\nAccomplish this and today's bounty is yours.", objectives = "" }
WordHunterWoW_QuestEN[11390] = { title = "I've Got a Flying Machine!", description = "Well, what are you waiting for, there's work to be done!\n\nHere's the keys to our flying machine. Grab three sacks of relics and haul them up to the crane platforms on the north and south sides of Steel Gate.  I'll mark them for you.\n\nHurry up! We haven't got all day!", objectives = "" }
WordHunterWoW_QuestEN[11391] = { title = "Steel Gate Patrol", description = "Eh? Yer back for another day's work?\n\nWell, alright, here's the keys. We don't need any haulin' today, so just keep an eye out for anything suspicious, okay?\n\nI've hooked her up with some rockets and a machine gun - just in case.", objectives = "" }
WordHunterWoW_QuestEN[11392] = { title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine.", objectives = "" }
WordHunterWoW_QuestEN[11393] = { title = "Where is Explorer Jaren?", description = "{name}, my betrothed, Jaren, went west with a small group of explorers to check into rumors of artifacts on the Chillmere Coast. But there are murloc down there, and I fear the worst has befallen them.\n\nSurely you have time to see if they're alright? There's a way down to the beach just to the southwest, though watch out for the worgs and other things lurking in the woods.", objectives = "" }
WordHunterWoW_QuestEN[11394] = { title = "And You Thought Murlocs Smelled Bad!", description = "Originally I came down here to investigate some rumors about artifacts to be dug up. I knew that there were murlocs along the coast here, but I never in a million years thought I'd see this.\n\n<The explorer pokes his head out to look around the tree.>\n\nThe Scourge are out there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, I think it's our duty to do something about this. Think you could take out a good chunk of those Scourge?", objectives = "" }
WordHunterWoW_QuestEN[11395] = { title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Explorer Jaren would like to have a look at this.", objectives = "" }
WordHunterWoW_QuestEN[11396] = { title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nWhat do you say, {name}? You up for it? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nIt's the least we can do to keep the Scourge from making more of their own kind.", objectives = "" }
WordHunterWoW_QuestEN[11397] = { title = "And You Thought Murlocs Smelled Bad!", description = "I came here to investigate a rumor about a Scourge presence nearby. I expected murlocs along the coast down below, but I never thought I'd see this!\n\nThe Scourge are down there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, we will not suffer them to create more of their kind, especially not from murlocs! There is a ramp down to the beach just northwest of the camp. See to it that you deal with the Scourge in a timely fashion!", objectives = "" }
WordHunterWoW_QuestEN[11398] = { title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Apothecary Anastasia would like to have a look at this.", objectives = "" }
WordHunterWoW_QuestEN[11399] = { title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nBrave enough to hazard another trip down there, {name}? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nHow can you refuse if it means less Scourge, especially ones made from murlocs?", objectives = "" }
WordHunterWoW_QuestEN[11400] = { title = "Brewfest Riding Rams", description = "If you show this hand stamp to Pol Amberstill, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", objectives = "" }
WordHunterWoW_QuestEN[11401] = { title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "" }
WordHunterWoW_QuestEN[11403] = { title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.", objectives = "" }
WordHunterWoW_QuestEN[11404] = { title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "" }
WordHunterWoW_QuestEN[11405] = { title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "" }
WordHunterWoW_QuestEN[11406] = { title = "Everything Must Be Ready", description = "When the expeditionary force moves north, Captain Adams expects everything to be ready at Fort Wildervar. The scouts and craftsmen there have been tasked with preparing the gear and rations for our men for the climb into the hills.\n\nThe captain's famous for his temper, so I want to send someone ahead to check on the preparations. Fort Wildervar is far to the northeast, beyond Skorn, up in the snow-covered areas near the border with Grizzly Hills. Find Gil Grisert there and make sure he is prepared.", objectives = "" }
WordHunterWoW_QuestEN[11407] = { title = "Bark for Drohn's Distillery!", description = "So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nWe'll lend you a racing ram for 4 minutes.\n\nBe careful though, the cheap goblins didn't put any apple crates along the way.", objectives = "" }
WordHunterWoW_QuestEN[11408] = { title = "Bark for T'chali's Voodoo Brewery!", description = "We need to spread the word about the trolls at Brewfest.  Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nBut I'll make it easy for ya, I'll lend you a racing ram for 4 minutes.\n\nBe careful though, the goblins didn't put any apple crates along the way.  They are cheap like that.", objectives = "" }
WordHunterWoW_QuestEN[11409] = { title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams? The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal: I'll lend you the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", objectives = "" }
WordHunterWoW_QuestEN[11410] = { title = "The One That Got Away", description = "The barbfish you brought should work well as bait for most fish, but I fear it'll attract a monster!\n\nWhen I first arrived, I put some of Nat Pagle's favorite bait on my hook and cast it into the water. A huge monster latched on, with giant teeth and icicles hanging from its fins!\n\nWould've pulled me into those icy waters if I hadn't cut the line! I can't use the new bait until ol' Frostfin's been dealt with. Use this bait near the sunken boat in the middle of the lake. He won't be able to resist!", objectives = "" }
WordHunterWoW_QuestEN[11411] = { title = "Camp Winterhoof", description = "In my travels as a courier, I've seen a number of strange denizens of the Howling Fjord, but one group stands out. From a distance, they look like tauren, but upon closer inspection, they're quite different -- sturdier and shaggier.\n\nI found one of their settlements far to the north, beyond Halgrind, Skorn, and the northern forests. Camp Winterhoof, it's called, and it sits in the foothills of Gjalerhorn near the border with Grizzly Hills. Make contact with them, and see if they might be of use to us.", objectives = "" }
WordHunterWoW_QuestEN[11412] = { title = "There and Back Again", description = "Am I glad you're here. We are in big trouble! There's been a brew accident on the road to Bladefist Bay, and kegs are no longer being transported. You gotta get us that brew!\n\nI'll put you on one of my racing rams and you follow the road to Bladefist Bay.\n\nOnce you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant. For now, all we want are 3 kegs. Do a good job and maybe we'll have another job for you.", objectives = "" }
WordHunterWoW_QuestEN[11413] = { title = "Did Someone Say \"Souvenir?\"", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "" }
WordHunterWoW_QuestEN[11414] = { title = "Brother Betrayers", description = "Watcher Moonleaf is from my dreams! If you are her friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha worg. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place called Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", objectives = "" }
WordHunterWoW_QuestEN[11415] = { title = "Brother Betrayers", description = "Mistwalker is from my dreams! If you are his friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", objectives = "" }
WordHunterWoW_QuestEN[11416] = { title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", objectives = "" }
WordHunterWoW_QuestEN[11417] = { title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", objectives = "" }
WordHunterWoW_QuestEN[11418] = { title = "We Call Him Steelfeather", description = "We see one brave hippogryph circling over the fort, then swooping down and taking prey. Jethan over there has taken a couple of shots at the creature, but his arrows bounced right off!\n\nWe've taken to calling this remarkable creature Steelfeather, but we can't see why he prefers the area around Fort Wildervar. Most hippogryphs are wary of people.\n\nResearcher Aderan has helped us fashion a charm from one of the creature's feathers. He claims it will allow the user to see through Steelfeather's eyes.", objectives = "" }
WordHunterWoW_QuestEN[11419] = { title = "Brewfest Riding Rams", description = "If you show this hand stamp to Driz Tumblequick, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", objectives = "" }
WordHunterWoW_QuestEN[11420] = { title = "The Path to Payback", description = "Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the same type of gun that the vrykul use to take down our ships. By studying that gun he managed to put together a comprehensive operation manual.\n\nUnfortunately he was abducted and taken north of here to Wyrmskull Village. We eventually did find him, but near death and without the manual. His dying words indicated that the manual was lost in the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!", objectives = "" }
WordHunterWoW_QuestEN[11421] = { title = "It Goes to 11...", description = "We must strike while the vrykul forces are in disarray! Take the harpoon control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff side of the village.\n\nOnce there, commandeer one of the vrykul harpoon guns that are stationed on the building's deck. Use the harpoon gun to rain hell upon Wyrmskull Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the vrykul may send at you!\n\nDo this and Daggercap Bay will become a much safer port!", objectives = "" }
WordHunterWoW_QuestEN[11422] = { title = "Trident of the Son", description = "<From the scratches he makes in the rock, you see several symbols: a trident, a mur'ghoul, the sun, a wrecked ship, and a rough stick-figure of yourself.>\n\n<Puzzling out what the murloc is conveying takes a while. Obviously he wants you to get a trident from the Chillmere Coast, but the image of the sun is puzzling. That is until you realize he means his son.>\n\n<His son was changed into a mur'ghoul! He wants you to find him to the south near the wrecked ship and return with his trident.>", objectives = "" }
WordHunterWoW_QuestEN[11423] = { title = "The Enemy's Legacy", description = "As our armies march through Northrend, our enemies will not suffer mere defeat.  Their houses will burn, their corpses will be devoured by our plagues, all trace of their existence will be lost.\n\nThis worries me as a seeker of knowledge.  The eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing.  The vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val'kyr.  Obtain them before Nifflevar is destroyed.", objectives = "" }
WordHunterWoW_QuestEN[11424] = { title = "Shield Hill", description = "My work should be extremely easy in a time of war.  There ought to be usable body parts everywhere.\n\nIt's not that simple, though.  With these eggheads making all sorts of killer plagues and sending them to enemy towns, most of the material gets contaminated.\n\nThere is a place, though, where usable samples exist.  Shield Hill, south of here, is an ancient vrykul burial ground where the dead walk but are not afflicted with any plague - ours or the Lich King's.  Get me some bones, I'll pay ya well.", objectives = "" }
WordHunterWoW_QuestEN[11426] = { title = "Locating the Mechanism", description = "Don't worry, {name}; this is all going to lead to something big! HUGE! You're just going to have to trust me for now and do as I ask of you.\n\nWe need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you'll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You'll find them on the east side of the village, on the docks by the longhouses.", objectives = "" }
WordHunterWoW_QuestEN[11427] = { title = "Meet Lieutenant Icehammer...", description = "Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It's where most of their harpoon attacks on our frigates originate.\n\nWell guess what? The time for payback has come, {name}. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar.\n\nWhen you're ready I'll place you on the back of one of our gryphons and zip you right to him! \n", objectives = "" }
WordHunterWoW_QuestEN[11428] = { title = "Keeper Witherleaf", description = "You have been a great friend and ally to us, {name}. There is one more thing I must ask of you.\n\nYou have seen the corruption of the Twisted Glade and the beasts that dwell there. The blacksouled keepers will continue raising these abominations from the waters and soil of our glade unless we act against them.\n\nThe most powerful of the blacksouled keepers is known as Keeper Witherleaf. Slay him, {name}, and open the way for the redemption of the glade as you once redeemed my sisters.", objectives = "" }
WordHunterWoW_QuestEN[11429] = { title = "Drop It then Rock It!", description = "I'm not about to put the fate of this mission into the hands of some untested scrub.\n\nNow, if you want to prove to me that you've got what it takes to carry out this mission, you'll need to do what I tell you.\n\nTake this battle standard and head over to Baleheim, directly north of here. Once you're at Baleheim, find the center of town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our beloved flag and return to me once you've established Alliance dominance!", objectives = "" }
WordHunterWoW_QuestEN[11430] = { title = "Harpoon Master Yavus", description = "That was a fairly strong showing at Baleheim, {name}. Before you go off patting yourself on the back there's work to be done at Nifflevar.\n\nWe've located the vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the name of Yavus. You'll find him in the main harpoon structure on the bluffs of Nifflevar, southeast of here.\n\nTrack him down and execute him for crimes against the Alliance!\n\nDo me proud, {name}!\n", objectives = "" }
WordHunterWoW_QuestEN[11431] = { title = "Catch the Wild Wolpertinger!", description = "On Draenor, many creatures posed a tough hunt. However, I've never encountered a creature such as the wild wolpertinger of Azeroth!\n\nThese beasts are not to be found most of the year, but the sounds and smells of Brewfest seem to draw them out. If you look around, you still may not see them... which is where these goggles come in handy!\n\nProve to me you are a worthy hunter and bring me five of these wolpertingers alive. If you need some goggles, I have some to spare.", objectives = "" }
WordHunterWoW_QuestEN[11432] = { title = "Sleeping Giants", description = "I've overheard what you've had to say with Father Levariol. Allow me to suggest that he's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", objectives = "" }
WordHunterWoW_QuestEN[11433] = { title = "Sleeping Giants", description = "I've overheard what you've had to say with Greatmother Ankha. With all due respect, she's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", objectives = "" }
WordHunterWoW_QuestEN[11434] = { title = "Forgotten Treasure", description = "I've made my fortune by specializing in treasure that regular pirates don't appreciate: art, antiquities, collector's pieces.\n\nBlack Conrad's fleet sank south of here years ago.  All the gold and jewelry was picked clean by divers, but two ancient relics remain there.  One is a museum-quality Amani vase, the other is an eagle figurine.\n\nGo and retrieve them for me and I'll vouch for you with the other pirates.  I'll even throw in something to make your underwater adventure a bit more manageable.", objectives = "" }
WordHunterWoW_QuestEN[11436] = { title = "Let's Go Surfing Now", description = "Navigating the steep bluffs of Howling Fjord can be nerve-racking! I've come up with a solution to ease that burden by utilizing vrykul technology and dwarven ingenuity. With just a few adjustments and some fine tuning I've created Icehammer's harpoon controller! Of course it hasn't been tested, but that's what you're here for!\n\nTake the controller to the big gun in Nifflevar and use it to launch yourself into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.", objectives = "" }
WordHunterWoW_QuestEN[11439] = { title = "Fire Brigade Practice", description = "The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?\n\nSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", objectives = "" }
WordHunterWoW_QuestEN[11440] = { title = "Fire Brigade Practice", description = "With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?\n\nWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", objectives = "" }
WordHunterWoW_QuestEN[11441] = { title = "Brewfest!", description = "Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Ironforge--he'll give you a free beer to kick things off!", objectives = "" }
WordHunterWoW_QuestEN[11442] = { title = "Welcome to Brewfest!", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", objectives = "" }
WordHunterWoW_QuestEN[11443] = { title = "Daggercap Divin'", description = "Hey... Uh... What's up? What are you doing down here?\n\nMe? Oh... Well, you see... I'm... Um... I'm trying to clean this place up! Orders from Keller himself! He says to me, \"Harry, I want you to put on a divin' bell and search the shipwrecks of Daggercap for OUR stuff...\"\n\nSay, maybe you could lend me a hand while you're down here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and bring me back whatever you find. Use this diving helm so you don't run out of air and die.", objectives = "" }
WordHunterWoW_QuestEN[11446] = { title = "Brewfest!", description = "Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Orgrimmar--he'll give you a free beer to kick things off!", objectives = "" }
WordHunterWoW_QuestEN[11447] = { title = "Welcome to Brewfest!", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", objectives = "" }
WordHunterWoW_QuestEN[11448] = { title = "The Explorers' League Outpost", description = "It's all a bunch of cryptic nonsense! Even with this cipher I can't make heads or tails of these tablets. Admittedly, cryptography is not my strong point.\n\nYou'll need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I haven't heard from Stanwad in two weeks. He took a team of twenty scientists to the dig sites on the southeastern bluffs of the fjord and hasn't been heard from since. The best I can do is have McGoyver over there give you a lift with his flying machine.", objectives = "" }
WordHunterWoW_QuestEN[11449] = { title = "Fire Training", description = "The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.\n\nHead west past the graveyard, following the road. You'll find the training area there.", objectives = "" }
WordHunterWoW_QuestEN[11450] = { title = "Fire Training", description = "The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.\n\nHead south through the gate to the crossroads. You'll find the training area there.", objectives = "" }
WordHunterWoW_QuestEN[11451] = { title = "Alicia's Poem", description = "Hi, I wrote a poem for my friend Caylee.  She likes to hang out with the Aldor in Shattrath City.  You know, in Outland?\n\nCould you take my poem to her?  My mommy says I'm too young to go to Shattrath City!", objectives = "" }
WordHunterWoW_QuestEN[11452] = { title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", objectives = "" }
WordHunterWoW_QuestEN[11453] = { title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", objectives = "" }
WordHunterWoW_QuestEN[11454] = { title = "Seek the Saboteurs", description = "This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.", objectives = "" }
WordHunterWoW_QuestEN[11455] = { title = "The Fragrance of Money", description = "Us pirates are known for many things, but hygiene isn't one of them.  Most pirate ships be carrying five or six times as many rats as people.\n\nIt's no wonder all the bears on this island caught the rabies soon after we moved in.  Long story short, the boss wants 'em all dead.\n\nIt just so happens I know a recipe for a bear musk fragrance popular among Stormwind nobles.  We kill the bears and sell the musk.  I see a fine business opportunity for us here.  What say ye?", objectives = "" }
WordHunterWoW_QuestEN[11456] = { title = "Feeding the Survivors", description = "We tuskarr rely mostly on our fish catch for sustenance.  In times of great need, however, we will on occasion hunt land animals.\n\nThe nearby village of Iskaal was recently attacked by pirates and the survivors just keep pouring in.\n\nOur catch has been modest this week, but there are many shoveltusk on the island and their meat is plentiful.\n\nAid my people by hunting these great beasts and obtaining their meat.", objectives = "" }
WordHunterWoW_QuestEN[11457] = { title = "Arming Kamagua", description = "Issliruk, the spirit of war, is depicted as a silver eagle by my people.  Our stories tell of how Issliruk fought against a hundred worgs to save his young.\n\nIt is time for us, too, to fight against our foes to save our brethren.  We will need to craft new weapons.  The horns of the frostwing chimaera that make their home in the snowy parts of the island are sharp and are easily crafted into spear tips.  Bring me the best of these horns that you can find.", objectives = "" }
WordHunterWoW_QuestEN[11458] = { title = "Avenge Iskaal", description = "The totem of Issliruk is ready, {name}, and for that I thank you.  We must cast our peaceful ways for the time being and strike at those who've attacked our land and our kin.\n\nThe pirate slavers that raided Iskaal have lost their minds and slaughtered all their captives.  Go to Iskaal, to the east of here and do what must must be done.  Take this horn and call on my brethren should you need assistance.", objectives = "" }
WordHunterWoW_QuestEN[11459] = { title = "Zeh'gehn Sez", description = "Is like dis, mon.  Ye be wantin' me 'elp spotting some craven bag-o-wire been cardin' da crew?\n\nYe gotta bring me a croaker, matey.  Aft I an' I show ye who da blaggard be, mon.  Nah, nah, croaker show ye.  Ye'll ku fer yerself with yer own deadlights, yahso.\n\nBring us a carver yahso too, 'atsteppa.  Galang, bucko.", objectives = "" }
WordHunterWoW_QuestEN[11460] = { title = "Trust is Earned", description = "The first and most important factor in falconry is the bond between the falconer and his bird. Trust must be earned by the master!\n\n<Hidalgo points to the falcons in the cage at his feet.>\n\nIf you are to earn their trust you will first need to fill their bellies.\n\nThe fjord rock falcon, as these birds are known, primarily eat grubs. Throughout the fjord you will find loose rocks that serve as breeding grounds for these grubs. Find a grub and return here to feed the falcons in the cage.", objectives = "" }
WordHunterWoW_QuestEN[11464] = { title = "Gambling Debt", description = "I heard you did a little work for Terry.  I was hoping someone reliable would show up around these parts.\n\nSee, pirates love to gamble.  They, however, do not love to pay their gambling debt.\n\nIf you're interested in collecting some coin on my behalf, I'd be willing to give you a cut.\n\nLet's start you out with an easy one.  \"Silvermoon\" Harry's a bit of an eccentric, keeps all sorts of expensive blood elf knickknacks inside his tent - yet when I see him he always pretends to be broke.  Get my gold.", objectives = "" }
WordHunterWoW_QuestEN[11465] = { title = "The Ransacked Caravan", description = "I was leading a caravan here from Valgarde that was attacked by Dragonflayers. I was the only survivor of that ambush. Unfortunately, I couldn't make it back here with the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet with your rock falcon.\n\n<Hidalgo hands you a cage.>\n\nTake this falcon cage and head west down the road leading out of this camp. Use the falcon to capture the loose turkeys and return here when you've gathered enough.\n\nRemember to feed the falcon!", objectives = "" }
WordHunterWoW_QuestEN[11466] = { title = "Jack Likes His Drink", description = "Our next customer,  Jack Adams, won't be the pushover that Harry was.  He spends all day drinking with his friends, tough pirates all of them.  Let's not use force this time, could get ugly.\n\nSee if you can use his drinking habit to your advantage.  There's only so much alcohol someone can handle before passing out.\n\nMaybe one of the bar wenches will be of assistance.  Once he's out, see if you can slip your hand into his pocket and get what's mine.", objectives = "" }
WordHunterWoW_QuestEN[11467] = { title = "Dead Man's Debt", description = "You might've heard of Black Conrad, he's a famous pirate around these parts.\n\nWell, he had a thing for gambling on my fights.  He had a thing for not paying, too.\n\nI'd love to collect, but trouble is... he's dead.\n\nI was about ready to write the whole thing off, when I came across this...\n\n<Taruk unfolds a map of the Isle of Spears with an X on a northeastern plateau.>\n\nHe hid his treasure on tuskarr land.  I want you to get it.  I'll be damned if I let that bilge sucker get away without paying.", objectives = "" }
WordHunterWoW_QuestEN[11468] = { title = "Falcon Versus Hawk", description = "Do you feel the closeness, {name}? Surely you feel a true bond forming between you and your falcon. Would you believe me if I told you that when the time is right you'll be able to see through the eyes of your bird? Aye, it is the ultimate level of falconry.\n\nBut first you must hunt more! The bird must hone and quicken its reflexes. Send it against a more formidable opponent! The fjord hawks of the region make the tops of the trees around us their homes. They shall be your next target!  ", objectives = "" }
WordHunterWoW_QuestEN[11469] = { title = "Swabbin' Soap", description = "Yeah, I got to get the deck swabbed spotless afore Mad Jonah comes 'round. An' I ain't gonna do it on my hands and knees neither!\n\nProblem is, we're all outa soap. That's more your problem than mine though, mate. Being the newbie 'round here, I gots a special trip for ya to make.\n\nUp on the northwest coast of this island, there's a whole mess o' sea lions. Amongst the nearby ice floes you'll find the alpha bull, Big Roy. Bring me back his blubber and I'll magic-up the best soap ya ever seen!", objectives = "" }
WordHunterWoW_QuestEN[11470] = { title = "There Exists No Honor Among Birds", description = "You are most definitely ready for the next step in falconry, {name}.\n\nTake your trained falcon east of here, to the vrykul hawk roost near the Stonewall Lift. From the roost you will send out your falcon to steal the eggs of the hawks. Their nests will be located in remote areas of the cliff walls surrounding the roost. Locate those nests and use your falcon to scavenge for the eggs!\n\nBeware the fjord hawk matriarchs, {name}. Should you come under attack, use your falcon's escape and soar abilities to flee!", objectives = "" }
WordHunterWoW_QuestEN[11471] = { title = "The Jig is Up", description = "I know why you're here, {name}.  You've been sent to kill our leader, Jonah Sterling.\n\nI'd like to offer my help.  Jonah's leadership threatens our operation.\n\nAttacking the Horde and the Alliance fleets simultaneously?  Suicidal.  Trying to sell the tuskarr as slaves when they die days after leaving this climate?  Disastrous.\n\nJonah's hideout is located inside a cave west of here.  Bring me his spyglass as proof of the deed and my first action as leader will be to end all attacks against your allies.", objectives = "" }
WordHunterWoW_QuestEN[11472] = { title = "The Way to His Heart...", description = "The Northsea Pirates slaughtered the isles' alpha sea lion bull, Big Roy. They made soap from him to clean the decks of their ships!\n\n<Anuniaq sighs.>\n\nNow the sea lions won't mate. Help me to repopulate their numbers.\n\nThe reef bulls can be found at the Twin Shores to the southeast. They crave the tasty reef fish that can be found on the east and west sides of the isles.\n\nTake this net and gather enough fish, at least a dozen -- maybe more, to lure a bull across the strait to a reef cow.", objectives = "" }
WordHunterWoW_QuestEN[11473] = { title = "A Traitor Among Us", description = "Our second in command, Annie Bonn, has been acting rather paranoid as of late.  She seems sure we have an infiltrator in our ranks, can ye believe it?\n\nAnyhow, we have a foolproof way of uncovering rats around these parts.  See, good ole' Zeh'gehn over here happens to be an authentic witch doctor.  His family hails all the way from Zul... something or other.\n\nGo let him know that we're in need of his divination skills.  I must warn ye, {name}, only one or two of us can understand anything Zeh'gehn says.", objectives = "" }
WordHunterWoW_QuestEN[11474] = { title = "Problems on the High Bluff", description = "As usual, the real work is left up to me and my crew. Thankfully McSorf's team didn't die for nothin'. The cipher they recovered will help us crack the stuff we've found up here - that is if we can ever get back to it! Damned iron dwarves have sprung up like leaks all over the place and are now attemptin' to bury the sites! Can you believe it? Bastards want to bury our finds!\n\nAnyhow, talk to Walt over yonder. He'll get you started.", objectives = "" }
WordHunterWoW_QuestEN[11475] = { title = "Tools to Get the Job Done", description = "I've been studying this deactivated construct for days, {name}. I think I can create a reasonable facsimile of the golem that would have room inside to fit one passenger. The idea being that it would fool those iron dwarves and allow us to get inside Baelgun's.\n\nNow I'm not gonna be able to make anything with a hammer and poker. I need my tools! Unfortunately I left those behind at Ivald's Ruin when the iron dwarves first attacked. Get me my tools!\n\nIvald's Ruin is located far to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[11476] = { title = "A Carver and a Croaker", description = "Some of the pirates around here... we have our own special way of talking.  Zeh'gehn has... many different special ways of talking... all mixed together.\n\nFrom what I can tell he wants a frog and a knife.\n\n\"Silvermoon\" Harry might have a knife on the cheap.  There's frogs all over town, just grab one and bring it to him along with the knife.\n\nI'd hate to be in the poor critter's shoes, if you know what I mean.", objectives = "" }
WordHunterWoW_QuestEN[11477] = { title = "Out of My Element?", description = "Keep it down, {race}. These iron dwarves are quick on the trigger. Now don't let the activities down in the dig fool you. Those steel-skinned abominations aren't digging anything up! No sir - on the contrary - they're burying the site! For whatever whacked out reason, they don't want anyone finding this place.\n\nWhat kind of dwarf buries ancient relics and dig sites? I'll tell you what kind: the kind you kill with reckless abandon! Get in there and take 'em out!", objectives = "" }
WordHunterWoW_QuestEN[11478] = { title = "Outpost Over Yonder...", description = "I see that you haven't visited my brothers at the Explorers' League Outpost south of here. Why don't you do Donny a favor and deliver this message to Stanwad. He'll be interested to hear about the activities of the iron dwarves up here.\n\nLike I said, mount up and start heading south. You'll see the outpost right before you get to Baelgun's.", objectives = "" }
WordHunterWoW_QuestEN[11479] = { title = "\"Crowleg\" Dan", description = "Croaker's spoken, matey. \"Crowleg\" Dan's on da ship yonder.\n\nBest go trace that blaggard, mon.  Show'im dis set's not fe be crossed.  Gaan back fe Terry when ye keelhaul 'is behind.", objectives = "" }
WordHunterWoW_QuestEN[11480] = { title = "Meet Number Two", description = "All the good work you've done for us hasn't gone unnoticed, {name}.  Our second in command, the delightful Annie Bonn, is incredibly impressed with what you've done so far and wants to meet you.  ", objectives = "" }
WordHunterWoW_QuestEN[11481] = { title = "Crisis at the Sunwell", description = "By the naaru, I thank you, {race}, for your efforts.\n\nOur work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued.\n\nOur forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau.\n\nYou are needed there, {name}. Report to Larethor. Tell him that I wish we could spare more men.", objectives = "" }
WordHunterWoW_QuestEN[11482] = { title = "Duty Calls", description = "Hear me, {race}.\n\nDuty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately.\n\nI'm afraid I have no more information to share, except this:\n\nYou'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive.\n\nApparently, the situation calls for us to set our differences aside and join forces.\n\nPrepare yourself, friend. This sounds serious.", objectives = "" }
WordHunterWoW_QuestEN[11483] = { title = "We Can Rebuild It", description = "Tools? Check. Materials? Negative.\n\nIf we're going to build this thing, you're going to have to get me the materials.\n\nFirst things first, {name}. For the skeletal structure I'm going to need a large barrel from Nifflevar, some dark iron ingots from Valgarde, and industrial strength rope from Baleheim.\n\nNifflevar and Baleheim are vrykul towns northwest of here. Valgarde is located in Daggercap Bay, also to the northwest. Speak with McGoyver to get the ingots. He'll fly you back here once you're all done.", objectives = "" }
WordHunterWoW_QuestEN[11484] = { title = "We Have the Technology", description = "While the infrastructure for a piece of machinery like this is important, we can't underestimate the appearance of the construct. If we're to fool the iron dwarves the clone must be exact!\n\nI can make this happen.\n\nBring me a pristine shoveltusk hide from the shoveltusk of this region and steel ribbing from vrykul in Nifflevar or Baleheim to the northwest.", objectives = "" }
WordHunterWoW_QuestEN[11485] = { title = "Iron Rune Constructs and You: Rocket Jumping", description = "Alright, {name}; the time has come for you to climb inside this thing and learn how to use its basic abilities. When you're ready, get on the work bench and I'll get you situated inside the construct.\n\nYour first lesson is going to be using the construct's transportation system. You'll notice that the iron dwarves have set up special rune carvings around the dig site. Their constructs use those rune carvings to power up and fly from point to point. Try it with the rune carving I built here.\n", objectives = "" }
WordHunterWoW_QuestEN[11486] = { title = "The Best of Brews", description = "I know a bright lad like ya wants to stop the hostilities on the surface, eh? Ya want yer nice and merry Brewfest to go off without a hitch. I'll make ya a deal.\n\nTake this keg of our finest brew to the Brewfest Organizer outside Ironforge, so that we Dark Iron dwarves can be rightly represented! The best brew in all of Azeroth comes from right here in this mountain, and don't ya ferget it!", objectives = "" }
WordHunterWoW_QuestEN[11487] = { title = "The Best of Brews", description = "I know a bright lad like ya wants to stop the hostilities on the surface, eh? Ya want yer nice and merry Brewfest to go off without a hitch. I'll make ya a deal.\n\nTake this keg of our finest brew to the Brewfest Organizer outside Orgrimmar, so that we Dark Iron dwarves can be rightly represented! The best brew in all of Azeroth comes from right here in this mountain, and don't ya ferget it!", objectives = "" }
WordHunterWoW_QuestEN[11489] = { title = "Iron Rune Constructs and You: Collecting Data", description = "The most important part of your job while controlling the construct is the collection of data. I've placed an iron dwarf relic in the cart over yonder. It's the floating, lightning infused crystal.\n\nGet on the work bench and I'll put you back in the construct. Once you're back in the driver's seat, use the construct's data collection ability to pick up the test data.", objectives = "" }
WordHunterWoW_QuestEN[11490] = { title = "The Scryer's Scryer", description = "Go to the terrace... use the orb.\n\n<Tyrith gasps for breath.>\n\nHurry... they must be stopped... before they can....\n\n<Tyrith dies.>", objectives = "" }
WordHunterWoW_QuestEN[11491] = { title = "Iron Rune Constructs and You: The Bluff", description = "You always gotta have a contingency plan in case your main plan backfires! That's why I've built in some anti-intelligence systems into the construct.\n\nYour shiny new ride might rouse some suspicion while you're at Baelgun's excavation site. That's what your bluff ability is for! Just use that any time you're confronted and you'll be safe from harm.\n\nTest it out on Lebronski by walking on his rug. Once he starts huffin' and puffin', use the bluff!\n\nGet on the work bench when you're ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[11494] = { title = "Lightning Infused Relics", description = "Your construct is ready to go. All abilities have been given a once over and I've programmed the machine to both comprehend and speak the language of the titans.\n\nTake the construct to Baelgun's Excavation Site, due south of here, and collect data from the lightning infused relics that litter the site. Remember to bluff any iron dwarves that suspect your construct to be a fake. And don't forget about rocket jumping from rune to rune to get around in there!\n\nGet on the table when you're ready!", objectives = "" }
WordHunterWoW_QuestEN[11495] = { title = "The Delicate Sound of Thunder", description = "The cavern that we opened at Baelgun's was the one place that most steered clear of... Can't say I blame 'em. The sound of thunder shot out of that cave, {name}! Loud, booming thunder!\n\nI think near the end, it was abandoned by all. Bad, bad things happened to any that went in to explore - most never coming back.\n\nI want you to check that cave out while you're at Baelgun's. Explore around the titan statue inside and report back with your findings.", objectives = "" }
WordHunterWoW_QuestEN[11496] = { title = "The Sanctum Wards", description = "Our first priority is to capture the Sun's Reach Sanctum.  Once we've secured it, we'll be able to use its energy to open a portal from Shattrath.\n\nThe sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves.  Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards.\n\nHunt down the Wretched and get the mana remnants they carry.  Use them to energize the sanctum wards.", objectives = "" }
WordHunterWoW_QuestEN[11497] = { title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying his own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley. When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[11498] = { title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying his own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley. When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.", objectives = "" }
WordHunterWoW_QuestEN[11499] = { title = "WANTED: The Signet Ring of Prince Kael'thas", description = "{class}, today I ask the impossible. Today, you must obtain the signet ring of Kael'thas Sunstrider, lord of the blood elves!\n\nIt's true, the rumors of his death within Tempest Keep were ill-founded. He has appeared once more, this time at the Magisters' Terrace on the Isle of Quel'Danas. What he is doing there is a tale for someone else to tell you. What I know is that I have innumerable collectors interested in his princely ring, and I mean to acquire it for them.\n\nOr rather, I mean for you to do so.", objectives = "" }
WordHunterWoW_QuestEN[11500] = { title = "WANTED: Sisters of Torment", description = "It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang.\n\nMah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas.\n\nYou will do this thing to earn the bounty, or you will not.", objectives = "" }
WordHunterWoW_QuestEN[11501] = { title = "News From the East", description = "Westguard needs to know what's going on here, {name}. I want you to personally deliver the news to Captain Adams.\n\nWhenever you're ready, let me know and I'll put you back in the construct for one final flight. It'll take you to Westguard Keep, but more than likely blow up in the process.\n\nIt's been a pleasure...", objectives = "" }
WordHunterWoW_QuestEN[11502] = { title = "In Defense of Halaa", description = "We are not a warlike race, {race}.  However when war comes to our lands, we do not run away from it.\n\nThe Alliance and the Horde wage war in the city of Halaa, to the northwest. We do not know what the blood elves are scheming, but any victory for the Horde would be disastrous.  The history between our people and the orcs is one of bloodshed and betrayal.\n\nGo and slay the enemy in Halaa and you will be rewarded in coin, honor and renown.", objectives = "" }
WordHunterWoW_QuestEN[11503] = { title = "Enemies, Old and New", description = "Our ancient enemy, the draenei, have returned with powerful allies.  They wage war in Halaa, southwest of here.\n\nWe cannot allow them a victory there as Garadar would be next without a doubt.\n\nGo and slay those who would aid our ancient enemy.", objectives = "" }
WordHunterWoW_QuestEN[11504] = { title = "The Dead Rise!", description = "The path east of us is a primary hunting trail of the tuskarr. At least that's what it used to be...\n\nMore recently our hunters have been returning to Kamagua claiming that the dead have risen and are out for blood! That is what has brought my son and me here. Elder Atuik asks that we find resolution in the bluffs.\n\nWill you assist us in our time of need? I seek heroes willing to brave the perils of Shield Hill, southeast of here. Search the desecrated graves for clues and return your findings to me.", objectives = "" }
WordHunterWoW_QuestEN[11505] = { title = "Spirits of Auchindoun", description = "Auchindoun's spirits have no stake in the conflict between the Alliance and the Horde, but incurring their favor will give our side an edge in the region.\n\nAncient custom directs the living to pay their respects at spirit towers in the Bone Wastes - though only at specific times of the day.  If you can help secure a tower during these times, you will have helped bring the spirits to our side.\n\nShould we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in our endeavors.", objectives = "" }
WordHunterWoW_QuestEN[11506] = { title = "Spirits of Auchindoun", description = "The draenei might be our enemies, but the spirits of their ancestors in Auchindoun are restless and have no allegiance.\n\nThe draenei's custom required them to pay their respects at spirit towers at various times during the day.  If you can help secure a tower during these times, you will help the spirits return to peace in Auchindoun.\n\nThe Alliance will try to capture the towers in order to secure the dead's favor.   We must ensure that our side succeeds instead.", objectives = "" }
WordHunterWoW_QuestEN[11507] = { title = "Elder Atuik and Kamagua", description = "<Orfus bundles up the clues you brought him.>\n\nMy people are bitterly entrenched in a war with the Northsea Freebooters. If any tuskarr could help us in our quest to right the wrongs of the pirates, it will be Elder Atuik of Kamagua. You must take these clues to him at once.\n\nTo get to Kamagua you must take the Ancient Lift, behind me. Take the lift directly to Kamagua and find Elder Atuik.", objectives = "" }
WordHunterWoW_QuestEN[11508] = { title = "Grezzix Spindlesnap", description = "The pirate thieves have set up port at Scalawag Point, far to the south. Unfortunately, they have fortified their camp with many deadly defenses.\n\nThere is someone that might be able to assist us in infiltrating Scalawag.\n\nA pirate mercenary by the name of Grezzix Spindlesnap recently came to our village in search of food and shelter. In exchange he gives us information about our enemies and feeds them misinformation about our attack plans. Seek him out at his ship just off the coast here - southwest.", objectives = "" }
WordHunterWoW_QuestEN[11509] = { title = "Street \"Cred\"", description = "The Northsea Freebooters all fear and respect Grezzix. I'm thinking they recognize my special talents and envy my amazing ship. All you need to do is tag along with my cabin boy, Lou, and you'll be in like... In like tin. Pirates love tin.\n\nJust talk to Lou when you're ready to go and he'll take you to Scalawag.\n\nOh yea, you'll want to talk to \"Silvermoon\" Harry first. He'll have more information on the stuff they pilfered. Just watch what you say around him. He's a freak... crazy for blood elves.", objectives = "" }
WordHunterWoW_QuestEN[11510] = { title = "\"Scoodles\"", description = "One of the first things Jonah Sterling did after he went crazy was to take my prized sin'dorei scrying crystal and feed it to the bane of my existence, \"Scoodles\" the orca.\n\nNo I didn't name the damned thing. I just know that she swims out past the ships directly southeast of Scalawag. Kill that overinflated goldfish and rip out my beautiful sin'dorei crystal from its stomach.\n\nDo this and we can get down to business.", objectives = "" }
WordHunterWoW_QuestEN[11511] = { title = "The Staff of Storm's Fury", description = "Those artifacts are cursed and you'd be crazy to go looking for them, {race}. I know for certain that anyone that's come into direct contact with any of those items has either gone mad or been killed.\n\nTake that staff, for example. Last I heard the ship that held it was abandoned and left to rot on the coast of the Isle of Spears, north of here.\n\nIf you want that thing, check the ship's hold.\n\nWhatever you do, don't bring that staff back here! And steer clear of Abdul! He'll tear your heart out.", objectives = "" }
WordHunterWoW_QuestEN[11512] = { title = "The Frozen Heart of Isuldof", description = "Some say Jonah was never quite right in the head, but I know the truth. It was the heart. That damned frozen heart! I saw the change in him the second he pulled it from the grave. I could see the blood freeze in his veins... It was then that the madness truly took over.\n\nHe left us to hole up in his cave on the north side of this island. Last I heard he had thrown the heart in the back of his bear den. Too little, too late...\n\nI'll kill you myself if you even think about bringing that heart back here!", objectives = "" }
WordHunterWoW_QuestEN[11513] = { title = "Intercepting the Mana Cells", description = "I have devised a plan to acquire a power source strong enough for the creation of our portal.\n\nThe ethereal forces at Bash'ir Landing, atop the northwestern Blade's Edge Mountains, have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael'thas.\n\nThey have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods.\n\nJust beware the mana cells' phase wyrm guardians.", objectives = "" }
WordHunterWoW_QuestEN[11514] = { title = "Maintaining the Sunwell Portal", description = "We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade's Edge Mountains, far to the north.\n\nRemember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods.\n\nJust be cautious of the phase wyrms that they use to guard the mana cells.", objectives = "" }
WordHunterWoW_QuestEN[11515] = { title = "Blood for Blood", description = "When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift.  They  stayed behind and gorged themselves on the blood of demons for days.\n\nThe blood has changed them, given them new powers.  It will also prove their undoing.\n\nObtain blood samples from other demons.  Use them to power this fel siphon and deprive these arrogant fools of their new powers.  Slay them in their weakened state and return to me.", objectives = "" }
WordHunterWoW_QuestEN[11516] = { title = "Blast the Gateway", description = "We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas.\n\nTake these embers, they contain one of my creations: a living flare.  It is designed to act as a powerful destructive force - as long as it has been provided enough energy.\n\nFind the fel sparks that wander the area and slay them near the living flare.  The flare will grow in power each time, until it becomes unstable.\n\nOnce you've achieved this bring the flare to the gateway.  It will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[11517] = { title = "Report to Nasuun", description = "I am most glad that you are here, {class}! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", objectives = "" }
WordHunterWoW_QuestEN[11519] = { title = "The Lost Shield of the Aesirites", description = "If you listen real close you can hear cannon fire coming from the northeast. That's Captain Ellis's ship, Sister Mercy. Thing is, Ellis and his entire crew were killed 'bout a month ago.\n\n<Harry nods.>\n\nGhost ship...\n\nIf it's info you be wantin' 'bout the shield, Ellis is the man to ask.\n\nSister Mercy docks on the small island between here and Sorlof's Strand to pick up more souls for the ship's crew 'bout once every five minutes. There be no shortage of souls 'round these parts...", objectives = "" }
WordHunterWoW_QuestEN[11520] = { title = "Discovering Your Roots", description = "Greetings, {race}.\n\nI'm afraid I have little to offer here until my reagents are stocked.\n\nOf the supplies I require, there is a special reagent, razorthorn root, that is particularly difficult to harvest.\n\nFortunately, I know a secret....\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outland and fly northeast from Shattrath until you reach Razorthorn Rise.", objectives = "" }
WordHunterWoW_QuestEN[11521] = { title = "Rediscovering Your Roots", description = "My stocks are presently sufficient, but I'll need plenty of razorthorn roots to keep up with the demand.\n\nCollecting the roots is difficult, but I know a special method of extraction.\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outland and fly northeast from Shattrath until you reach Razorthorn Rise.\n\nReturn to me, {name}, once you have collected five of the roots.", objectives = "" }
WordHunterWoW_QuestEN[11523] = { title = "Arm the Wards!", description = "We've succeeded in reactivating the crystal wards around the sanctum, but why stop there?  We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards.\n\nHunt them down and get the mana remnants they carry.  Use the remnants to energize the sanctum wards; the safety of our operation depends on it.", objectives = "" }
WordHunterWoW_QuestEN[11524] = { title = "Erratic Behavior", description = "We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor.\n\nThe loose energy from the Sunwell has caused the sentries that patrol this island to malfunction.  The crystal cores that control their behavior are damaged beyond repair.\n\nI've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries.  We will need all the help we can get.", objectives = "" }
WordHunterWoW_QuestEN[11525] = { title = "Further Conversions", description = "My plan to replace the damaged crystals on the erratic sentries has been a success.  We've managed to take the Sun's Reach Sanctum with their help.\n\nI've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries.  We'll deploy them to other locations once they're converted.", objectives = "" }
WordHunterWoW_QuestEN[11526] = { title = "The Missing Magistrix", description = "We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here.  She never returned.\n\nTake this scroll we found on one of the enemy corpses.  We believe it will grant you access through the portal.  Once through, find Magistrix Seyla and aid her in any way you can.", objectives = "" }
WordHunterWoW_QuestEN[11527] = { title = "Mutiny on the Mercy", description = "Aye, we got problems, matey. Me gunners have mutinied! M'n'the crew up top be tryin' to kick Sorlof's keester while dealin' with the mutinous gunners down'blo.\n\nYe're gonna have to go down'blo and deal with those mutinous sea dogs and take their blastin' powder for the big'un o'er on the poop deck.\n\nWith ye mannin' the big'un, Sorlof is sure to die and give up the booty!", objectives = "" }
WordHunterWoW_QuestEN[11528] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[11529] = { title = "Sorlof's Booty", description = "Me crew is gonna get the big'un all primed an'ready for ya, matey. She's restin' snuggly on the bow, o'er on the other side of the ship. Go'n man it and be ready to fire when Sorlof is in our sights!\n\nOnce we take that landlubber down, ye'll have to recover the booty for us, seein' as how we can't leave the damned ship! Bring that booty back to me and ye'll get your cut - the shield...", objectives = "" }
WordHunterWoW_QuestEN[11530] = { title = "The Shield of the Aesirites", description = "Here's yer shield. Me hopes it doesn't curse ye like it did me'n'me crew. Ye don't have to go home, but ye can't stay here... I be certain that thar be some that would be interested in getting' it back.\n\nNow get that thing off me ship!", objectives = "" }
WordHunterWoW_QuestEN[11532] = { title = "Distraction at the Dead Scar", description = "The Legion will move against us as soon as their forces to the south are freed up.  The Scourge at the Dead Scar are keeping their forces occupied at the moment.  It won't last long, however.\n\nI want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges.\n\nIf all goes well, they won't even notice us taking the armory from Kael's lackeys.  Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.", objectives = "" }
WordHunterWoW_QuestEN[11533] = { title = "The Air Strikes Must Continue", description = "We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar.\n\nAs a matter of fact, it's gone so well that we're going to continue our air strikes against them.  Take these arcane charges and use them against their forces.\n\nTalk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.", objectives = "" }
WordHunterWoW_QuestEN[11534] = { title = "Report to Nasuun", description = "I am most glad that you are here, {class}! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", objectives = "" }
WordHunterWoW_QuestEN[11535] = { title = "Making Ready", description = "Supplies are inbound, or so I'm told.\n\nRegardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have.\n\nAs for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons.\n\nThere are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion.\n\nRelieving them of their ore will help our efforts in more ways than one....", objectives = "" }
WordHunterWoW_QuestEN[11536] = { title = "Don't Stop Now....", description = "Now that we have an anvil, I can really get to work.\n\nNo matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here.\n\nThere are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", objectives = "" }
WordHunterWoW_QuestEN[11537] = { title = "The Battle Must Go On", description = "We must continue to defeat and demoralize the armies of the Legion.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", objectives = "" }
WordHunterWoW_QuestEN[11538] = { title = "The Battle for the Sun's Reach Armory", description = "The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", objectives = "" }
WordHunterWoW_QuestEN[11539] = { title = "Taking the Harbor", description = "One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village.\n\nThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[11540] = { title = "Crush the Dawnblade", description = "We've driven the Dawnblade army out of the Sun's Reach Harbor.  Sun's Reach is ours in its entirety.  Yet somehow... I'm not entirely satisfied.\n\nI want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants.  They sealed their fate when they followed Kael to this place.", objectives = "" }
WordHunterWoW_QuestEN[11541] = { title = "Disrupt the Greengill Coast", description = "The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs.\n\nIt's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in.\n\n{class}, I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free.\n\nMy guess is that the murlocs will be incensed and turn on their masters.", objectives = "" }
WordHunterWoW_QuestEN[11542] = { title = "Intercept the Reinforcements", description = "We're making a push to solidify our control of Sun's Reach by capturing the harbor next.  Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.    You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", objectives = "" }
WordHunterWoW_QuestEN[11543] = { title = "Keeping the Enemy at Bay", description = "We've managed to capture Sun's Reach in its entirety.  Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.  You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", objectives = "" }
WordHunterWoW_QuestEN[11544] = { title = "Ata'mal Armaments", description = "The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but is now overrun by fel orcs. They have dug up the special ore from that place and created corrupted weapons and armor.\n\nI need the armaments to form an alloy with the naga ore. Our anchorites have blessed my anvil with the ability to cleanse them.\n\nRetrieve the armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, breaking down and purifying them upon my anvil, and then hand me the cleansed results.", objectives = "" }
WordHunterWoW_QuestEN[11545] = { title = "A Charitable Donation", description = "We've taken Sun's Reach from the enemy and our final victory is at hand.  The cost was high and many brave combatants gave their lives so we could achieve this.\n\nIt is my goal to ensure that those who perished in combat are not forgotten.  I ask that you take a moment to consider making a donation towards a memorial fund.  Any leftover gold will go to the widows and orphans of the fallen.", objectives = "" }
WordHunterWoW_QuestEN[11546] = { title = "Open for Business", description = "Welcome, {name}.\n\nThere are a number of ways I can assist you in your efforts here.\n\nFor example, I've recently discovered a recipe for a unique elixir.\n\nThe bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites.\n\nBring me a sample from the nearby bushes and I'll show you what I mean.", objectives = "" }
WordHunterWoW_QuestEN[11547] = { title = "Know Your Ley Lines", description = "Freeloaders!\n\nYou all want instant gratification - never giving thought to the effort required to create even the simplest of portals.\n\nPerhaps a little education will instill a bit of gratitude for my ceaseless efforts.\n\nTake this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast.\n\nPerhaps then you'll appreciate your precious translocations....", objectives = "" }
WordHunterWoW_QuestEN[11548] = { title = "Your Continued Support", description = "We've built a memorial to honor those slain in battle.  It's but a small consolation to the families that lost their loved ones.\n\nI am taking up a collection to aid the orphans and spouses of our war heroes.  If you can spare a small donation it would go a long way.", objectives = "" }
WordHunterWoW_QuestEN[11549] = { title = "A Magnanimous Benefactor", description = "You've done so much for us, {name}.  We greatly appreciate your assistance.\n\nYou might have noticed Anchorite Ayuri's efforts outside.  She has a big heart and is very convincing, but the donations do not quite add up to what she had expected.\n\nIf you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide.  What do you say?", objectives = "" }
WordHunterWoW_QuestEN[11550] = { title = "Enter, the Deceiver...", description = "Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival.\n\nThe object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now.\n\nReport to Archmage Ne'thul at the Isle of Quel'Danas, north of Quel'Thalas.", objectives = "" }
WordHunterWoW_QuestEN[11554] = { title = "A Friend in the Frontlines", description = "", objectives = "" }
WordHunterWoW_QuestEN[11555] = { title = "Honored by Your Allies", description = "", objectives = "" }
WordHunterWoW_QuestEN[11556] = { title = "Revered in the Field of Battle", description = "", objectives = "" }
WordHunterWoW_QuestEN[11557] = { title = "Exalted Among All Combatants", description = "", objectives = "" }
WordHunterWoW_QuestEN[11559] = { title = "Winterfin Commerce", description = "Now that you can speak with the Winterfin, it is time for you to let them get to know you. One of the best ways to do that is to conduct business with them.\n\nThe murlocs prize clams over any other object and their only surviving merchant is Ahlurglgr. If I were you, I'd collect a handful of Winterfin clams and give them to him as a gift.\n\nThe clams can be found all over down in the trench, as well as across it in the Winterfin village and their caverns.", objectives = "" }
WordHunterWoW_QuestEN[11560] = { title = "Oh Noes, the Tadpoles!", description = "Oh good, you're back!\n\nWhen the landslide at the village across the water exposed the caverns, a malevolent lobstrok, known as Claximus, came out of the caves and stole the Winterfin tadpoles away.\n\nSomething happened to all of the murlocs that followed him in there, and when they re-emerged, they were under his control.\n\n{class}, you must swim across the waters and rescue the Winterfin tadpoles in the village and caverns.\n\nThe future of the Winterfin tribe depends upon you!", objectives = "" }
WordHunterWoW_QuestEN[11561] = { title = "Them!", description = "Our brothers and sisters across the water are now our mortal enemies. They have kidnapped our tadpoles, driven us out of our village, and killed more of us than I can count.\n\nProve yourself, {race}! Swim across the rift and slay them!\n\nDespite the favor that the new king has shown you, only then will we consider accepting you here. Fail to do so, and you might as well leave now and never return!", objectives = "" }
WordHunterWoW_QuestEN[11562] = { title = "I'm Being Blackmailed By My Cleaner", description = "I have something embarrassing to admit: I'm being blackmailed!\n\nMrmrglmr agreed to clean some of my things, and got hold of my spare murloc costume. He's threatening to reveal my true nature to the other murlocs.\n\nI need not explain to you what a disaster that would be! Besides, I have a plan that's going to require that we get that costume back.\n\nPlease, {name}, go to Mrmrglmr at the other end of the Retreat to the north and do whatever he asks of you.", objectives = "" }
WordHunterWoW_QuestEN[11563] = { title = "Grmmurggll Mrllggrl Glrggl!!!", description = "If your pathetic little eyes were any good, you'd see that we're being slaughtered by the orcas to the north in the bay!\n\nAssuming your precious night elf king wants his spare costume back, I think you'll do me a favor and bring back the head of the king of the orcas, Glrggl: he who swims against the tides of fate -- eradicating the hope of life for all those who hear the siren song of death upon the waves!\n\nBe quick about it, {race}, Winterfin murlocs are losing their lives even as we waste time talking!", objectives = "" }
WordHunterWoW_QuestEN[11564] = { title = "Succulent Orca Stew", description = "Word is, strange {race}, that you might be going after the king of the orcas, Glrggl.\n\nThat's all fine and good, but if you want to taste the stew that makes life worth living, then you'll bring me back the succulent blubber of the orcas that swim in Glimmer Bay.\n\nHurry... I have quite a bit of cutting to do on this carcass if you want to reap the benefits of your efforts.", objectives = "" }
WordHunterWoW_QuestEN[11565] = { title = "The Spare Suit", description = "Very well, your king's secret is safe with me as long as he continues to help us against our enemies.\n\nHere, take this to him. I cleaned it up nicely, though I have no idea why he needs a second disguise.\n\nMaybe he has something in mind for you?", objectives = "" }
WordHunterWoW_QuestEN[11566] = { title = "Surrender... Not!", description = "The time has come to put an end to this unnatural situation, {name}. For the Winterfin murlocs to have a chance at a future, Claximus must die!\n\nI want you to take my spare murloc suit and enter the Winterfin Caverns under the pretext of surrender. With the white flag in hand, the murlocs won't attack you.\n\nYou'll find him in the southwestern most corner of the caverns. Once you get close enough, deal with Claximus. Bring me one of his claws as proof that the grisly deed has been done.", objectives = "" }
WordHunterWoW_QuestEN[11567] = { title = "The Ancient Armor of the Kvaldir", description = "I was on the vessel that was bringing in the armor. We'd just boarded the ship and were headin' back here when we were attacked by a Forsaken destroyer.\n\nThey boarded our ship, took all the booty for themselves, and then sunk her.\n\nThat was the last I'd seen of that armor. If you want, you can take my bomber from Scalawag to the dreaded isle that the destroyer be docked. Talk to my woman, Alanya, outside. She'll get you on the bomber.\n\nIf you manage to find the stuff, don't you dare bring it back!", objectives = "" }
WordHunterWoW_QuestEN[11568] = { title = "A Return to Resting", description = "<Orfus hands you a satchel.>\n\nWithin this satchel are the artifacts that you recovered. Locate the burial mounds of Shield Hill, far to the southeast, where the items were originally stolen from and return the artifacts. It is my hope that this gesture will quell the spirits that now haunt our hunting grounds.\n\nBe strong, {name}...", objectives = "" }
WordHunterWoW_QuestEN[11569] = { title = "Keymaster Urmgrgl", description = "I have to get out of these caverns! There's magic stuff seeping in from Coldarra, above, and affecting everyone's minds.\n\nI don't intend to be controlled like these others!\n\nKeymaster Urmgrgl is in the cave below and to the south. He holds the key to my cage. Get it from him and bring it back so that I can unlock my cage and get out of here.\n\nHurry!", objectives = "" }
WordHunterWoW_QuestEN[11570] = { title = "Escape from the Winterfin Caverns", description = "The lock on my cage doesn't look too solid, but I'm not foolish enough to try to leave without assistance.\n\nWill you help me safely get out of these caverns? There's no time to waste, {race}.\n\nWhen you get back to the retreat, please let the king know that I'm okay. He's sure to give you a reward.", objectives = "" }
WordHunterWoW_QuestEN[11571] = { title = "Learning to Communicate", description = "To help, you must learn how to speak the Winterfin dialect. We'll work with the forces of nature and magic to do that.\n\nTake this empty conch shell. At the bottom of the watery trench below exists Scalder, an elemental of air and watery fury.\n\nOnce she is defeated, use the conch upon her remains to capture her magical steam. Return the full conch to me, and I'll imbue my knowledge of the Winterfin tongue into you.\n\nLuckily, a friend taught me a water breathing spell, which I will cast upon you.", objectives = "" }
WordHunterWoW_QuestEN[11572] = { title = "Return to Atuik", description = "Return to Elder Atuik at Kamagua. He and the rest of my people must be warned of this impending doom that approaches from the sea.\n\n<Orfus shivers.>\n\nUse the Ancient Lift to reach him. Please hurry!", objectives = "" }
WordHunterWoW_QuestEN[11573] = { title = "Orfus of Kamagua", description = "Hail, traveler. I am Lunk-tusk of the Kalu'ak. We are known as tuskarr to your people. My partner and I were recently sent up to investigate strange happenings along one of our hunting trails. It was when we approached the graveyard known as Shield Hill that we were attacked by the undead. I was lucky to make it to this camp, but I am uncertain as to what became of Orfus.\n\nWe parted ways at the Ancient Lift, southeast of here along the cliff edge. Will you go see if he is ok?", objectives = "" }
WordHunterWoW_QuestEN[11574] = { title = "Too Close For Comfort", description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts - I was surrounded!\n\nA magical box appeared above me, opened up and pulled me inside. Just as it began to close around me, my rescuers swooped in on the backs of red drakes. It was breathtaking!\n\nI never thanked them for saving me. Please, {class}, find them, and pass on my gratitude.", objectives = "" }
WordHunterWoW_QuestEN[11575] = { title = "Nick of Time", description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts. I was surrounded!\n\nA huge magical cube appeared above me. It opened up and pulled me inside. I swear it's true!\n\nJust as it began to close around me, my rescuers swooped in on the backs of drakes - It was amazing! My captors scattered and I was able to escape.\n\nI never thanked them for saving me. Please, {class}, if you see them, pass on my gratitude.", objectives = "" }
WordHunterWoW_QuestEN[11576] = { title = "Monitoring the Rift: Cleftcliff Anomaly", description = "Greetings, {race}. I am Garren of Dalaran.\n\nNot long ago, the rift was a peaceful place - geothermally speaking at least.\n\nRecently though, earthquakes have occurred with alarming frequency and scars in the earth have appeared, exposing unique energy fields of chaotic power.\n\nMy mission here is to chart and monitor these anomalies. My instruments indicate that another has appeared on the cliff face to the southwest.\n\nTake this device with you and use it when you locate the new disruption.", objectives = "" }
WordHunterWoW_QuestEN[11580] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[11581] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[11582] = { title = "Monitoring the Rift: Sundered Chasm", description = "Did you feel that?! That was just an aftershock... you should've been here a few minutes ago!\n\nI'm afraid I must call upon your services again. My instruments indicate that there is an immense disruption just west of here, far beneath the water's surface.\n\nJust as before, I need you to take the arcanometer and capture the anomaly's data.\n\nI'll cast a spell that will enable you to breathe underwater. If it wears off before you find it, come let me know and I'll renew its effects.", objectives = "" }
WordHunterWoW_QuestEN[11583] = { title = "Honor the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[11584] = { title = "Honor the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[11585] = { title = "Hellscream's Vigil", description = "Throm-Ka, {race}! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!\n\nThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!", objectives = "" }
WordHunterWoW_QuestEN[11586] = { title = "Hellscream's Vigil", description = "Throm-Ka, {race}! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!\n\nThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!", objectives = "" }
WordHunterWoW_QuestEN[11587] = { title = "Prison Break", description = "Greetings, {class}. I am Donathan, a loyal representative of Dalaran.\n\nForgive my abruptness, but we find ourselves in the midst of a crisis. Mages all across Azeroth are being abducted and I have been authorized to conscript anyone able to assist in the unraveling of this mystery.\n\nThe camp just south of ours is where our investigation begins. I call upon you to rescue one of the imprisoned mages held there. You must obtain a key from one of the mage hunters and use it to open an arcane prison.", objectives = "" }
WordHunterWoW_QuestEN[11590] = { title = "Abduction", description = "{name}, we have a situation.\n\nI've just learned that one of our archmages en route from Dalaran has gone missing. Naturally, we suspect the mage hunters are behind her disappearance.\n\nTime is clearly of the essence. We must know what has become of Lady Evanor at once if we are to have any hope of rescuing her.\n\nTake this device. Return to Beryl Point and use it on a Beryl sorcerer when he is near death. It should bind him long enough for you to bring him here for questioning.", objectives = "" }
WordHunterWoW_QuestEN[11591] = { title = "Report to Steeljaw's Caravan", description = "That dimwitted cur, Steeljaw, tried to take our caravan of supplies on a shortcut through a taunka graveyard!\n\nWe just struck up relations with them!\n\nNow the caravan lies in ruins, overrun by the taunka spirits that rose out of their graves as he was trampling them.\n\nHead south and see if you can salvage the situation, {class}. I sent Grunt Ragefist and a few others down there with him to help out.\n\nWhy don't you see if you can lend a hand.", objectives = "" }
WordHunterWoW_QuestEN[11592] = { title = "We Strike!", description = "One of your orcs named Steeljaw tried to save some time by taking a shortcut through our burial grounds. This had better not be how your Horde normally acts, {race}, or you will find the taunka to be the end of you!\n\nBut, you look as if you want to help fix this situation. Good!\n\nSteeljaw's cursed spirit now haunts this place and disturbs the remains of my ancestors. We must put an end to him!\n\nIf we live through this, tell your Overlord Bor'gorok at the outpost to the north.\n\nAre you with me?", objectives = "" }
WordHunterWoW_QuestEN[11593] = { title = "The Honored Dead", description = "Our fallen deserve a hero's funeral, but we cannot bury them here on sacred taunka ground.\n\nI'll not ask you to drag their bodies back here, but take this and head further into the cemetary.  When you come across our dead caravan guards and workers, put them to the torch.\n\nHonor our dead, {class}!", objectives = "" }
WordHunterWoW_QuestEN[11594] = { title = "Put Them to Rest", description = "Force-Commander Steeljaw's idiocy caused this mess. What was he thinking taking a caravan through a taunka burial mound?\n\nStill, what's done is done. Now it is up to us to deal with the consequences.\n\nOverlord Bor'gorok asked me to help Longrunner Proudhoof in any way that I can. The longrunner has asked that we lay to rest the spirits of his ancestors.\n\nWhat do you say, {class}? Are you man enough to handle such a simple task?", objectives = "" }
WordHunterWoW_QuestEN[11595] = { title = "The Defense of Warsong Hold", description = "Hellscream has the weight of the Horde upon his shoulders. Do not be dissuaded from your duties because of his temperament, {name}.\n\n<Saurfang nods.>\n\nDid you think that I would forget the name of a hero of Orgrimmar? It is not every day that I have the pleasure of putting the head of Nefarian on a pike!\n\nThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.", objectives = "" }
WordHunterWoW_QuestEN[11596] = { title = "The Defense of Warsong Hold", description = "Do not let Hellscream dissuade you from your duties as a soldier of the Horde, {race}. He bears a terrible burden in these frozen wastes, with the outcome of his charge resulting in victory over the Scourge or the extinction of all life on Azeroth. It is for this reason that we require your strength and wisdom.\n\nThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.", objectives = "" }
WordHunterWoW_QuestEN[11597] = { title = "The Defense of Warsong Hold", description = "It seems that we always meet in the direst of circumstances, Scarab Lord. Were you not saving the world from certain destruction the last time we met?\n\n<Saurfang chuckles.>\n\nYour assistance is most welcome in Northrend, despite what the young chieftain might say.\n\nIf we had even a dozen more soldiers with your power, we would be sitting in Orgrimmar right now, hunched over a warm fire.\n\nReport to Overlord Razgor, right outside the main entry to Warsong Hold, to the south.", objectives = "" }
WordHunterWoW_QuestEN[11598] = { title = "Taking Back Mightstone Quarry", description = "While Warsong is protected by 10 feet of steel and stone on all sides, this quarry is soft and primed for attacks by the Nerubians.\n\n<Razgor points west.>\n\nBeyond this quarry stand thousands of Scourge, awaiting orders to attack. Should the Nerubians take down our inner defenses, we will be overrun by the undead legions of Arthas.\n\nWe can't let that happen - which is why you're going on the offensive and slaughtering the Nerubians in the quarry.\n\nBlood and thunder, soldier! Take 'em both with you.", objectives = "" }
WordHunterWoW_QuestEN[11599] = { title = "Thassarian, My Brother", description = "I recently received word from William Allerton, a family friend, that my brother enlisted here in Valiance Keep on the same day he did.  Thing is... my brother's been dead for years.\n\nI sold everything I owned to come looking for Thassarian, only to be stonewalled by the local bureaucracy.  I've even been threatened with arrest if I keep snooping around.\n\nI need someone in the good graces of the higher-ups... someone like you.  If you can help me, I heard that William's stationed at the Farshire mine.", objectives = "" }
WordHunterWoW_QuestEN[11600] = { title = "The Late William Allerton", description = "William's neck has been cut by a sharp object.\n\nFurther inspection reveals a single clue to bring to Leryssa - an enlistment card bearing the name of William Allerton.", objectives = "" }
WordHunterWoW_QuestEN[11601] = { title = "Lost and Found", description = "Poor Mr. Allerton might yet help us find my brother.\n\n<Leryssa unveils a voluminous book, not unlike an army recruitment ledger.>\n\nI borrowed it, ok?  Let's see, does that enlistment card have a date?\n\nWilliam saw Thassarian at the enlistment line.  Their entries must be near each other... here it is!\n\nHe was assigned to... Unit S?  All the other military units are named after Alliance towns.\n\nWho's in the unit?  Where are they deployed?  We need rumors.  See if the innkeeper's heard anything.", objectives = "" }
WordHunterWoW_QuestEN[11602] = { title = "Cutting Off the Source", description = "Aerial reconnaissance of the quarry reports that the Nerubians are storing their eggs on the scaffolding surrounding the base. Smart beasts these are... They're keeping the eggs high and dry, away from the epicenter of conflict.\n\nYou're going to have to go back out there and track down their eggs. Find 'em, smash 'em, and trash 'em.\n\nEach egg destroyed means twenty less Nerubians feeding on our corpses.\n", objectives = "" }
WordHunterWoW_QuestEN[11603] = { title = "In Wine, Truth", description = "The military was all that old man Colburn had.  After he retired, he still clung to it like a lifeline.\n\nHe knows the name of every general, unit, brigade, detachment... you name it.  He's the man you need.\n\nProblem is, his mind is scarred.  He won't talk to anyone unless he gets his Kul Tiras wine.  Takes him back to the times he was a marine.\n\nI haven't received a shipment in months.  The last merchant ship out of Kul Tiras sunk northeast of here.  See if you can salvage a bottle to bring Colburn.", objectives = "" }
WordHunterWoW_QuestEN[11604] = { title = "A Deserter", description = "Unit S... Unit S.... hmmmpph.... don't make any sense... it oughta be named after a town...\n\nDarkshire was sent to Dragonblight.  The Goldshire boys were sent to the Fjord.   Where did I hear...\n\nOh, yes... the deserter!  There's a turn-tail in the barracks prison.  Got thrown in not too long ago.  Kept saying that \"S\" stood for suicide.\n\nLook for the deserter.  He might have some information for you.", objectives = "" }
WordHunterWoW_QuestEN[11605] = { title = "The Honored Ancestors", description = "<A distant voice echoes in your head as you regard the stone statue.>\n\nDo not be startled, stranger. I am Elder Atkanok, an ancient ancestor of the tuskarr people, a skilled craftsman in my own time and the guardian of this quarry for centuries.\n\nThe quarry has been overrun, leaving many statues unfinished while the ancestors' spirits wander the world. Will you aid me in righting this wrong?\n\nFirst, I must know the names of these wandering ancestors. Look for the markers near their statues.", objectives = "" }
WordHunterWoW_QuestEN[11606] = { title = "Patience is a Virtue that We Don't Need", description = "We can kill all the Nerubians that we see and destroy all the eggs that we find, but those things won't stop coming until we blow their tunnels and passageways up. Of course, we can't do that without some heavy grade munitions. Unfortunately, most of our stockpile is being used up by the goblins and blacksmiths for our siege tanks and weaponry.\n\nWe do happen to have a pretty good supply of the stuff out in Mightstone Quarry - underneath all the Nerubian crap. You'll just have to go out and get it for me.", objectives = "" }
WordHunterWoW_QuestEN[11607] = { title = "The Lost Spirits", description = "In the attack on the quarry, the shaman and craftsmen working here were slain. The violence threw the spirit world into utter chaos and we'll be unable to guide the ancestors home unless we find a way to soothe the spirits of the murdered.\n\nThe aggressors themselves pay no heed to the spirits, but their companions, the beryl hounds, sense the spirits and hold them in thrall.\n\nKill the beryl hounds, and using the raw energy left behind, break the imprisonment of the spirits of the innocent.", objectives = "" }
WordHunterWoW_QuestEN[11608] = { title = "Bury Those Cockroaches!", description = "North, south, east and west. Those are the locations that you should be concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly situated Nerub'ar sinkholes.\n\n<Holgoth hands you a bundle.>\n\nBe very careful with that package, {name}. Mishandle it and you'll be dog meat.\n\nInside the bundle are seaforium depth charges. Get to each of those Nerub'ar sinkholes and plant a depth charge at their center point. If all goes well, the tunnels will collapse.\n\nGet a move on!", objectives = "" }
WordHunterWoW_QuestEN[11609] = { title = "Picking Up the Pieces", description = "With the spirits of the murdered craftsmen and shaman at rest, the way is clear for us to complete the ceremonies interrupted by the attack. You must perform a role traditionally reserved for a tuskarr shaman, and you must possess all the necessary ritual items.\n\nThere is no time to craft new ones, so you will need to scour the quarry for those left by the victims of the attack. Handle these objects with care, {name}, for some are centuries old. You may need to wrest them from the hands of the invaders.", objectives = "" }
WordHunterWoW_QuestEN[11610] = { title = "Leading the Ancestors Home", description = "With your help, the ancestor spirits can now be guided to their rightful homes, the statues lovingly prepared by Kaskala's craftsmen and shaman.\n\nThe ceremonies for these ancestors were interrupted during the attack on the quarry, and you will need to complete them. Take with you the objects that you recovered from the quarry, stand in front of the statues with the name markers, and recite this chant.\n\n<Words in a strange language flood your head, but you have no difficulty recalling them.>", objectives = "" }
WordHunterWoW_QuestEN[11611] = { title = "Taken by the Scourge", description = "<Mortuus sighs.>\n\nPeons... We may as well post up a sign offering the Nerub'ar a free meal.\n\nSee, the problem with a peon is that: (1) they're dumber than dirt; and (2) they're weaker than a leper gnome. Of course they're the first to be taken by the Scourge!\n\nThis puts me in a bit of a predicament, you see. Without peons, manual labor comes to a halt. No peons, no construction.\n\nFind and release my peons, {race}. If they're alive, you'll find 'em spun up in webbing throughout Mightstone Quarry.\n", objectives = "" }
WordHunterWoW_QuestEN[11612] = { title = "Reclaiming the Quarry", description = "You're a welcome sight, {class}. My name is Etaruk, and I used to be a craftsman here at the Coldrock Quarry.\n\nMy companions and I were preparing a new set of statues for their last set of rites when we saw those mysterious blue platforms come flying over the plateau.\n\nWhen they landed, the mages they carried swarmed the quarry, murdering my fellows and plundering the quarry. If we don't stop them, they'll destroy our statues and make off with our artifacts. Will you help me defeat the invaders?", objectives = "" }
WordHunterWoW_QuestEN[11613] = { title = "Karuk's Oath", description = "They call themselves the Kvaldir.  My people have legends about them; we call them the tuk-hariq - walkers of the fog.\n\nMy village was destroyed by these giant mist-men.  Everyone I knew was slain, including my father Ariut.\n\nBy tuskarr law I must seek retribution against those who shed my kin's blood.\n\nI am but a fisherman and I've not yet passed the test of manhood... I cannot stand toe-to-toe with the vile Kvaldir.\n\nIf you were to carry out my blood duty for me, I will be in great debt to you.", objectives = "" }
WordHunterWoW_QuestEN[11614] = { title = "Untold Truths", description = "We are here by order of Varimathras! The mission of the Shadowstalkers is a simple one: spy. Well, spy with a little assassination on the side.\n\nOne of my best field agents has gone missing. I haven't heard from him in days, which has left me fearing the worst. No, not death! Death would be ideal. I fear he may have gone rogue... turned traitor even.\n\nHis last known location was northern Mightstone Quarry. He was gathering intelligence on the Nerubians. Find him.\n\nHe better be dead...", objectives = "" }
WordHunterWoW_QuestEN[11615] = { title = "Nerub'ar Secrets", description = "You skim through the pages of the book, looking for anything of importance. On the last page you discover what appears to be frantic scribbling:\n\nNecrolords. At least a dozen by my count.\n\nFarms to west being used as some sort of horrible spawning glade for Scourge.\n\nRow upon row of victims.\n\nI think they're on to me. Made a dash for the hold. I won't be captured alive.\n\nDreadvenom hemotoxin. If they decide to bite into me, they'll be in for a surprise.\n\nTake this information back to Barthus.", objectives = "" }
WordHunterWoW_QuestEN[11616] = { title = "Message to Hellscream", description = "<Barthus tears out the last page and rolls it up.>\n\nTake this to Hellscream at once! In the meantime, I'm going to send a team to scout out the farms.\n\nBe sure to tell Hellscream that we're going to need reinforcements. ", objectives = "" }
WordHunterWoW_QuestEN[11617] = { title = "Hampering Their Escape", description = "I'm sure you've seen those blue and white platforms hovering over the quarry. They're the transportation the mage hunters used to land their forces here, and now they're loading them up with our artifacts and fragments of our statues.\n\nWe must stop them before they leave the quarry.\n\nThe small creatures digging in the quarry carry explosives. Take them and use them to destroy the three floating platforms. The leader keeps watch from a fourth, grounded platform, but we'll deal with him afterward.", objectives = "" }
WordHunterWoW_QuestEN[11618] = { title = "Reinforcements Incoming...", description = "<Hellscream shakes his head.>\n\nYou may not have noticed that we're trying to win a war here, {race}. I need all available soldiers at the primary points of conflict. This means that we don't have any real soldiers to spare for these minor incursions.\n\n<Hellscream pauses to think.>\n\nIf Barthus wants reinforcements at the farm...\n\n<Hellscream claps his hands together.>\n\n...he shall have them! Report to Barthus's assassins at the farms, west of here. Let them know that reinforcements have arrived.", objectives = "" }
WordHunterWoW_QuestEN[11619] = { title = "Gamel the Cruel", description = "My own father was slain by the leader of this raiding party, Gamel the Cruel.  He has made his abode inside a cave on the beach.\n\nYou've dealt with his men already.  Finish what you've started, {name}.  Avenge my father and I will share with you what little I still have.", objectives = "" }
WordHunterWoW_QuestEN[11620] = { title = "A Father's Words", description = "There is someone who might shed light on this mystery, {race}.  It is rumored that the Kvaldir have kept a naga priestess alive at the temple on the west side of the shore.\n\nShe will no doubt have great reason to resent her uninvited Kvaldir guests.  Perhaps my father is expecting her to cooperate with you in some way.", objectives = "" }
WordHunterWoW_QuestEN[11621] = { title = "The Tablet of Leviroth", description = "You scour through the tablet's etchings, looking for any text you can understand.  You finally find the following fragment:\n\n\"The sons of the fog will claim a thousand souls for the one who dwells in darkest waters.  His emissary will then awake.\"\n\nKaruk might be interested in this information.", objectives = "" }
WordHunterWoW_QuestEN[11622] = { title = "Secrets of Riplash", description = "There is someone who might shed light on this mystery, {race}.  It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple.\n\nThe high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests.  Perhaps she can tell you more about what the writing on the tablet means.", objectives = "" }
WordHunterWoW_QuestEN[11623] = { title = "A Visit to the Curator", description = "The leader of the mage hunter forces is a fearsome creature called Curator Insivius. My people have hunted the beasts of the seas and land for countless generations, but I've never seen anything like this curator before.\n\nHe's landed one of those flying disks on the upper rim of the quarry and oversees the operation from there. {name}, I can only believe the ancestors themselves sent you to my rescue and I hope you will help me drive the mage hunters from this quarry once and for all.", objectives = "" }
WordHunterWoW_QuestEN[11624] = { title = "The Sky Will Know", description = "I must find out what happened to my master, Farseer Grimwalker!\n\nEarlier, he was observing the magnataur at nearby Magmoth. But one of his grunts just returned, saying that the group had been crushed, and that the farseer was dragged into the depths of the place.\n\nBefore I send you on a suicide mission, I wish to consult with the spirits to learn more.\n\nThere is an air elemental known as Imperean in the ruins of Eldra'nath to the west. She is wise and may give you the information we seek.", objectives = "" }
WordHunterWoW_QuestEN[11625] = { title = "The Trident of Naz'jan", description = "Five hundred years ago, Azshara imprisoned a being named Leviroth in the waters below.  Now these barbarians seek to undo our queen's work!\n\nThey took over our city and began to sacrifice my brethren to awaken him!  When they ran out of naga, they began to take tuskarr.  Their spirits will know no peace!\n\nI will help you, for it will go a long way towards quelling my vengeance.  Their captain, Ragnar, dwells deep inside northeastern Riplash.  He has in his possession a golden trident.  Bring it to me!", objectives = "" }
WordHunterWoW_QuestEN[11626] = { title = "The Emissary", description = "Raj Naz'jan was the emperor of Riplash when Leviroth was imprisoned.  Azshara herself blessed his trident so it would slay the beast should it ever escape.\n\nNow you wield it, {race}.  As much as it disgusts me, I will have my revenge on these barbaric giant-men.\n\nTake the trident to the depths beneath Riplash.  You will find Leviroth below an iceberg closest to northern Riplash.\n\nDrive the trident into his flesh and slay him!  Return to whomever sent you when you're done; I wish to see no more of you.", objectives = "" }
WordHunterWoW_QuestEN[11627] = { title = "Boiling Point", description = "Ah, it is information that you crave: the whereabouts and condition of your 'farseer'. He did not see so far as to avoid the trouble which befell him.\n\nNevertheless, I will give you the means to acquire the knowledge. But first, you will do some things for me.\n\nNo doubt you have seen the war between fire and water to the south. Simmer keeps boiling Churn's pool, and the two have been battling for ages.\n\nGo to the Charred Rise and Blistering Pool, and convince each of them to stop their bickering.", objectives = "" }
WordHunterWoW_QuestEN[11628] = { title = "Shrouds of the Scourge", description = "To the northeast looms the Temple City of En'kilah, the Scourge's seat in Borean Tundra. From behind its walls, the Scourge commander has sent his Nerubians to surround us.\n\nRemaining on the defensive would doom my people, but my advisors differ in their strategies. Durm would charge in blindly, while Sage Aeire favors stealth.\n\nThe Temple City has blighted the nearby lands and the native creatures. Aeire believes the pelts of the scourged mammoths can serve as a cloak that may hide an infiltrator.", objectives = "" }
WordHunterWoW_QuestEN[11629] = { title = "Return to the Spirit Talker", description = "You have done what was asked, and now I give you that which you desire.\n\nDeliver this primal to the spirit talker back at your Bor'gorok Outpost. If she is wise, she will know a ritual to gain you the information which you seek.", objectives = "" }
WordHunterWoW_QuestEN[11630] = { title = "The Bad Earth", description = "By curing the hides with the blighted earth outside the Temple City, Sage Aeire believes she can create a cloak which will cause most of the Scourge minions to ignore your presence. You should blend right in, she says.\n\nShe'd best be correct. It's our only chance to gather information and plan our counterattack.\n\nYou should be able to find the earth she needs poking in the areas to the south and west of the fortress. Bring it to me when you've finished gathering it.", objectives = "" }
WordHunterWoW_QuestEN[11631] = { title = "Vision of Air", description = "Here, {name}, I've attuned the primal to you.\n\nOpen your soul to it in the presence of my totem of air and concentrate upon the fate of Farseer Grimwalker.\n\nThe spirit of the wind touches all; with any luck you will be granted a vision.", objectives = "" }
WordHunterWoW_QuestEN[11632] = { title = "What the Cold Wind Brings...", description = "You hold the carapace fragment of Ith'rix the Harvester and realize that this is only the beginning. Even now you sense that victory is fleeting. Surely the Lich King has a thousand more beasts like Ith'rix, waiting to be unleashed upon the Horde.\n\nTake your trophy and present it to High Overlord Saurfang, inside Warsong Hold. He should be notified of your victory over a powerful Scourge agent.", objectives = "" }
WordHunterWoW_QuestEN[11633] = { title = "Blending In", description = "Sage Aeire has finished the shroud. Take it with you and travel to the Temple City of En'kilah. Don the cloak within the city's bounds to hide yourself from most of the Scourge there. This will be our best opportunity to gather information about the enemy's fortifications and leaders.\n\nWhile wearing the cloak, scout the three large spires on the grounds of the city. While the shroud will shield you from most of the Scourge, the En'kilah abominations will be able to find you if you get too close.", objectives = "" }
WordHunterWoW_QuestEN[11634] = { title = "Wind Master To'bor", description = "You're a tough mother, {name}. I think your talents are better suited elsewhere - like the root of the whole damn problem!\n\n<Razgor points to the west.>\n\nA thousand Scourge, at least four full sized floating death machines and who knows what else.\n\nBut you're gonna find out and then you're gonna handle it... That's right, you're gonna beat the hell out of the Scourge army that's currently beating down our door.\n\nGet to the top of Warsong Hold and report to Wind Master To'bor. He'll be expecting you.", objectives = "" }
WordHunterWoW_QuestEN[11635] = { title = "Farseer Grimwalker's Spirit", description = "You must go to Magmoth to the east.\n\nYou must descend into the depths of their caverns.\n\nYou must speak with Farseer Grimwalker's spirit!", objectives = "" }
WordHunterWoW_QuestEN[11636] = { title = "Magic Carpet Ride", description = "Tanks, mon. I be talkin' bout siege machines! We got heavy tanks stationed at Garrosh's Landing on da west coast. We gonna get you to da tank and you gonna use da tank to lay down some Horde justice on da Scourge!\n\nDa only tricky part be getting' you der. No way we be sendin' you on our wind riders. Too risky.\n\nYou see dat pixie o'er der? Dat blondie elf? Yanni be his name, mon. He can get you to da coast, safely. Once der, talk to Annihilator Grek'lor!", objectives = "" }
WordHunterWoW_QuestEN[11637] = { title = "Kaganishu", description = "After my small force of grunts were killed, I was dragged down here and ritually murdered. The snobold who did this is known as Kaganishu.\n\nThough you have vanquished his shaman helpers, my spirit is still tethered to this place. After he slew me, he created a fetish from my body, which anchors me here. Kaganishu is using it to learn all that I know of shamanism.\n\nYou must retrieve the fetish from him and use it upon my spirit. Kaganishu is nearby in the caves.\n\nOnly then will I truly be free.", objectives = "" }
WordHunterWoW_QuestEN[11638] = { title = "Return My Remains", description = "{name}, now that my spirit has been freed would you do me the honor of returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath me.\n\nI sense that the spirit talker is still at Bor'gorok Outpost to the west where last I saw her.", objectives = "" }
WordHunterWoW_QuestEN[11639] = { title = "Revenge Upon Magmoth", description = "The overlord refuses to allow the shaman to heal my wounds. He says that it will be a good lesson for me and give me time to reflect upon my failure.\n\nBut you could get revenge for me and the others who fell at Magmoth!\n\nI know that the spirit talker wants you to go in there to save the farseer.\n\nIt's just to the east. Go, {class}... go slay the magnataur and their snobold servants. Regain the outpost's honor!", objectives = "" }
WordHunterWoW_QuestEN[11640] = { title = "Words of Power", description = "Within the spires you described dwell the main lieutenants of the Scourge leader, the high priests. Not only do they command the Scourge forces, but they hold the key to the necropolis above, and their master.\n\nAn endless stream of Scourge minions will overrun us if we can't find and defeat their leader. I cannot leave my people defenseless, however much Durm might want to bring the fight to the enemy. It falls to you, {name}, to slay the high priests and take the scrolls they hold.", objectives = "" }
WordHunterWoW_QuestEN[11641] = { title = "A Courageous Strike", description = "From the beginning, I've counseled that Chieftain Wintergale should assemble our mighty warriors and attack our enemy at their base. My advice has fallen on deaf ears and he has proven that he'd rather tip-toe around according to Sage Aeire's plans.\n\nI'll wait no longer. If Chieftain Wintergale is too cowardly to send our warriors into battle, perhaps you'd be willing to show him that a direct attack can succeed. Storm the Temple City of En'kilah and slay all in your path, {name}.", objectives = "" }
WordHunterWoW_QuestEN[11642] = { title = "Tank Ain't Gonna Fix Itself", description = "We need to get these tanks back up and runnin'! They ain't gonna fix themselves. Mobu's gonna be the one to handle that stuff. Talk to him and see what he needs. Maybe you can shut him up before he finally drives me into a berserker frenzy and I cleave him in two!", objectives = "" }
WordHunterWoW_QuestEN[11643] = { title = "Mobu's Pneumatic Tank Transjigamarig", description = "These wrenches are useless, buddy. I need my pneumatic tank transjigamarig to get these things up and running! Unfortunately, I left it at my old digs, on the other side of this landing. It's the beat down hut next to the stables. You're gonna have to go and get it for me, because I sure as hellfire am not going to go anywhere near the mist.\n\nOh yea, buddy, watch out for the mist. The mist is what tore up these shores.\n", objectives = "" }
WordHunterWoW_QuestEN[11644] = { title = "Super Strong Metal Plates!", description = "I need metal to patch these tanks up! Super strong metal plates can be found scattered about all across Garrosh's Landing and at the bottom of the bay.\n\nJust be careful when you're out there searching for plates. The mist is... um... AGGRESSIVE! The mist is what took out the landing and the adjoining tuskarr town. Poor little tuskarr...", objectives = "" }
WordHunterWoW_QuestEN[11645] = { title = "Dirty, Stinkin' Snobolds!", description = "Those dirty, stinkin' snobolds... they stole all of my supplies!\n\nWhat's a snobold you ask? It's like a kobold, 'cept they serve the magnataur; kinda take care of them. I know, weird!\n\nAnywho, wanna help me out? I know the little creeps stole off with all of my stuff. Stupid me thinkin' that it'd be nice and safe, packed up on the north side of the airstrip.\n\nWhy don'tcha do me a favor and head north to their stupid Magmoth. There's a cash reward if you bring all my stuff back quick!", objectives = "" }
WordHunterWoW_QuestEN[11646] = { title = "The Borean Inquisition", description = "Listen closely, {name}, for there is not a moment to spare.\n\nYour prisoner is being prepared for interrogation here in our tower. In the event that he is less than forthcoming, your assistance may be required.\n\nMake your way up to where he is being detained and tell Librarian Normantis that I've sent you to assist him.", objectives = "" }
WordHunterWoW_QuestEN[11647] = { title = "Neutralizing the Cauldrons", description = "The presence of plague cauldrons within the Temple City of En'kilah worries me greatly, {name}. It's clear that Chieftain Wintergale trusts your judgment and your knowledge of our enemy. Would you help me deal with the cauldrons as you help the chieftain carry out his plans in the Temple City?\n\nI've prepared a totem which will attack and neutralize the contents of the cauldrons. All you must do is locate the cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer to victory.", objectives = "" }
WordHunterWoW_QuestEN[11648] = { title = "The Art of Persuasion", description = "It is fortunate you're here, {race}.\n\nYou see, the Kirin Tor code of conduct frowns upon our taking certain 'extreme' measures - even in desperate times such as these.\n\nYou, however, as an outsider, are not bound by such restrictions and could take any steps necessary in the retrieval of information.\n\nDo what you must. We need to know where Lady Evanor is being held at once!\n\nI'll just busy myself organizing these shelves here. Oh, and here, perhaps you'll find this old thing useful....", objectives = "" }
WordHunterWoW_QuestEN[11649] = { title = "Motes of the Enraged", description = "Now that their little squabble is dealt with, there is still the matter of helping you and your spirit talker.\n\nAs you can see, my vassals have been enraged by the ongoing war between fire and water. This will not change anytime soon, but it will serve to your advantage.\n\nIn order to assist you, what we need are their motes. Head further into the ruins and retrieve them from the tempests.", objectives = "" }
WordHunterWoW_QuestEN[11650] = { title = "Just a Few More Things...", description = "As you may have noticed, we created the airstrip on the southern border of a magnataur den!\n\n<Crafty says something uncharitable about Fizzcrank under her breath.>\n\nThe old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb!\n\nThat's where you come in. I want you to get me everything on this shopping list. Please.", objectives = "" }
WordHunterWoW_QuestEN[11651] = { title = "Tanks a lot...", description = "Thanks for all your help, buddy. You can let Grek'lor know the tanks are ready for action. Hopefully you can clean up this place once and for all!", objectives = "" }
WordHunterWoW_QuestEN[11652] = { title = "The Plains of Nasam", description = "Once you're ready, jump into one of the tanks and drive it out to the Plains of Nasam, southeast of here.\n\nUse the tank's weapon arsenal to take down the Scourge army. If you get in a jam, the \"Meatpounder\" will tear 'em up and the land mines will finish 'em off! If you find any of our soldiers, grab 'em! One last thing, fuel tanks can be found all over the field.\n\nTry to get close enough to that structure in the center and see what's going on.\n\nIf you do all of this and live, go to Hellscream!", objectives = "" }
WordHunterWoW_QuestEN[11653] = { title = "Hah... You're Not So Big Now!", description = "That'll do her, chief! So, here's what I want ya to do....\n\nTake my blaster and head north to Magmoth. If we're gonna have a chance at all against those monsters, we need to cut them down to size... so to speak.\n\nIn order to gauge its effectiveness, I need you to slay the magnataur while the blaster's effects are still on it. Any of the crushers or mates will do, but don't bother with the offspring... they're too small to worry about.", objectives = "" }
WordHunterWoW_QuestEN[11654] = { title = "The Spire of Blood", description = "As you inspect the captured blood vial, you realize its contents are still warm. The victim must have just been bled and may still be alive.\n\nWhat use would the Scourge have for blood? They've never shown an interest in live prisoners in the past. Perhaps if you can locate the source of the blood, you'll be able to discover what the Scourge is planning.", objectives = "" }
WordHunterWoW_QuestEN[11655] = { title = "Into the Mist", description = "Across the mist to the north you will find Garrosh's Landing. To the south are the ruins of my old home, Pal'ea. Both have been ransacked by an ancient force known as the Kvaldir.\n\nThese fearsome savages slew all of my people without mercy and drove your people inland.\n\nAll that remains of the tuskarr of Pal'ea are our personal effects, taken as relics by the Kvaldir. While we are not a vengeful race, justice must be served. The tuskarr relics must be returned to me. Enter the mist and find them...", objectives = "" }
WordHunterWoW_QuestEN[11656] = { title = "Burn in Effigy", description = "Tuskarr magic is similar to what your people call shamanism. While we serve the elements differently than you, the power that we are able to call forth is formidable.\n\n<Waltor waves a torch-like baton in front of you.>\n\nWith this tuskarr torch I want you to return to the mist and strike at the Kvaldir vessels. You will find three of their vessels docked behind the mist at Garrosh's Landing, north of here, and one docked off the shores of Pal'ea, to the south. Burn their ships in effigy! For all to see!", objectives = "" }
WordHunterWoW_QuestEN[11657] = { title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches. Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up! Catch four then come back to me.\n\nCareful! They're dangerous if they hit the ground! Good luck!", objectives = "" }
WordHunterWoW_QuestEN[11658] = { title = "Plan B", description = "Okay, don't panic! The blaster might not've worked, but we still have options.\n\n<Crafty snaps her fingers.>\n\nWe're going to divert attention away from the airstrip! To make this work, we'll need a few things first.\n\n<Wobblesprocket looks you up and down appraisingly.>\n\nSteeljaw's caravan, just to the west, stupidly took a shortcut through a taunka graveyard and was destroyed by their risen spirits.\n\nHead over there and get some outfits off of the dead orcs. Pick up one of their banners, too!", objectives = "" }
WordHunterWoW_QuestEN[11659] = { title = "Shatter the Orbs!", description = "They're... bleeding the prisoners... putting the blood... in those globes.\n\n<Grumm's eyes close momentarily and he leans his head back.>\n\nThe blood... taken up to necropolis... to feed blood prince...\n\n<Grumm gasps for breath.>\n\nP-promise... you'll... destroy blood... globes... bring word... to Junek.\n\n<The snow tracker collapses into unconsciousness.>", objectives = "" }
WordHunterWoW_QuestEN[11660] = { title = "Horn of the Ancient Mariner", description = "A Kvaldir lieutenant known as Orabus directed the initial incursion against my people at Pal'ea, He oversaw the destruction of both villages and then disappeared into the mist.\n\nIn those early days there was talk of a horn that Orabus gifted to the Kvaldir mistweavers. This horn could be used to summon him should the need arise.\n\nWe need to get that horn from the Kvaldir mistweavers and call forth Orabus. If he is destroyed, these savages might retreat.\n\nSeek out mistweavers at Pal'ea, to the south.", objectives = "" }
WordHunterWoW_QuestEN[11661] = { title = "Orabus the Helmsman", description = "Take the horn and travel west to the Warsong Jetty. Make your way to the end of the jetty and blow into the horn. The sound should rouse Orabus.\n\nSlay the foul beast and return to me!", objectives = "" }
WordHunterWoW_QuestEN[11662] = { title = "Seek Out Karuk!", description = "A fellow survivor of Pal'ea known as Karuk has made his way to the main base of the Kvaldir in the Borean Tundra - far to the south where the snow was once bountiful. Karuk hides along the bluffs overlooking Riplash Strand.\n\nSeek out Karuk and let him know what you did for my people here at the Coast of Echoes.\n\nThe safest route to Karuk is through your fortress. From Warsong Hold, take the road south and follow it around until you reach Riplash Strand.", objectives = "" }
WordHunterWoW_QuestEN[11663] = { title = "Sharing Intelligence", description = "Thank you, {class}! The information you've extracted is of vital importance to the Kirin Tor.\n\nReturn at once to Donathan as we make plans for the rescue of Lady Evanor.", objectives = "" }
WordHunterWoW_QuestEN[11664] = { title = "Escaping the Mist", description = "I can hear the mist creatures outside. Their yells are driving me mad, but I dare not try to escape. And where would I even go? How long would it be until they caught up with me and executed me like the others?\n\nI wonder, how far has the mist crept, stranger? Has it overtaken this whole continent?\n\nWould you be willing to help me try and escape the mist? I think I can lead us back toward my father. I still sense his life spirit. He is close.", objectives = "" }
WordHunterWoW_QuestEN[11665] = { title = "Crocolisks in the City", description = "Hello lad.  I'm glad you've stopped by to talk to this old man--there's trouble back home.\n\nA traveling merchant recently sold a batch of baby crocolisks to some gullible children.  Crocolisks are wild beasts, and many have escaped and now lurk in city waterways.\n\nGrab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me.  I'm anxious to see one.", objectives = "" }
WordHunterWoW_QuestEN[11666] = { title = "Bait Bandits", description = "You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests.  But here's one you haven't heard of: the blackfin darter.\n\nThe fish is notoriously crafty and difficult to catch.  You have to pull your line at the last possible second, because they nibble at the bait before they take it.\n\nDrop your line in the rivers of Terokkar and bring me a blackfin darter.  Avoid the lakes, as the blackfin only thrive in moving water.", objectives = "" }
WordHunterWoW_QuestEN[11667] = { title = "The One That Got Away", description = "Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand.  They grow their entire lives and are well known as fighters.\n\nYears ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped.\n\nA fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.", objectives = "" }
WordHunterWoW_QuestEN[11668] = { title = "Shrimpin' Ain't Easy", description = "There's a lot of big fish in the Zangarmarsh lakes.  Ever wonder what they eat?\n\nShrimp.  Giant freshwater shrimp.  The Rokk tells me the dishes you can make with shrimp are nearly endless.\n\nBut shrimp are too small to catch with a fishing line.  So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.", objectives = "" }
WordHunterWoW_QuestEN[11669] = { title = "Felblood Fillet", description = "This old man is going hunting soon.  I'm gonna take down a mammoth shark off the coast of Azshara.\n\nThe thing is, I need a toxin that'll stay on a spear tip while it's underwater.  To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper.\n\nSuch a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley.  Bring me back a whopper and I'll be a happy old man.", objectives = "" }
WordHunterWoW_QuestEN[11670] = { title = "It Was The Orcs, Honest!", description = "With all of those outfits you, er, recovered, I fashioned a Warsong orc disguise. I had the genius idea of combining it with some old stuff that I had left hanging around from last Hallows' End, so it should be foolproof!\n\nHere, in this sack is the disguise and the banner you recovered. Head down into the bowels of Magmoth and slay the magnataur chieftain, Magmothregar.\n\nIf you're going to convince them to turn their attention on the Warsong orcs, you'll need to plant the banner while disguised.", objectives = "" }
WordHunterWoW_QuestEN[11671] = { title = "A Race Against Time", description = "So it's true. They have her.\n\nIt's clear what must be done, {race}. She WILL be saved.\n\nI must remain here and aid in the rescue preparations. I call upon you again; this time to collect the prison key. All we know of this Salrand figure is that she cannot be harmed so long as her shield is intact.\n\nWe've customized a special explosive that should strip her of this protection, allowing you to perform your duty. Return to me when you've collected the key.\n\nHurry, {name}. Lady Evanor is suffering!", objectives = "" }
WordHunterWoW_QuestEN[11672] = { title = "Enlistment Day", description = "You've come to enlist, right?  Normally you'd have to stand in line like the other recruits.  Normally you'd be out of luck because the recruitment ledger's gone missing and I can't process anyone until the new books get here.\n\nFortunately for you, {name}, I've heard about you and what you did in Outland.  To be honest, you're a cut above these poor saps.  Lines aren't for you.\n\nGo to the barracks and speak to General Arlos.  He'll be more than happy to meet with someone of your caliber.", objectives = "" }
WordHunterWoW_QuestEN[11673] = { title = "Get Me Outa Here!", description = "I knew they'd send someone for me sooner or later... turned out to be later, of course.\n\nI came in here to parlay with the snobolds, but their main shaman, Kaganishu, decided instead that I'd make a tasty snack for Magmothregar.\n\nWait... what?! They didn't send you?!\n\nDID THEY FORGET ABOUT ME?!\n\nOkay, you're here now and that's all that matters.\n\nAs soon as you break this chain we'll make our way back to the airstrip. Then you can tell Fizzcrank I'm safely back.\n\nIf he remembers me, that is.", objectives = "" }
WordHunterWoW_QuestEN[11674] = { title = "Sage Highmesa is Missing", description = "There are many new mysteries walking the lands now. One of our sages, Highmesa, has foolishly gone north with only one longrunner to investigate something strange near the Dens of Dying.\n\nWhat are the dens, you ask? They are a sacred place to the magnataur, where they go in their old age to die. She saw something fall from the sky near them a few days ago.\n\nIf you would be friend to the taunka, I would have you find and help her. She is not so stubborn that she will not accept your aid.", objectives = "" }
WordHunterWoW_QuestEN[11675] = { title = "A Proper Death", description = "The magnataur at the Dens of Dying have contracted a plague. We must find the cause, but first we must put them out of their misery.\n\n{race}, you must go north onto the slopes in front of us and destroy as many of the poor creatures as you can.", objectives = "" }
WordHunterWoW_QuestEN[11676] = { title = "Merciful Freedom", description = "The soldiers that they didn't kill are being held in cages scattered across this farmland. Through some thievery we've managed to find a few keys, but we're unable to get close enough to any prisoners without being attacked.\n\nWe need your \"talents\" in securing those keys and freeing the prisoners. Bash in the brains of the necrolords and aberrations and take their keys. Use those keys to free Scourge prisoners.", objectives = "" }
WordHunterWoW_QuestEN[11677] = { title = "Stop the Plague", description = "I'm convinced that the plague is being caused by something in the caves up there.\n\n{class}, I want you to take these seeds. I normally use them as a ward against the Scourge, though perhaps they can be used to disrupt whatever foulness is happening in the dens.\n\nFind the source of the plague and throw them into it.", objectives = "" }
WordHunterWoW_QuestEN[11678] = { title = "Find Bristlehorn", description = "Bristlehorn should have returned by now.\n\nThe other reason why we came up here was to investigate that Scourge structure to the west, which fell from the sky. He's impetuous and has likely gotten himself into trouble.\n\n{name}, go to that place and find him, please.", objectives = "" }
WordHunterWoW_QuestEN[11679] = { title = "Reforging the Key", description = "Delays, delays... the one thing we cannot afford right now!\n\nAs much as I hate to disturb Lord Surristrasz, he's our only hope of saving our beloved Evanor.\n\nBring him the key fragments and hope that his mood is favorable.\n\nHurry, {class}, our assault team is waiting.", objectives = "" }
WordHunterWoW_QuestEN[11680] = { title = "Taking Wing", description = "The key is forged anew.\n\nNow heed my counsel, {race}. Succeed in your endeavor or die trying, for if a single scale falls from one of my drakes I shall hold you personally accountable.\n\nNow, off with you.", objectives = "" }
WordHunterWoW_QuestEN[11681] = { title = "Rescuing Evanor", description = "At last, we attack!\n\nOnce we've cleared the platform I'll use the key.\n\nYou are to ensure that Lady Evanor remains safe after her release.\n\nHurry now, let us be off!", objectives = "" }
WordHunterWoW_QuestEN[11682] = { title = "Dragonspeak", description = "I am aware of your recent deeds here, {name}, and again I thank you.\n\nAs for this local menace, we've learned all we need to know from them. They'll be dealt with in short order. On now to more important issues....\n\nAzeroth needs you. The region just west of here is the center of an urgent crisis.\n\nI'll leave the details to Lord Surristrasz. You must speak with him at once.\n\nGood luck, friend of Dalaran.", objectives = "" }
WordHunterWoW_QuestEN[11683] = { title = "Fallen Necropolis", description = "The fallen necropolis to the west can only be assumed to still be filled with Scourge.\n\nWhile you are at Talramas, {class}, I would ask that you dispatch all of the Lich King's servants that you find within and in the surrounding pools where it fell.", objectives = "" }
WordHunterWoW_QuestEN[11684] = { title = "Scouting the Sinkholes", description = "Can you feel the tremors in the earth?\n\nThe Scourge's nerubians are on the move deep beneath the ground. They've emerged to the southwest in the Geyser Fields, and are harassing the patrols Chieftain Wintergale sent out.\n\n<The taunka elder offers you a worn map.>\n\nPerhaps a single person can succeed where the patrols have failed. Take this with you to the Geyser Fields and map out the locations of the Nerubian sinkholes.", objectives = "" }
WordHunterWoW_QuestEN[11685] = { title = "The Heart of the Elements", description = "Now that we know the exact locations of the nerubian sinkholes, we can collapse them to halt the Scourge offensive and cripple their force. Wind Tamer Barah knows a way to harness elementals to destroy the tunnels the Nerubians are using, but she will require your help.\n\nSoutheast of the village, near the coast beyond the Frozen Reach, you'll find an area dominated by frozen earth elementals. The hearts of these elements are exactly what Wind Tamer Barah will need.", objectives = "" }
WordHunterWoW_QuestEN[11686] = { title = "The Warsong Farms", description = "According to Luther's notes the Scourge is now using this place as a breeding ground for those monsters you see lumbering across the field.\n\n<Ickoris shudders.>\n\nThose monsters were once orcs... tauren...\n\nWe need more information before a plan can be devised. I want you to investigate three sites that are heavily trafficked by Scourge: the Warsong Granary, southwest of us, Torp's Farm, directly west of us, and the old Warsong Slaughterhouse, north of us.\n\nReturn to me once you've scouted 'em out.", objectives = "" }
WordHunterWoW_QuestEN[11687] = { title = "The Doctor and the Lich-Lord", description = "There are two... that must... be killed.\n\nThe doctor and... the lich-lord... are above. Find them... destroy them... before....\n\n...it is too... late....", objectives = "" }
WordHunterWoW_QuestEN[11688] = { title = "Damned Filthy Swine", description = "Just look at 'em! My beautiful kodos are helpless to defend themselves against those filthy swine! I need you to buy me some time, {race}. I think I can cure the kodo of the sickness, but you need to keep the unliving swine off 'em, else there'll be nothin' left to cure!\n\nGet out there and send those swine to their graves - permanently!", objectives = "" }
WordHunterWoW_QuestEN[11689] = { title = "Return with the Bad News", description = "The greatmother will need to know, {name}.\n\nWill you please return to Taunka'le? Tell her that I will be following shortly.", objectives = "" }
WordHunterWoW_QuestEN[11690] = { title = "Bring 'Em Back Alive", description = "Take this riding snaffle, {name}. You'll notice that I've placed a tiny medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a kodo bites down. Once you've cured the sick out of 'em, you'll need to ride 'em home. They'll be weak so you'll need to gently direct 'em here.\n\nBring my babies back, {name}!\n\nOne last thing, you've got ten minutes! That's how long the antidote will remain effective inside that snaffle.", objectives = "" }
WordHunterWoW_QuestEN[11691] = { title = "Summon Ahune", description = "I and my Shamans have gathered our powers for the coming battle with the Lord of Frost.  {name}, you will be the fist of the Earthmother.\n\nTake this magma totem.  Use it against the Ice Stone, to the northeast.  Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes.\n\nIf fortune is with us, then, perhaps, we can defeat him.\n\nPrepare yourself, {name}.  If Ahune comes to face us, then his fury will be great.", objectives = "" }
WordHunterWoW_QuestEN[11692] = { title = "Check in With Bixie", description = "You're a proven hero. I have another problem!\n\nMy boss, Tinky, went east with Bixie Wrenchshanker and I CAN'T get the outgoing on this thing to work! Tinky's the only one that can fix it and we really need it working one-hundred percent.\n\nYou think you could find them? Bixie said something about following some old magnataur to a place called The Dens of Dying.\n\nI'm guessing that's where you'll find them.\n\nYou can catch a ride out there by talking with Kara Thricestar at the runway.", objectives = "" }
WordHunterWoW_QuestEN[11693] = { title = "Oh Great... Plagued Magnataur!", description = "Tinky and I came out here stalking some old magnataur. Apparently those caves up there are where they go to die.\n\nOf course, we had no idea that they were going to get plagued when they went in there. We can't have plagued things just roaming about; it's not healthy.\n\nSay, why don't you put down a number of those things while I figure out what our next step should be?", objectives = "" }
WordHunterWoW_QuestEN[11694] = { title = "There's Something Going On In Those Caves", description = "So, while you were out taking care of those plagued beasts, I took a peek inside the caves up there.\n\nThere are cultists in there plaguing them!\n\nThey have some sort of noxious concoction brewing in a cauldron. I have a powder that I normally use as an anti-poison, and I mixed it up with some other stuff. I think it'll neutralize their brew!\n\nTake it up to one of those caves and see if it works.", objectives = "" }
WordHunterWoW_QuestEN[11695] = { title = "The Horn of Elemental Fury", description = "I can fashion the likeness of an elemental from these pieces of inanimate stone, but breathing life into it is different. For that, we'll need help and a bit of luck.\n\nLegend tells of an ancient artifact called the Horn of Elemental Fury, sought after by a great hero. I'll lend you a scroll with a copy of the tale. I don't know if the legend is true, but it's our best bet. If the legend is right, the parts of the horn may be in the Flood Plains surrounding the village to the north and southwest.", objectives = "" }
WordHunterWoW_QuestEN[11696] = { title = "Ahune is Here!", description = "{name}, your presence is a blessing.  Ahune lies within these caverns, gathering strength for his assault.  Earthen Ring forces were sent ahead, but they alone cannot defeat him.\n\nExplore, {name}.  Find our Earthen Ring Shamans and speak with their leader, Luma Skymother.  Perhaps, with your added strength, we can beat Ahune before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[11697] = { title = "Rats, Tinky Went into the Necropolis!", description = "I told Tinky not to go off on her own, but she just HAD to check out that crashed necropolis to the west.\n\nI'm 100% certain that those cultists came from inside that thing, which means I'm now 100% certain that Tinky's in trouble!\n\nShe's the airstrip's number one engineer. Without her we're doomed!\n\nI'd find her myself, but one of those things got in a swipe on my leg before I could vanish again. {name}, if anyone can get her out, it's you!", objectives = "" }
WordHunterWoW_QuestEN[11698] = { title = "Might As Well Wipe Out the Scourge", description = "If the cultists up in those caves survived the crash, then that fallen necropolis to the west can only be assumed to still be filled with Scourge. There're probably lots of them out in front of it in the pools, too!\n\nWhile you're at Talramas, {class}, do you think you could dispatch all of the Lich King's flunkies that you find there?", objectives = "" }
WordHunterWoW_QuestEN[11699] = { title = "I'm Stuck in this Damned Cage... But Not For Long!", description = "The cultists magicked me into this cage and there's no door to it. Little did they know that I'm the chief transmatter engineer for the airstrip!\n\nWith your help, and a little elbow-grease, I won't be in here for long.\n\nI'm going to need an engine-core crystal from one of the ghouls in here, a magical gyroscope from their doctor, and a piloting scourgestone from the lich-lord up top.\n\nWith all of that stuff, I should be able to make a port device to get back to Fizzcrank's and escape the gnome way!", objectives = "" }
WordHunterWoW_QuestEN[11700] = { title = "Let Bixie Know", description = "My evil twin's out there somewhere now.\n\nI'm pretty sure that she's not back at the airstrip. In fact, wherever she ended up, it's colder there than here. But I could only 'feel' her for a moment.\n\nOh well, I'll reconfigure this thing and port myself back to the airstrip soon enough. In the meantime, do you think you could go east and let Bixie know that I'll meet her back there?\n\nThanks, {name}!", objectives = "" }
WordHunterWoW_QuestEN[11701] = { title = "Back to the Airstrip", description = "Okay, I think I'm going to start making my way back to the airstrip, too. Of course, I'm moving a little slower with this leg injury.\n\nSay, do you think you could get there ahead of me and pass on the good news to Ol' Fizzcrank? I bet anything that there'll be a reward in it for you.\n\nThanks, {name}!", objectives = "" }
WordHunterWoW_QuestEN[11702] = { title = "King Mrgl-Mrgl", description = "Dis is gonna sound weird, {class}, but dere be a murloc askin' for our help!\n\nHe goes by da name of King Mrgl-Mrgl, leader of da Winterfin murlocs. Him and his people been run outa dere village and wantin' you to come save dem.\n\nYou find him by headin' west and go down da cliffs. He hangin' out on da south side of da Winterfin Retreat.", objectives = "" }
WordHunterWoW_QuestEN[11703] = { title = "Get to Getry", description = "The Scourge agent that's overseeing the abduction and transformation of Horde soldiers into undead monsters is using the northwest farm as a spawning glade. Shadowstalker Getry has been staking out that monster for the past week and has gathered some vital information that might allow us to end this menace.\n\nGet to Getry and see if you can help him put a stop to this Scourge assembly line. You'll find Getry at the abandoned tower on the northwest border of these farms.", objectives = "" }
WordHunterWoW_QuestEN[11704] = { title = "King Mrgl-Mrgl", description = "This is the weirdest thing, {class}, but there's a murloc asking for our help!\n\nHe goes by the name of King Mrgl-Mrgl, leader of the Winterfin murlocs. It would seem that he and his people have been run out of their village and they want someone to come save them.\n\nThat someone is you!\n\nYou'll find Winterfin Retreat, and the king, by heading west down the road until you come to the cliffs. Head down to the water line near the Blistering Pool.", objectives = "" }
WordHunterWoW_QuestEN[11705] = { title = "Foolish Endeavors", description = "This is madness. How do they expect us to take on a Scourge necrolord and an unknown number of his minions?\n\n<Getry sighs.>\n\nIf Ickoris sent you he must think that you are capable of great feats. Perhaps you will call down a miracle today, eh?\n\nWhen you're ready we will descend and face Varidus.\n\nIf we make it out of this mess in one piece, report back to Hellscream in Warsong Hold.", objectives = "" }
WordHunterWoW_QuestEN[11706] = { title = "The Collapse", description = "I have created and bound Alluvius using the Horn of Elemental Fury. He will respond to the horn's call when you stand near the southernmost sinkhole in the Geyser Fields.\n\nThe quake Alluvius will unleash should collapse the Nerubian tunnels and put an end to their flanking attack. I wouldn't be surprised if the Nerubian commander showed himself after the quake. If the collapse of the tunnels doesn't break the back of their assault, the defeat of their leader surely will.", objectives = "" }
WordHunterWoW_QuestEN[11707] = { title = "Distress Call", description = "Oh good, you're {name}, right?\n\nWe need your help up north at Fizzcrank Airstrip, like yesterday! The magnataur, and the Scourge... and the pumping station!\n\nIt's madness I tell you, madness!\n\nYou've got to head up there and talk to old man Fullthrottle a.s.a.p.!", objectives = "" }
WordHunterWoW_QuestEN[11708] = { title = "The Mechagnomes", description = "Now that you're here, it's time for me to tell you the full story of what's going on.\n\nAfter you've heard my tale, go outside and find my second-in-command, Jinky Wingnut. She'll handle everything from here on out.", objectives = "" }
WordHunterWoW_QuestEN[11709] = { title = "Nork Bloodfrenzy's Charge", description = "While you have done much to secure our foothold in these frozen wastes, other dangers still lurk in the shadows. I want you to assist Warden Nork Bloodfrenzy, stationed at the internment camp just outside and immediately southeast of Warsong Hold. Seek him out and offer your assistance for prisoner transport and exchange.\n\nYou are dismissed, {name}. ", objectives = "" }
WordHunterWoW_QuestEN[11710] = { title = "What's the Matter with the Transmatter?", description = "There're spare parts strewn all over to the east in the Scalding Pools, the Geyser Fields... heck, probably even up on the pumping station still, too. Bring back a whole bunch. Maybe then I'll be able to get outgoing teleport on this thing working, not to mention getting the incoming transmatter ports aligned.\n\nI'd hate to see another accident....", objectives = "" }
WordHunterWoW_QuestEN[11711] = { title = "Coward Delivery... Under 30 Minutes or it's Free", description = "We're seeing more deserters show up at our gates with each passing day. We simply do not have enough room to keep all of these maggots caged up. Especially not if we want to keep the pigs happy.\n\n<Nork snorts as he laughs.>\n\nI want you to escort one of these cowards to the crossroads east of here and fire this flare gun. One of their captains will show up when they see the flare and take the coward off your hands.\n\nReport to Scout Tungok on the east road once the delivery has been made.\n", objectives = "" }
WordHunterWoW_QuestEN[11712] = { title = "Re-Cursive", description = "If you listened to the old man, then you know that we have gnomes out there that were changed. Gearmaster Mechazod infected them with something that reversed the \"Curse of the Flesh\", and now they're robots!\n\nWe think we have a way to re-curse them back to normal. We want you to take this re-cursive transmatter injection and use it on the corpses of any mechagnomes you come across.\n\nWe're hoping that this stuff will cure them and allow us to lock onto them to port 'em out of there.\n\nWhaddya say, {name}?", objectives = "" }
WordHunterWoW_QuestEN[11713] = { title = "Scouting the Sinkholes", description = "Fizzcrank sent out an aerial surveillance team to map the Nerubian sinkholes in the southern part of the Geyser Fields, but they haven't yet returned. I can't afford to wait any longer for their information, so I'm going to need someone to check out the sinkholes on foot.\n\nI understand the dangers involved, and I'll compensate you accordingly. Take this map with you and record the vital information about each of the sinkholes you encounter out there.", objectives = "" }
WordHunterWoW_QuestEN[11714] = { title = "Vermin Extermination", description = "Perhaps you'd be interested in helping me clean up these fields? They're littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call 'em, they're all over the damned place. The stink alone is making my life hell!\n\nTake care of the vermin for me and I'll make it worth your while, {name}.\n", objectives = "" }
WordHunterWoW_QuestEN[11715] = { title = "Fueling the Project", description = "I plan to build a machine that will collapse the tunnels the Scourge is using to deploy their Nerubians, but with the main drilling rig out of order, we'll have to collect the fuel for the device some other way.\n\nOut in the Geyser Fields to the southeast, small pools of oil bubble up away from the main rig. If you can collect enough of the oil from those pools, I can make a crude fuel to power the machine.\n\nSimply deploy the collector near the rig, and it will pump and store the oil in its tank.", objectives = "" }
WordHunterWoW_QuestEN[11716] = { title = "The Wondrous Bloodspore", description = "We are witnessing something amazing here, {race}. A whole undiscovered ecology lives and breathes not more than a few paces from us! I surmise it is the bloodspore plant that sets this environment abuzz.\n\nI have collected some pollen from the nearby male species of bloodspore plant but still lack female receptors for pollination. Fetch me a bushel of the bloodspore carpels. You'll find them near the larger plants surrounding us.\n\nBe wary of their guardians! The kobolds won't give them up easily!", objectives = "" }
WordHunterWoW_QuestEN[11717] = { title = "Pollen from the Source", description = "It's obvious! The bloodspore moths are the entities responsible for pollination on these plains. It must be something that happens within the moth's internal system that acts as a catalyst for this pollen to work. It's all starting to make sense now, {name}. That's why the kobolds don't kill the moths and instead go to great lengths to protect them! Those stupid little rats have it all figured out!\n\nWell we'll just have to get our own moth pollen! What do you say? Fetch me some in the name of science?", objectives = "" }
WordHunterWoW_QuestEN[11718] = { title = "A Bot in Mammoth's Clothing", description = "I've reconfigured the skeleton of an old bot to create an earthquake large enough to collapse the tunnels, but the machinery is delicate and sensitive to Northrend's biting cold.\n\nI've devised a means of insulating it using the thickest hides of the native mammoths. They roam the plains south of the airstrip and adjacent to the Geyser Fields. Bring back enough of the hides for me to finish the machine and then we'll be able to unleash it on the Nerubians!", objectives = "" }
WordHunterWoW_QuestEN[11719] = { title = "A Suitable Test Subject", description = "<Laurith looks you over as if to size you up.>\n\nSo we've got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What's the worst that could happen anyway?\n\nDon't you worry, {name}! Just take this sample and rub it all over your face. ", objectives = "" }
WordHunterWoW_QuestEN[11720] = { title = "The Invasion of Gammoth", description = "Hellscream assigned Mighthorn and I with the daunting task of magnataur extermination on the southern front of Warsong Hold. With us came an entire platoon of seasoned Horde soldiers. Our initial foray into the nearby magnataur dens proved quite unsuccessful as our entire squad was wiped out by the lair defenders. We're the only ones left...\n\nWe aren't scientists or researchers. We're soldiers of the Horde, just like you. Soldiers on a mission that cannot fail...\n\nSpeak to Primal Mighthorn now.", objectives = "" }
WordHunterWoW_QuestEN[11721] = { title = "Gammothra the Tormentor", description = "Magnataur live in prides, much like lions: one or two dominant males and several females along with their offspring. In the case of Gammoth, the magnataur den west of here, Gammothra is the leader. It is Gammothra that controls this magnataur population and therefore it is Gammothra that must be slain to prevent any type of magnataur uprising.\n\nTake this pouch of crushed bloodspore flower to Gammoth. Use the powder from the pouch to weaken Gammothra and then slay him! Return his head to me as proof.", objectives = "" }
WordHunterWoW_QuestEN[11722] = { title = "Trophies of Gammoth", description = "We cannot take all of the credit for this Horde victory, {name}. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra.\n\nHonor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.", objectives = "" }
WordHunterWoW_QuestEN[11723] = { title = "Deploy the Shake-n-Quake!", description = "Behold, the machine that will save us from the Nerubian threat!\n\n<Abner beams with pride as he presents the finished bot.>\n\nTake this remote control with you, and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the remote to activate the Shake-n-Quake 5000. It will do the rest on its own.\n\nDon't be surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, it would be a great opportunity to finish off the Nerubian offensive.", objectives = "" }
WordHunterWoW_QuestEN[11724] = { title = "Massive Moth Omelet?", description = "This egg was obviously important to somebody, as the corpse nearby can attest. As you look the egg over you notice that it has already been tagged for shipment to the Bloodspore Plains, care of Bloodmage Laurith. That's just east of here!\n\nCollect the egg and take it to the expectant Bloodmage.", objectives = "" }
WordHunterWoW_QuestEN[11725] = { title = "Finding Pilot Tailspin", description = "I should've flown the mission myself. It's not that I don't trust Tailspin. Far from it. Heck, he was the best wingman I ever flew with.\n\nNo, it's just that it's my responsibility to lead a mission of such import.\n\nI sent Tailspin out with our fastest recon squadron to gather information about the Nerubian infestation in the middle of the Geyser Fields.\n\nThe last report we received placed his squadron in the pools to the far south and just west of the Nerubian sinkholes.\n\nFind Tailspin, {name}.", objectives = "" }
WordHunterWoW_QuestEN[11726] = { title = "A Little Bit of Spice", description = "The wolves have been pawing through the wreckage ever since the crash and I'm afraid they consumed the microfilm from our mission in the process.\n\nI have a plan to recover that microfilm, but I need your help to make it work.\n\nTo the south and east, in the Flood Plains, live creatures called gorlocs. They prepare their foods with noxious spices, which would sicken any other creature. If you can gather enough of the spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.", objectives = "" }
WordHunterWoW_QuestEN[11727] = { title = "A Time for Heroes", description = "It's good to have you among us, {name}.  We've all heard of your past deeds.\n\nAs you know, King Wrynn is moving great armies into Northrend to meet those of Arthas.  But armies are nothing without true heroes to inspire and lead them.\n\nI want you to be that hero for my men.  Fight alongside them against the Scourge that lays siege to our stronghold.\n\nReport to Sergeant Hammerhill outside the inner hold.  Valiance Keep cannot fall.  The future of our campaign depends on it.", objectives = "" }
WordHunterWoW_QuestEN[11728] = { title = "Lupus Pupus", description = "Whatever you do, don't eat this bait yourself. Just set it down in the vicinity of an oil-soaked wolf. If they're desperate enough to eat the microfilm, they'll come running when they smell the bait.\n\nSimply wait for nature to take its course and then all you need to do is search the, uh... byproduct for the film.\n\nI'd offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. I'm afraid you'll have to conduct the... err... search the old-fashioned way.", objectives = "" }
WordHunterWoW_QuestEN[11729] = { title = "The Ultrasonic Screwdriver", description = "The unit you just dismantled had this inside of its mechanical innards.\n\nIt looks pretty complicated... certainly someone back at the airstrip would want to take a look at it. Maybe Crafty Wobblesprocket?", objectives = "" }
WordHunterWoW_QuestEN[11730] = { title = "Master and Servant", description = "The Ultrasonic Screwdriver is the ultimate tool. It can do anything to mechanical stuff!\n\nHead back into the pools and dismantle a number of Mechazod's robots. Then all you have to do is use the screwdriver on their remains, and I'm betting that they'll turn to our side, for a short time anyway.\n\nI'm pretty sure it won't work on the mechagnomes, so don't even bother with them.\n\nOh, and if you want to take anything from the robot's insides, you'll want to do so before using the screwdriver!", objectives = "" }
WordHunterWoW_QuestEN[11731] = { title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lesson.", objectives = "" }
WordHunterWoW_QuestEN[11732] = { title = "Desecrate this Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[11733] = { title = "Traversing the Rift", description = "I've been mindful of your efforts, mortal. Do not feign surprise. Surely you've felt my eye upon you.\n\nThe time has come to peel back a layer of darkness from your mind. There are stark truths that you have grown ready to accept.\n\nBefore hearing the tale, you shall be shown firsthand what we face.\n\nPut your affairs in order, {class}....", objectives = "" }
