WordHunterWoW_QuestEN[11788] = { title = "Lefty Loosey, Righty Tighty", description = "Okay, I think we're ready for the penultimate assault... before you can bring down Mechazod, you're going to have to dismantle his lieutenants first!\n\nYou'll find Twonky, ED-210, Max Blasto, and The Grinder at the West Point, North Point, Mid Point and South Point stations, respectively.\n\nTo get them to show up, just turn the valves at the stations to mess up whatever they're trying to do out there. You can't miss the places, they all have spinning lights.", objectives = "" }
WordHunterWoW_QuestEN[11789] = { title = "A Soldier in Need", description = "You there!  Please, I need your help.  This soldier will succumb to the cryptfiends' venom unless we act immediately.\n\nI've managed to slow down the poison, but without a suitable supply of antidote I cannot counteract it.\n\nI was promised a new shipment of anti-venom in the Stormbreaker's most recent trip from the south.  Go inside its hold and search for a chest of first aid supplies.\n\nHurry, {class}!  We can't afford to lose any more men unnecessarily.", objectives = "" }
WordHunterWoW_QuestEN[11790] = { title = "Cultists Among Us", description = "This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.\n\nPerhaps he is to be found above deck.", objectives = "" }
WordHunterWoW_QuestEN[11791] = { title = "Notify Arlos", description = "We must notify General Arlos at once.  I've known the captain for a long time and, believe me, he is one of the more careful ones.\n\nWho knows how many cultists have been smuggled into our settlements in Northrend in other ships?  This could be disastrous.", objectives = "" }
WordHunterWoW_QuestEN[11792] = { title = "Enemies of the Light", description = "Not so fast there.  I don't know about you, {class}, but I was hardly convinced by the general's words.  They rung unsure... as if they were not his own.\n\nSomething's amiss here.  All of our efforts to collaborate have been blocked and delayed.  It is time we took a more independent approach.\n\nIf we're to learn more about the cultists inside the keep... perhaps we should investigate those outside.\n\nIntelligence reports a small group of them aiding the Scourge north of here.  See if they carry any clues.", objectives = "" }
WordHunterWoW_QuestEN[11793] = { title = "Further Investigation", description = "I'm afraid this is a matter I must delegate to one of my operatives... someone who can work in secret.  Keep the evidence with you and take it to Vindicator Yaala inside the inn.\n\nTell her I sent you and speak of this matter to no one else.  We do not know who might be working for the cult.", objectives = "" }
WordHunterWoW_QuestEN[11794] = { title = "The Hunt is On", description = "I've made it my business to learn as much as possible about the vile death cult, including their secret language.\n\nVurenn was right.  The cultists mention disguised operatives in various locations in Valiance Keep: the lower docks, the jail inside the inner hold and in the inn's kitchen.\n\nTake this oculus.  Use it at those three locations - anyone that has recently used the cult's necromancy will be enshrouded by a dark aura.  Take care of the cultists before something nefarious happens.", objectives = "" }
WordHunterWoW_QuestEN[11795] = { title = "Emergency Protocol: Section 8.2, Paragraph C", description = "Injured or not, as squadron commander, I'm responsible for locating and returning the insignia of all fallen pilots under my command. In all the years I've flown with Fizzcrank, we've never failed to return the signet of a pilot.\n\nMy injuries make it dangerous for me to stray far from the safety of the wreckage, but perhaps you would be willing to help me recover the insignia? In the meantime, I'll make preparations to carry out my final duty as squadron commander.", objectives = "" }
WordHunterWoW_QuestEN[11796] = { title = "Emergency Protocol: Section 8.2, Paragraph D", description = "There's only one more thing left to do before I can finally return to the airstrip and make my report. Section 8.2, paragraph D of the emergency protocol requires me to scuttle as much of the wreckage as possible, in order to prevent our technology from falling into enemy hands.\n\nI'll give you my torch if you agree to help me complete this last duty. I don't want to think about what the Horde's goblin allies will do if these machines fall into their hands.", objectives = "" }
WordHunterWoW_QuestEN[11797] = { title = "The Siege", description = "Well, well, well.  It's good to see Arlos bring out the big guns.\n\nDon't get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us.  I'm not sure how much longer we can hold out against these undead Nerubians.\n\nWhat do you say you get out there and kill me some creepers?  Show these boys how it's done.", objectives = "" }
WordHunterWoW_QuestEN[11798] = { title = "The Gearmaster", description = "Gearmaster Mechazod is insane! He says that he offers us immortality by removing this so-called 'Curse of the Flesh', but what he's really making are robotic slaves!\n\n{name}, we're pretty certain that he's still at the pumping station out in the middle of the pools to the east.\n\nThe last we saw of him, he was in the command hut up top. Go up there and research his stuff.\n\nYou must confront Mechazod if gnomes everywhere,... no, everyone everywhere, are to stay alive!", objectives = "" }
