WordHunterWoW_QuestEN[11864] = { title = "A Mission Statement", description = "", objectives = "" }
WordHunterWoW_QuestEN[11865] = { title = "Unfit for Death", description = "Just south of us the caribou used to roam freely, peacefully. Then Nesingwary showed up and everything changed. Now the caribou are in a perpetual state of frenzy, always in a panic. They are stalked by the hunters and trappers hidden in the field.\n\nNesingwary's executioners are unfit for death. They must feel the torture that they put the caribou through!\n\nTake this pile of fake furs and lay it upon their caribou traps to the south. Watch as the hunters are caught in their own deadly traps!", objectives = "" }
WordHunterWoW_QuestEN[11866] = { title = "Ears of Our Enemies", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.\n", objectives = "" }
WordHunterWoW_QuestEN[11868] = { title = "The Culler Cometh", description = "Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons!\n\nFind this murderer, Karen, and end her worthless existence.\n\nPrepare yourself properly, {name}. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her!", objectives = "" }
WordHunterWoW_QuestEN[11869] = { title = "Happy as a Clam", description = "To the west of us you will find Lake Kum'uya. It is, as far as we know, the only freshwater giant clam habitat in the world.\n\nOf course Nesingwary's lackeys are now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught to those that would think to endanger an entire species.\n\nGo to Lake Kum'uya and locate the loot crazed divers. Slay them until the water runs red! Return to me when a proper example has been made!", objectives = "" }
WordHunterWoW_QuestEN[11870] = { title = "The Abandoned Reach", description = "We have just gotten word from Liandra that mercenaries hired by Nesingwary are moving goods off the beach and onto the main Nesingwary shipping vessel. No doubt they plan on making a fortune from their murderous trade!\n\nShe has asked that we send assistance to the Abandoned Reach, directly south of here on the beachfront of the Borean Tundra.\n\nMake haste, Liandra awaits you there!\n", objectives = "" }
WordHunterWoW_QuestEN[11871] = { title = "Not On Our Watch", description = "Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks of animal parts. It would seem that Nesingwary is in cahoots with the Northsea Freebooters. Those dirty pirates are transporting the goods that Nesingwary's murderous lackeys gather offshore. No doubt they will end up in the homes and on the backs of wealthy, unscrupulous individuals across Azeroth.\n\nThis won't happen. Not on our watch. Bring me all shipments that you find upon this beach. They'll never have them!", objectives = "" }
WordHunterWoW_QuestEN[11872] = { title = "The Nefarious Clam Master...", description = "It's despicable, really, to anoint one's self as the \"Clam Master,\" as if they hold mastery over the creatures of the sea. None may make such claims!\n\nThis \"Clam Master\" must be found and slain. He was last seen at the wreckage just off the coast of the Abandoned Reach. Find him and kill him.\n\nOnce this is done, return to Hierophant Cenius at the D.E.H.T.A. Encampment, north of here, and let her know that the mission was a success.", objectives = "" }
WordHunterWoW_QuestEN[11873] = { title = "Give Fizzcrank the News", description = "Would you be willing to head back to the airstrip and let Fizzcrank know that I'll be along shortly to give my formal report? I've got to deal with the wreckage of my flying machine, and then I'll be on my way.\n\nI'll be certain that Fizzcrank knows that he has you to thank for my survival and the recovery effort.\n\nI only wonder what the old man would've done himself if he'd been flying with us. I miss those days.", objectives = "" }
WordHunterWoW_QuestEN[11875] = { title = "Gaining the Advantage", description = "The troops of the Shattered Sun Offensive will need every advantage they can get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils which will strengthen the blades and armor of our troops.\n\nThe key ingredient, nether residue, pervades Outland  -- if you know where to look. Any master herbalist, skinner, or miner who knows the signs can gather it while plying his trade. Those herbs, ores, and beasts native to Outland may all bear the residue.", objectives = "" }
WordHunterWoW_QuestEN[11876] = { title = "Help Those That Cannot Help Themselves", description = "They're majestic beasts, aren't they?\n\n<Lathorius points towards the mammoths of the northern tundra.>\n\nWith each passing day their numbers diminish. Demons that call themselves hunters slay the beasts for sport and riches.\n\n<Lathorius' face contorts with anger.>\n\nIt's the whimpers that drive me to madness, {name}. You can hear them, carried by the wind. The mammoth calves, trapped in the hunters' vile traps, call out to us.\n\nTake this hammer and smash those traps. Free the calves!", objectives = "" }
WordHunterWoW_QuestEN[11877] = { title = "Sunfury Attack Plans", description = "As we press the offensive on Quel'Danas, we've discovered that Kael'thas' minions are planning a counterattack. By ordering the Sunfury blood elves, based in Netherstorm, to attack our operations in Outland, he hopes to draw troops and attention away from the Sunwell.\n\nWe must not allow this to happen, {name}. Each and every blade is needed on the front lines.\n\nGo to Netherstorm and capture their attack plans. Any of the Sunfury blood elves up there could be in possession of the plans. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[11878] = { title = "Khu'nok Will Know", description = "Although you have acted valiantly in freeing the trapped calves, many of them will still die. You see, without a caretaker, these calves must fend for themselves in the wild.\n\nBut there is a way! Hope yet remains!\n\nNorth of here in the mammoth fields, bordering the Scalding Pools, you will find Khu'nok the Behemoth: a mammoth as wise as he is ancient. Take this mammoth orphan and present it to Khu'nok. He will know what to do.", objectives = "" }
WordHunterWoW_QuestEN[11879] = { title = "Kaw the Mammoth Destroyer", description = "You cannot defeat the being responsible for the slaughter of my kind by yourself. The mammoths of the tundra will help you!\n\nVenture forth to the plains and find a mammoth bull. He will allow you to mount him and control his movements and actions. Ride upon his back and find Kaw, north of here at Kaw's Roost. Together, you will be the instrument of Kaw's demise.\n\nDestroy Kaw's armies and take from Kaw his coveted war halberd. Return to Lathorius at the D.E.H.T.A. Encampment should you succeed.", objectives = "" }
WordHunterWoW_QuestEN[11880] = { title = "The Multiphase Survey", description = "I'm sure that 'gnomish inventor' is a crackpot. He was babbling about some dark distortions that have begun to appear in the Spirit Fields around Oshu'gun in Nagrand.\n\nAccording to him, these, uh, multiphase... um, spectro-goggles will allow the wearer to see the distortions and take readings from them. He insisted that recording this data was fundamental to our campaign at the Sunwell. I think he's nuts, but I'm under orders to investigate anything that might help. Would you mind taking some readings?", objectives = "" }
WordHunterWoW_QuestEN[11881] = { title = "Load'er Up!", description = "Have you seen the flying machines buzzing around? That's gnomish innovation at its finest.\n\nI've long waited to get my hands on some of their technology and a perfect opportunity has presented itself. One of their recon wings crashed in the Scalding Pools, in the southwest part of the Geyser Fields.\n\nBlow this whistle near one of the crashed machines and my trusty mule, Jenny will answer. She'll follow you and carry the salvage, but you must keep her safe. She'll begin to drop the cargo if attacked.", objectives = "" }
WordHunterWoW_QuestEN[11882] = { title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Fire Eater at any Alliance capital. They should be able to help you.", objectives = "" }
WordHunterWoW_QuestEN[11883] = { title = "Fire Dancing?", description = "You wish the learn the art of fire dancing?\n\nWell, then. Speak to a Master Fire Dancer at any Horde capital. They should be able to help you.\n", objectives = "" }
WordHunterWoW_QuestEN[11884] = { title = "Nedar, Lord of Rhinos...", description = "West of here, on the high bluffs above Lake Kum'uya, roams a despicable being known as Nedar. The self proclaimed \"Lord of Rhinos\" hunts the wastes for the injured or young - rhinos unable to defend themselves against his cowardly attacks. To add insult to injury, Nedar has raised a rhino of his own to become his mount and bodyguard.\n\nIt is a rare thing that D.E.H.T.A. would ever call for the death of an animal, but Nedar's tainted rhino must be disposed of... Kill them both and return to me. ", objectives = "" }
WordHunterWoW_QuestEN[11885] = { title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  These are powerful beings you will be facing; you would do well to bring friends.", objectives = "" }
WordHunterWoW_QuestEN[11886] = { title = "Unusual Activity", description = "While celebration has its place, {class}, some of us must look to graver matters.\n\nWhen the festival began, we received reports from Zoram Strand about a sharp increase in Twilight Cult activity. The origins of this holiday are steeped in the very powers those madmen revere; this cannot be coincidence. Go to the camp just south of the Blackfathom Deeps entrance, in the ruins, and see if the cultists will part with information - forcefully if need be. Use this beacon to summon a guide when you find it.", objectives = "" }
WordHunterWoW_QuestEN[11887] = { title = "Emergency Supplies", description = "Rifling through the dead gnome's possessions, you come across a small packet filled with rations, tools, and a handy roll of gnomish duct tape. The contents of these kits might prove helpful to Fezzix Geartwist when it comes time for him to reassemble the wreckage of the gnomish flying machines.\n\nBringing a few of these kits to Fezzix might just be worth a nice bonus.", objectives = "" }
WordHunterWoW_QuestEN[11888] = { title = "Ride to Taunka'le Village", description = "{race}, the chieftain is making me wait... time that Taunka'le does not have!\n\nThere has been talk of your prowess. Rather than wait for Garrosh to send help, I ask you to go and help my people.\n\nTaunka'le village lies far to the northeast. Follow the road east out of the hold, turning north at the intersection. Not long after, you will come to another intersection. Follow the path east, passing south and then east of the great pools along the flood plains.\n\nSpeak with Sage Earth and Sky when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[11889] = { title = "Death From Above", description = "We're doing a good job of holding the front lines against these bugs.  Some of these cheeky fiends, however, can fly over the aforementioned front lines and are really beating down on our inner defenses.\n\nI've requisitioned reinforced fishing nets from our civilian ships.  If you've got a good enough throwing arm, they'll help you knock the enemy out of the sky.  Thin their numbers so that our defenses can hold the keep.", objectives = "" }
WordHunterWoW_QuestEN[11890] = { title = "What Are They Up To?", description = "The gnomes have run into some trouble in the pools to the west. It serves them right as they have been fouling up the land with their so-called inventions.\n\nI want you to go out to their pumping station and observe what has befallen them. Return to me after.", objectives = "" }
WordHunterWoW_QuestEN[11891] = { title = "An Innocent Disguise", description = "According to this, it seems there is another encampment of the cultists to the northwest of the large gathering on the Zoram Strand, and they are speaking with... guests?\n\nMuch could be learned from listening to these proceedings, {race}. Take this orb; it will allow you to appear as one of the native crawlers on the beach. Spy on the conversation with these \"guests\" of the cultists at the northwestern camp and report back to me when you are successful.", objectives = "" }
WordHunterWoW_QuestEN[11892] = { title = "The Assassination of Harold Lane", description = "You have done much for the animals of the Borean Tundra, {name}. Nesingwary's lackeys have been beaten back and taught a lesson that they will not soon forget.\n\nHarold Lane, the primary agent responsible for the mass slaughters in Nagrand, has been identified as the man in charge of Nesingwary operations in the tundra. He is stationed at Lake Kum'uya, west of here.\n\n<Lathorius hands you an intricately carved oak horn.>\n\nFind Lane and kill him. Use this horn should you require our aid.\n", objectives = "" }
WordHunterWoW_QuestEN[11893] = { title = "The Power of the Elements", description = "I kept trying to tell that silly goblin his machines are unreliable.\n\nBut the power of the elements; that is deep and abiding. When my apprenticeship is over, I will wield their full power. What I know now should be sufficient to help out our friend Fezzix, though.\n\nTake this windsoul totem and plant it near any of the steam ragers to the west of the village. The totem will gather up the energies of slain elementals. Return the fully charged totem to me and I'll do the rest.", objectives = "" }
WordHunterWoW_QuestEN[11894] = { title = "Patching Up", description = "Remember all that gnomish duct tape you brought me?\n\nWell, I've found a use for it. The body of this flying machine is so banged up in places, that I'm going to need to reinforce it if I ever hope to fly.\n\nDorain over there has been telling me that the taunka use steam cured caribou leather for making watertight containers. Marsh caribou live all around the village and in the Flood Plains to the south. Get the best hides you can find and cure them over the steam vents in the Geyser Fields.", objectives = "" }
WordHunterWoW_QuestEN[11895] = { title = "Master the Storm", description = "From what you describe, the creatures of metal should be easy to deal with. But first, you must master the storm.\n\nBehind me in the lodge is a totem. When you are ready, focus your will upon it and the storm will come. You must defeat the storm and in so doing take its essence into yourself.\n\nIf others are there, it is enough that you all work together to defeat it. Return to me after, {class}.", objectives = "" }
WordHunterWoW_QuestEN[11896] = { title = "Weakness to Lightning", description = "You now have the power of the storm within you. I will give you the means to focus that power and weaken the robots in the pools.\n\nTake this lightning rod. Use it against the robotic creations of the mechagnomes you find within the greater pools area to the west. Do not worry about using it against the mechagnomes themselves; Greatmother Taiga has other plans for them.\n\nOnce the robots are weakened by the power of the storm, dismantle them utterly!", objectives = "" }
WordHunterWoW_QuestEN[11897] = { title = "Plug the Sinkholes", description = "The Scourge are showing no sign of letting up, {name}.  It's those blasted sinkholes; they connect to tunnels all the way to Icecrown for all we know.  Giant undead worms burrow under the ground to create them.\n\nIf there's something years of mining has taught me it's that without support beams, tunnels will cave in easily after an explosion.\n\nTake these explosives and place them at the entrance to the sinkholes up on the ridge beyond the beach to the west.  Come back after you've collapsed them.", objectives = "" }
WordHunterWoW_QuestEN[11898] = { title = "Breaking Through", description = "On the lowest tier of the Temple City, there is a gray altar bathed in light. Step into it to gain entry to the dread necropolis Naxxanar.\n\nBe cautious, {name}. Prince Valanar will certainly be defended by his personal retainers, who will give their lives to keep you from ascending to the top level of the necropolis.\n\nYou must find your way through the necropolis to the prince's seat. If you fail to defeat him, {name}, I fear my people will never know the safety Icemist offers.", objectives = "" }
WordHunterWoW_QuestEN[11899] = { title = "Souls of the Decursed", description = "The mechagnomes in the pools to the west are a great mystery to us. They appeared not long after the gnomes disappeared from their pumping station and its environs.\n\nThey are an unnatural danger and must be dealt with.\n\nTake this soulcatcher and use it on the remains of the mechagnomes to capture their souls. When you return, we will set them free so that we might find out what happened.", objectives = "" }
WordHunterWoW_QuestEN[11900] = { title = "Reading the Meters", description = "I had hoped that the Nexus' impact was limited to this region. Recently though, reports have flooded in from all over Azeroth suggesting that geologic instability is growing exponentially!\n\nI need the Nexus monitored regularly as I work to develop a solution.\n\nI've placed sensitive instruments around Coldarra, disguised as Malygos' scrying orbs. One lies in the trench near the Nexus, and three are hidden in the structures around the valley's perimeter. Visit each and return to me with their readings.", objectives = "" }
WordHunterWoW_QuestEN[11901] = { title = "Military?  What Military?", description = "There's Scourge everywhere, {class}.  We've organized the farmers and miners into a militia, but this just won't cut it.\n\nThe one detachment of troops that Valiance Keep sent is defending the mine.  We haven't heard from them in days!\n\nIf you really wish to help us, why don't you go to the mine and see what's going on?  Maybe we can get them to send us some reinforcements.", objectives = "" }
WordHunterWoW_QuestEN[11902] = { title = "Pernicious Evidence", description = "The sacks of grain emanate the foul stench you've come to associate with the Plague.  This probably explains what happened to the footmen defending the mine.\n\nYou'd best bring word back to Gerald Green.", objectives = "" }
WordHunterWoW_QuestEN[11903] = { title = "It's Time for Action", description = "Well, {name}.  With the last of our military in Farshire dead or worse, we can do but one thing: fight these Scourge ourselves.\n\nWe have deployed militia in what remains of Farshire.  Without your help, they've but little hope of winning.  Go and lend them a hand.  Me and the lads will watch this path.  We can't let the Scourge break through!", objectives = "" }
WordHunterWoW_QuestEN[11904] = { title = "Fruits of Our Labor", description = "The Scourge just keeps coming... but we can't give up!  Listen, {name}.  Inside that mine there's a cart with the last of the ore the Alliance is going to see on this side of the continent for a long time.\n\nThe problem is the cart release is locked.  When the military went in there, Captain Jacobs commandeered all the important equipment, including the cart release key.\n\nThe plague that affected the soldiers in the mine must also have affected Jacobs.  Get the key from him and salvage the ore.", objectives = "" }
WordHunterWoW_QuestEN[11905] = { title = "Postponing the Inevitable", description = "Azeroth's ley lines are being redirected to the Nexus.\n\nThe influx of arcane energies is tearing a rift between dimensions.\n\nI cannot stop it, but I've discovered a way to slow it down.\n\nTake this and activate it near the forming rift.", objectives = "" }
WordHunterWoW_QuestEN[11906] = { title = "Cleaning Up the Pools", description = "<A single tear rolls down the face of Iron Eyes.>\n\nI have heard that you are heading back into the pools to the west. I have something for you to do while you are out there, {race}.\n\nThe gnomes, who care nothing for the land, have polluted it with their machinery. I want you to pick up any spare parts that you come across.\n\nReturn them to me here. I will see to it that they are properly disposed of before we leave this place for good.", objectives = "" }
WordHunterWoW_QuestEN[11907] = { title = "The Sub-Chieftains", description = "It is known that Gearmaster Mechazod has four sub-chieftains that manage the robots in the pools.\n\nWe must put an end to them!\n\nOur longrunners and snow trackers say that if you were to turn the valves at the west point, north point, mid point and south point stations, each of his sub-chieftains would come quickly to prevent you from fouling their operations.\n\nThe stations are centered on the spinning lights in the pools surrounding the pumping station.\n\nHurry, {name}!", objectives = "" }
WordHunterWoW_QuestEN[11908] = { title = "Reference Material", description = "I was in charge of the harvest golems - an important job until the Scourge destroyed most of our farmlands.  I've an idea that would make the golems useful again, however.\n\nI think I can rewire the harvest collectors so they'll give us a hand fighting the Scourge.\n\nI'm not an expert at this just yet, so I'm going to need my manual.  The problem is, I left it at the workshop... which happens to be that burning building next to the mine.  Think you could go salvage it?", objectives = "" }
WordHunterWoW_QuestEN[11909] = { title = "Defeat the Gearmaster", description = "Clearly this Gearmaster Mechazod creature is not in his right mind. If his offer of a cure and immortality means all of us becoming robotic slaves then he must be stopped!\n\nThe winds that guide me whisper that he's atop the pumping station out in the middle of the pools to the west.\n\nMost likely, he'll be found in the command hut on top of the structure. Go inside and research his works.\n\n{name}, you must confront Mechazod if we are to survive!", objectives = "" }
WordHunterWoW_QuestEN[11910] = { title = "Secrets of the Ancients", description = "It's become clear that the instability in the region has had an effect on its indigenous creatures.\n\nI've taken a particular interest in the Glacial Ancients and their recent adaptations. I suspect that their transformation into these 'Magic-bound' Ancients may hold clues to our predicament here.\n\nFor my studies, I'll need samples from both. Do hurry....", objectives = "" }
WordHunterWoW_QuestEN[11911] = { title = "Quickening", description = "I've learned more in my short time here than in decades of studies.\n\nThe ancients here are being exposed to incredible levels of arcane energy. It's literally transforming them into something...\n\nI'm confident that there's a final stage in their metamorphosis. Find me some evidence of their final state.", objectives = "" }
WordHunterWoW_QuestEN[11912] = { title = "Nuts for Berries", description = "Oh! What a relief it is to see a fresh face. I was beginning to feel we had been forsaken.\n\nOur supply lines were cut off days ago, and things have been looking - well, bleak. To be honest, this was a suicide mission to begin with if you ask me.\n\nMaybe I'm simply not cut out for all of this violence - to say nothing of the bitter cold! I'd much rather be back in Dalaran studying ancient texts.\n\nTo the point, our food supply is nearly spent. Please, gather what you can and bring it to me.", objectives = "" }
WordHunterWoW_QuestEN[11913] = { title = "Take No Chances", description = "I heard what you told Gerald and I don't like it one bit.  If cultists managed to poison the grain in the mines with their foul plague, they could've easily done the same with the grain outside.\n\nWe don't have time to sort the good grain from the bad.  We must act quickly and burn it all.\n\nTake this torch and set fire to any sacks of grain you find out here.  It would be a tragedy if we survived this attack only to succumb to the plague afterwards.", objectives = "" }
WordHunterWoW_QuestEN[11914] = { title = "Keep the Secret Safe", description = "Our existence here depends entirely upon staying hidden. Should the shield fail, even for a moment, Malygos' minions would have us.\n\nOne of my responsibilities is to rejuvenate the warmages' mana levels so their focus doesn't falter. With our supply lines lost, I've been forced to improvise.\n\nI could use your help, {name}.\n\nVery near the Nexus, Arcane Serpents feast on the abundant magical energies. Once defeated, they will yield a mana essence that I can make use of.", objectives = "" }
WordHunterWoW_QuestEN[11915] = { title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Flame Eater at any Horde capital. They should be able to help you.", objectives = "" }
WordHunterWoW_QuestEN[11916] = { title = "Hellscream's Champion", description = "You have faced all challenges that have been set before you and squashed them beneath your boot heel. It is because of you, {name}, that the Horde is now firmly entrenched in Northrend.\n\nBut our work has only just begun. We must march to Icecrown and we must tear down its walls!\n\nYour next assignment begins to the east, at Taunka'le Village. Our taunka allies are in dire straits and require aid. Secure transport from the stable master, Durkot Wolfbrother, and seek out Chieftain Wintergale at Taunka'le.", objectives = "" }
WordHunterWoW_QuestEN[11917] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nReturn to the camp on the Zoram Strand with the large ice stones. They use them to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "" }
WordHunterWoW_QuestEN[11918] = { title = "Basic Training", description = "This is war, mortal, and we are the tip of the spear.\n\nYour little spats over land or currency pale in comparison to this conflict. We face the aspect Malygos and his entire blue dragonflight. All you need to know is that if he is victorious, this world shall be no more.\n\nWe are but few here, and we fly against many. Our deaths are all but a certainty, and our ultimate success lies in merely delaying our enemy.\n\nGo now. Busy yourself while I decide what to do with you.", objectives = "" }
WordHunterWoW_QuestEN[11919] = { title = "Drake Hunt", description = "The blues have begun to cover their drakes in mysterious runes. I must discover their significance.\n\n<Raelorasz pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.\n\nTheir hatchlings feed around the northwest edge of the valley.", objectives = "" }
WordHunterWoW_QuestEN[11920] = { title = "Cultists Among Us", description = "This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.\n\nPerhaps he is to be found above deck.", objectives = "" }
WordHunterWoW_QuestEN[11921] = { title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[11922] = { title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lesson.", objectives = "" }
WordHunterWoW_QuestEN[11923] = { title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four then come back to me.\n\nCareful! They're dangerous if they hit the ground! Good luck!", objectives = "" }
WordHunterWoW_QuestEN[11924] = { title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", objectives = "" }
WordHunterWoW_QuestEN[11925] = { title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", objectives = "" }
WordHunterWoW_QuestEN[11926] = { title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[11927] = { title = "Word on the Street", description = "Hey, {name}.  There's a girl in the inn that's asking about you.  Her name's Leryssa.\n\nI don't think she knows you, but she said she needed your help.  She sounded really desperate.", objectives = "" }
WordHunterWoW_QuestEN[11928] = { title = "Farshire", description = "My lads should be able to take it from here, {name}.  Valiance Keep is built to take a beating far worse than this.  I worry about our farmlands and mine in Farshire, however.\n\nWe sent a full detachment to protect our mining operations right before the invasion - they should be able to defend the civilians.\n\nGerald Green's in charge of the villagers there. There's a passage out of the northern wall out of Valiance Keep; it'll take you straight to him.  See what you can do to help them.", objectives = "" }
WordHunterWoW_QuestEN[11929] = { title = "The Fall of Taunka'le Village", description = "We are lost, {name}. This place has been our home for many generations, but it is no longer safe. There remains only death... Death and a memory of what used to be.\n\nI have called for the evacuation of Taunka'le. All remaining taunka must leave at once and make their way to our capital city, Icemist, located in the Dragonblight.\n\n<Wintergale points east.>\n\nYou must help get my people to safety, {name}. Mother Tauranook awaits you at the village gates. Hurry! The Scourge closes in from all sides!", objectives = "" }
WordHunterWoW_QuestEN[11930] = { title = "Across Transborea", description = "The path across Transborea, to the east, is the only way to reach the Dragonblight. Many perils await you as you make your journey across the tundra. Beware the Scourge and its influence upon the beasts of the land. Rumors have started to spread about our very own taunka brothers and sisters rising from the dead and attacking caravans on their way to the Dragonblight! Defend your caravan and get the evacuees to safety!\n\nWartook Iceborn waits for you across the bridge leading into the Dragonblight.", objectives = "" }
WordHunterWoW_QuestEN[11931] = { title = "Cracking the Code", description = "I sense a distinct peculiarity in the drakes here but the meaning of the runes that cover their bodies still eludes me.\n\nWithout a codex, it will take more time than we can afford for me to interpret them.\n\nNot far from here is a Kirin Tor traitor, Caleras, who is likely to have a copy of the tome I require. His underlings hold the runes I will need for my translation.\n\nHurry, mortal. Malygos gains strength with every passing moment.", objectives = "" }
WordHunterWoW_QuestEN[11932] = { title = "Cowards and Fools", description = "Listen, {name}.  No offense, but the operation they put Thassarian in charge of was pure suicide.\n\nA handful of our men were to launch an attack on the biggest Scourge presence in the area.  Call me crazy, but storming a Scourge ziggurat outside a plagued Nerubian city with a dozen men ain't my idea of fun.\n\nIf you're still interested in finding Thassarian, we were supposed to arrange for passage east with a tuskarr by the name of Ataika in Kaskala to the northeast.  Good luck with your fool's errand.", objectives = "" }
WordHunterWoW_QuestEN[11933] = { title = "Stealing the Exodar's Flame", description = "This flame, stolen from the heart of the Exodar itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "" }
WordHunterWoW_QuestEN[11935] = { title = "Stealing Silvermoon's Flame", description = "This flame, stolen from Silvermoon, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "" }
WordHunterWoW_QuestEN[11936] = { title = "Hatching a Plan", description = "Our goals here are simple. We are to remain hidden from Malygos, observe his brood, and thwart his efforts wherever possible. To that end, I have a task for you.\n\nThe blues are laying their eggs at the base of the Nexus. Exposure to so much arcane energy will surely make them hatch sooner, and there's no telling what effect it will have on their spawn.\n\nI don't intend to find out. Slay the local wyrmkin and use their frozen axes to break the eggs.", objectives = "" }
WordHunterWoW_QuestEN[11938] = { title = "Buying Some Time", description = "Now that we have this phylactery, I shouldn't have any problems getting the information I need.  It won't take long for the Scourge in the Temple City to notice something's up, however.\n\nI won't be able to fend off a full scale attack here.  Or maybe I would... but I'd rather not find out.\n\nI want you to head down there and inflict some casualties.  Hopefully they'll be distracted long enough for these two to spill their guts... figuratively, of course.  Take Lurid with you, he might be of aid.", objectives = "" }
WordHunterWoW_QuestEN[11939] = { title = "?????", description = "[PH]Quest to close this questline - summon and kill a mature drake (Elite?) - Fight a drake in the dungeon?", objectives = "" }
WordHunterWoW_QuestEN[11940] = { title = "Drake Hunt", description = "I need more drake hatchlings to continue researching the runes covering their bodies.\n\nThey can be found around the northwest edge of the valley....\n\n<Raelorasz pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.", objectives = "" }
WordHunterWoW_QuestEN[11941] = { title = "Puzzling...", description = "Something about this scrap of metal prevents you from casting it aside.\n\nPerhaps Raelorasz might be able to shed some light on its purpose.", objectives = "" }
WordHunterWoW_QuestEN[11942] = { title = "Words of Power", description = "The lich has spoken, {name}.  The high priests of En'kilah hold the secret to entering Naxxanar.\n\nGo to the Spire of Blood, the Spire of Pain and the Spire of Decay and slay each of the priests.\n\nReturn once you've obtained the three scrolls.", objectives = "" }
WordHunterWoW_QuestEN[11943] = { title = "The Cell", description = "You've discovered a fragment of a special prison, {name}.\n\nMalygos' minions use similar prisons to hold their captured mages and other arcane entities, but this prison was constructed to hold something... stronger.\n\nIn hopes that the enemy of our enemy will prove to be a friend, you must search for the prison's remaining fragments.\n\nThey are likely to be in the possession of Malygos' most trusted underlings.", objectives = "" }
WordHunterWoW_QuestEN[11944] = { title = "Surrounded!", description = "Our situation is nearly hopeless.  We were ordered to take the Wailing Ziggurat with a handful of men.\n\nWe'll be lucky if we can hold this position against the Scourge.  We're outnumbered, injured and have no escape route.\n\nIf you can take some of the pressure off of us, we might be able to solidify our position.  Kill some of the undead circling the structure - we'll hold off their advance.", objectives = "" }
WordHunterWoW_QuestEN[11945] = { title = "Preparing for the Worst", description = "Dark times are upon us.  Karkut's spirit walks the earth and gathers the spirits of dead tuskarr.\n\nThe sons of the mist have taken many of our brethren.  Soon dear Kaskala will be reduced to ashes.\n\nThere is hope yet.  Not for us perhaps, but we've sent our families to Unu'pe.  We fight here so there may be a future for them.\n\nThey will need supplies or they will starve.  There's not enough food in Unu'pe.  Salvage any supplies before it's too late for our families.", objectives = "" }
WordHunterWoW_QuestEN[11946] = { title = "Keristrasza", description = "I am... free?\n\nI was destined to spend an eternity roaming an empty abyss, and now am saved? You cannot fathom my gratitude, mortal.\n\nWhen I refused to bend to his will Malygos bound me to that prison, then shattered it and scattered the pieces. Should I live one hundred of your lifetimes, I shall not forget this kindness.\n\nPerhaps, in time, I will find ways to repay you. For now, though, we must focus our attention on Malygos. I am weak, and there is much to be done.\n\nI need your help, {name}.", objectives = "" }
WordHunterWoW_QuestEN[11947] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nThere is a camp located in the shadow of Ethel Rethor within northwestern Desolace. There, they use ice stones to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "" }
WordHunterWoW_QuestEN[11948] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nNeptulon has long had a base of operations on an island in western Stranglethorn. There, the Twilight Cult has set up ice stones to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "" }
WordHunterWoW_QuestEN[11949] = { title = "Not Without a Fight!", description = "Kaskala is a sacred place for us, {race}.  Our ancestors were guided here by the spirit of Tayutka herself.\n\nNow these foul creatures attack us from the mists without any provocation.\n\nWe will show them that our spears are not merely for whaling.  Fight alongside us, friend.  Perhaps my people might repay you some time in the future.", objectives = "" }
WordHunterWoW_QuestEN[11950] = { title = "Muahit's Wisdom", description = "Listen, {name}.  Warriors like me are replaceable.  If I fall, my brothers and cousins will pick up my spear and fight.\n\nMy people cannot survive without wise elders.  Stubborn Muahit, our most venerable shaman, refuses to leave the altar to Tayutka in the central island.  We would suffer a significant loss if he was slain by these monsters.\n\nYou are an outsider, maybe he'll listen to you.  Show him reason... ask him to flee to the safety of Unu'pe before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[11951] = { title = "Bait and Switch", description = "During my captivity I was able to learn much about Malygos. Fate now allows us to use this knowledge against him.\n\nThere is a great blue dragon, Saragosa, who circles high above the Nexus. She serves both as the aspect's guardian and as his consort. If any serious threats arise, she alerts her master of the danger.\n\nI suffered greatly at the hand of Saragosa during my captivity, and now her time to die has come. First, however, we must fashion the perfect bait....", objectives = "" }
WordHunterWoW_QuestEN[11952] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nFirewatch Ridge in Searing Gorge is an established bastion of Twilight Cult activity. Recently, they have been using ice stones in the cave to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "" }
WordHunterWoW_QuestEN[11953] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nSilithus is the Azerothian base of the Twilight Cult. In the north, they have been using new ice stones to communicate with the Tidehunter's realm. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "" }
WordHunterWoW_QuestEN[11954] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nIn order to ensure Ahune's success, the cult has established a base near the Dark Portal itself in Draenor. They use ice stones to coordinate the frost lord's arrival. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's templar protectors and destroy it. Perhaps this forestalling action will be enough...", objectives = "" }
WordHunterWoW_QuestEN[11955] = { title = "Ahune, the Frost Lord", description = "I believe you are strong enough for the ultimate task set before us.\n\nWe cannot allow the plot between the Twilight Cult and the naga heretics of Neptulon to come to fruition. For the sake of Azeroth and all life upon it, we must act. Our path is clear. You must journey to the Slave Pens deep within Coilfang Reservoir and meet with our shaman there. Go, and quickly!", objectives = "" }
WordHunterWoW_QuestEN[11956] = { title = "Finding the Phylactery", description = "No time for small talk, {name}.  I was sent on what was to be a suicide mission to take this ziggurat.  I've accomplished my duty as a soldier, now is the time to get some answers.\n\nThis lich has knowledge I seek, yet I cannot inflict pain to his physical body to obtain that knowledge.\n\nThe lich stored his soul in a phylactery, and while it remains hidden, I won't be able to pry the information from him.\n\nReturn to the camp and take my horse, Dusk, she will lead you to the phylactery.  Bring it to me.", objectives = "" }
WordHunterWoW_QuestEN[11957] = { title = "Saragosa's End", description = "Using the mana crystals you provided, I have created this Power Focus.\n\nSaragosa is a glutton. She will be unable to resist its lure. Inside it lie magics that will greatly diminish her power. Let us hope she does not see through my ruse....\n\nPrepare yourself, {name}, and speak to me again when you are ready to face Saragosa.\n", objectives = "" }
WordHunterWoW_QuestEN[11958] = { title = "Let Nothing Go To Waste", description = "The wolvar have always been our natural enemies. But the incursion of your peoples into the Great Dragonblight has forced them into a small space upon the glade to the north.\n\nCombined with the land's upheaval this morning, they have become even more aggressive than ever before. They have made several raids upon our goods... things that we'll need if we are to survive the trek from our home here.\n\nAs a sign of good faith and friendship, retrieve our goods from the Snowfall Glade wolvar.", objectives = "" }
WordHunterWoW_QuestEN[11959] = { title = "Slay Loguhn", description = "Already it goes from bad to worse. There is only one course to take... regrettably, Loguhn must die!\n\nHe's the alpha male of the Snowfall Glade tribe and one mean wolvar. But it's the only way to get a short break from their attacks and stealing forays.\n\nYou will find the \"Render of Flesh\" in front of his hovel upon the northern rise of the glade. It's larger than the others and hard to miss. Kill him and smear his blood upon yourself, both to show your dominance and respect.", objectives = "" }
WordHunterWoW_QuestEN[11960] = { title = "Planning for the Future", description = "We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain.\n\nThe Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance.\n\nIf Elder Ko'nani hasn't asked you already, he will ask you to deal with them.  While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[11961] = { title = "Spirits Watch Over Us", description = "Powerful spirits watch over my tribe -- Kaskala will not be lost.\n\nIssliruk will give us courage, Tayutka will make sure our survivors always have food and shelter and Karkut will watch over the fallen so they do not lose their way.\n\nIssliruk's guidance is the one we need the most right now.  I asked my nephew, Iruk, to bring me Issliruk's totem, but the Kvaldir's spears struck him down and his body fell into the waters to the north.  Bring me the totem, {name}.  Don't let my nephew's death be in vain.", objectives = "" }
WordHunterWoW_QuestEN[11962] = { title = "One Last Delivery", description = "That's it then.  With the last of the ore you salvaged we now have enough to send to Valiance Keep.\n\nIf Farshire is wiped off the face of Azeroth, then at least let us be remembered as the first ones to defend our land and the last ones to give up.\n\nTake this ore to Hilda Stoneforge - she is a good friend of mine.  Tell her to make some good weapons with this ore.  We'll need plenty of them in the days to come.", objectives = "" }
WordHunterWoW_QuestEN[11963] = { title = "Weapons for Farshire", description = "Farshire is overrun and all that Gerald can think of is to get me my ore shipment?  I swear that man has as much heart as any of our soldiers on the frontlines.\n\nWe cannot let the civilians lose their lands if they're willing to fight for them.  We might not have the troops to spare, but we can send them weapons.\n\nThese were earmarked for new recruits, but I'll be able to cover those with the ore you've brought me.  Send word to Gerald that weapons are on the way.", objectives = "" }
WordHunterWoW_QuestEN[11964] = { title = "Incense for the Summer Scorchlings", description = "Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any summer scorchling.  Appease the little fire spirit, and it may reward you.", objectives = "" }
WordHunterWoW_QuestEN[11965] = { title = "Call to Arms!", description = "Farshire has a fighting chance now, {name}.  That's all we could've asked for and you've made it possible.\n\nAll we need now is a rallying point.  I'll have my men deliver the weapons to our town hall.  Go and ring the town hall bell so any survivors know to rally there.\n\nIt's time to show the Scourge what we're made of.", objectives = "" }
WordHunterWoW_QuestEN[11966] = { title = "Incense for the Festival Scorchlings", description = "Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any festival scorchling.  Appease the little fire spirit, and it may reward you.", objectives = "" }
WordHunterWoW_QuestEN[11967] = { title = "Mustering the Reds", description = "Malygos is certainly aware that something is amiss.\n\nI know him. His focus is fragmented. I am confident that I can lure him from the safety of his realm when he learns what has become of his precious Saragosa.\n\nTake me to Raelorasz at once, {name}. He must rouse every dragon he commands to face Malygos.", objectives = "" }
WordHunterWoW_QuestEN[11968] = { title = "The Tides Turn", description = "The spirits have heard our cry for help, {name}.  It's a sign that Kaskala might yet be saved.\n\nTake advantage of the confusion the weather has created and slay the Kvaldir leader.  Your actions will sway the battle in our favor, I am sure of it.", objectives = "" }
WordHunterWoW_QuestEN[11969] = { title = "Springing the Trap", description = "We owe this opportunity in great part to your efforts, {name}.\n\nIt is only fitting that you initiate the attack on Malygos.\n\nTake this spark and use it to light the signal fire northwest of the Nexus. Keristrasza will direct you from there.", objectives = "" }
WordHunterWoW_QuestEN[11970] = { title = "The Master of Summer Lore", description = "There should be no mistake, the festival is a time for fun and laughter! However it is important that you understand the origins of this holiday. Education should be sought out and savored! .\n\nThe Festival Loremaster in the Alliance capitals can guide your way. Go now and learn!", objectives = "" }
WordHunterWoW_QuestEN[11971] = { title = "The Spinner of Summer Tales", description = "Let there be no mistake, the festival is a time for fun and laughter! However it's important that you understand the origins of this holiday. Education should be sought out and savored! .\n\nThe Festival Talespinner in the Horde capitals can guide your way. Go now and learn.", objectives = "" }
WordHunterWoW_QuestEN[11972] = { title = "Shards of Ahune", description = "These shards pulse with foreboding. Do they hold the last essence of the Frost Lord?", objectives = "" }
WordHunterWoW_QuestEN[11973] = { title = "Prisoner of War", description = "Malygos has taken Keristrasza to serve as his consort!\n\nWe cannot allow this to come to pass.\n\nYou must do whatever it takes to spare her such a fate, {race}.", objectives = "" }
WordHunterWoW_QuestEN[11975] = { title = "Now, When I Grow Up...", description = "Maybe I already asked you this, but when you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock or a Blood Knight, like I said before?  Or maybe... A rock star!!  Like Sig Nicious, the blood elf, in the Tauren Chieftains!\n\nI heard that when they aren't touring, they hang out in Silvermoon City!  They just sit on a balcony in the Walk of Elders waiting for people to stop by.\n\nPlease take me there.  Please!", objectives = "" }
WordHunterWoW_QuestEN[11977] = { title = "A Tauren Among Taunka", description = "<Wartook points northeast.>\n\nShe is quite kind, you know. If it were not for your emissary, the surviving refugees may have given up hope. While she may not be taunka by birthright, the tribe has taken to her as a village elder for the time being.\n\nIf you are who I think you are, please go and pay Emissary Brighthoof a visit inside the refugee camp. She has been waiting for you.", objectives = "" }
WordHunterWoW_QuestEN[11978] = { title = "Into the Fold", description = "Before we can officially bring these taunka into the Horde we must recover our armaments from the Anub'ar Nerubians that infest the nearby woods. The armaments were lost when a caravan from Agmar's Hammer was ambushed by the Scourge late last night.\n\nVenture out into the woods to the east of Westwind Refugee Camp and recover those armaments, {race}.", objectives = "" }
WordHunterWoW_QuestEN[11979] = { title = "The Taunka and the Tauren", description = "The Scourge have seized control of the capital city of the taunka, Icemist Village! All living taunka that escaped the massacre are being held in protective custody at the Westwind Refugee Camp on the western border of Dragonblight.\n\nLord Hellscream believes that the taunka must join the Horde if they are to survive and has sent a tauren emissary to Westwind to bolster our relationship with the winter tauren. Travel to Westwind Refugee Camp and seek out Emissary Brighthoof. You will assist her.", objectives = "" }
WordHunterWoW_QuestEN[11980] = { title = "Pride of the Horde", description = "I was one of the guards chosen to escort the caravan carrying the armament shipment to this camp. The attack came fast and without warning. We fought and killed dozens of the beasts, but in the end there were simply too many. Tor'zin and I barely made it out alive...\n\nIf not for our injuries we would be out in the woods hunting down those fiends ourselves. Will you help us regain our lost pride? Search the woods east of here for Anub'ar Nerubians and kill them! For the Horde!", objectives = "" }
WordHunterWoW_QuestEN[11981] = { title = "Find Kurun!", description = "The Earthen warrior's stone surface is covered with cracks and gouges. Although it is incapable of bleeding, you can sense that the warrior is near death.\n\nA low, hoarse voice escapes from the dying warrior's mouth.\n\n\"Find... Kurun... you must find... Kurun.\"\n\nIt looks at you helplessly as you ask for any clues as to who or what Kurun might be.\n\n\"Our... leader... he stands on the... hill overlooking Thor Modan... commands us. Please... tell him... we cannot take... the city... \"", objectives = "" }
WordHunterWoW_QuestEN[11982] = { title = "Raining Down Destruction", description = "Beneath us is iron's ancient bastion, Thor Modan. Thousands of years ago, the stone giants tore the land asunder, collapsing part of the city and exposing much of the rest.\n\nEven now, the iron dwarves attempt to reclaim their old capital, but we will not permit it. My giants fill the trench with boulders and debris, hoping to seal it off and kill the servants of iron as they work. Take up the boulders you see near the trench to the northeast, and help us put an end to their efforts.", objectives = "" }
WordHunterWoW_QuestEN[11983] = { title = "Blood Oath of the Horde", description = "They are ready, {name}. These taunka will all willingly join the Horde and give all that they have to see the Scourge driven from this world.\n\n<Brighthoof hands you a scroll bearing the insignia of the Horde.>\n\nWithin this scroll you will find the blood oath of the Horde. Tradition dictates that our new taunka brothers and sisters utter the sacred words herein.\n\nTake the scroll and swear the taunka into the Horde, commander. Return the scroll to me when you have completed your duty.", objectives = "" }
WordHunterWoW_QuestEN[11984] = { title = "Filling the Cages", description = "'Ol Budd's seen better days.\n\nEver since our stay in Ghostlands he's been useless to us. We've had to find ways to make it on our own, and today that means sellin' trolls to the highest bidder.\n\nFortunately, we've recently found a use for Budd. Something about his condition allows him to mingle with the local trolls, so we taught him a little game that's turned us a tidy profit.\n\nSee for yourself. Talk to Budd, take him southwest to Drak'Zin Ruins and use this cage as soon as he tags a troll.", objectives = "" }
WordHunterWoW_QuestEN[11985] = { title = "Into the Breach", description = "If we can't overcome the defenders inside Thor Modan, the iron dwarves can hold out forever. The Earthen are bravely taking on the constructs built by the sons of iron, but they cannot break into the city.\n\nThe tunnels narrow too quickly for my fellow giants to be of use, so our options are few. Would you be willing to venture into the city and kill the dwarf commanding the resistance?", objectives = "" }
WordHunterWoW_QuestEN[11986] = { title = "The Damaged Journal", description = "This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps.\n\nThe author's handwriting seems vaguely familiar, but you're unable to place it until you discover an entry signed with the name of Brann Bronzebeard.\n\nThe back half of the book, containing the most recent entries, has been torn away. Pages litter the battlefield, and it will be impossible to know what Brann discovered here until the book is whole again.", objectives = "" }
WordHunterWoW_QuestEN[11988] = { title = "The Runic Keystone", description = "Brann's journal mentions that he used a runic keystone to illuminate the important runes on the plate he discovered. Without the keystone, the plate's contents would be little better than gibberish.\n\nAt the end of Brann's last entry, he describes the iron dwarf defenders seizing the keystone from him, shattering it, and dividing it among themselves. Before we can decipher the runed plate, we must hunt down the fragments. Any of the dwarves within Thor Modan or the buildings around it may carry fragments.", objectives = "" }
WordHunterWoW_QuestEN[11989] = { title = "Truce?", description = "Watch yerself, mon.\n\nDrakuru shrunk more {race} heads than I can remember - and even if I could remember, I couldn't count that high. Lucky for you I be stuck in dis cage or I'd be addin' one more to da list.\n\nBut things bein' what they are, mebbe we be puttin' our differences aside fer a time, eh?\n\nDrakuru know things, mon. Things that will aid you in your struggle here.\n\n<Drakuru cuts the palm of his hand on one of his tusks and extends it through the cage.>\n\nSo, what you say, mon... truce?", objectives = "" }
WordHunterWoW_QuestEN[11990] = { title = "Vial of Visions", description = "First things first, mon. There be some preparatory work that need doin'.\n\nNo tellin' how long dey gunna keep me here. Ya be needin' a powerful elixir so we can be keepin' in touch.\n\nLucky for you, I know just the thing! And the ingredients all be close by.\n\nI need a vial from the pretty little troll over there, some waterweed from the lake just north of here, and a few haze leaves found around the camp here.\n\nHurry now, mon, before dey be haulin' me away.", objectives = "" }
WordHunterWoW_QuestEN[11991] = { title = "Subject to Interpretation", description = "A legendary set of artifacts, lost for thousands of years, were created to make Drak'Tharon Keep impervious.\n\nMost think they be myth, but Drakuru knows better, mon!\n\nI nearly discovered where one be, but got captured while interpreting hieroglyphs. Ya gotta summon my soul back dere so I can finish readin' em!\n\nUse my elixir at da brazier on Drak'Zin Ruins, southwest of here. You'll hafta mix in da frozen mojo my bruddas be holdin'. I hate ta see my bruddas fall, but it be for the greater good.\n", objectives = "" }
WordHunterWoW_QuestEN[11993] = { title = "The Runic Prophecies", description = "We've no time to lose! Now that we've reassembled the runic keystone -- well, most of it -- we can decipher the contents of those very same runic plates Brann was working on before he fled.\n\nWe have no way of knowing if he managed to read the contents of all three plates, but we'll have to assume he got enough information to determine his next destination.\n\nStand before each of the plates and use the keystone to determine the contents of each. Brann may be counting on us!", objectives = "" }
WordHunterWoW_QuestEN[11995] = { title = "Your Presence is Required at Stars' Rest", description = "{class}, I know these tuskarr will ask you to do many favors for them, but you must get to Stars' Rest with all due haste!\n\nThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.\n\nStars' Rest is westward past the intersection of the road leading north out of the harbor. There is an archmage there named Modera. She will be expecting you.", objectives = "" }
WordHunterWoW_QuestEN[11996] = { title = "Your Presence is Required at Agmar's Hammer", description = "{class}, I know these tuskarr will ask you to do many favors for them, but you must get to Agmar's Hammer with all due haste!\n\nThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.\n\nThe Hammer is westward past the intersection of the road leading north out of the harbor. Archmage Aethas Sunreaver himself will be expecting you!", objectives = "" }
WordHunterWoW_QuestEN[11997] = { title = "The Frozen Flame", description = "It is time we make our move, {name}. I can conjure a portal that will take you directly inside but it will take some time before I can make another and join you.\n\nThe Lich King will no doubt sense the magic of your arrival so you will need to move fast to locate Felo'melorn and secure it.\n\nIf Lyandra has the blade with her then I fear she may not relinquish it easily. Be prepared for anything, {name}.", objectives = "" }
WordHunterWoW_QuestEN[11998] = { title = "Softening the Blow", description = "Our best bet for moving our forces quickly to Icecrown Glacier lies with the network of tunnels beneath the ancient iron dwarf city of Thor Modan.\n\nBrugar Stoneshear and his Explorers' League boys aren't going to be happy, but orders are orders.\n\nThe news might go over better if you brought him a cask of that moonshine sold by that trapper, Hugh Glass, down at Redwood Trading Post, southeast of here along the tree line.\n\nMan's not right in the head, but you won't find better moonshine out here.", objectives = "" }
WordHunterWoW_QuestEN[11999] = { title = "Rifle the Bodies", description = "The Moonrest Gardens to the southwest were the final resting place of a group of Highborne elves. It was also a ley line nexus.\n\nThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.\n\nI want more information and you are going to get it for me!\n\nAfter the land was destroyed at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters there. Go rifle their corpses for clues.", objectives = "" }
WordHunterWoW_QuestEN[12000] = { title = "Rifle the Bodies", description = "The Moonrest Gardens to the southwest were the final resting place of a noble group of Highborne elves. It was also a powerful ley line nexus.\n\nThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.\n\nI need more information and I hope that you will get it for me.\n\nAfter the upheaval at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters present. Go rifle their corpses for clues.", objectives = "" }
WordHunterWoW_QuestEN[12002] = { title = "Brothers in Battle", description = "I hope Gryan knows I withdrew my men from Thor Modan when the battle began. There's no way we can excavate anything until that place settles down.\n\nYou seem like a brave sort, though, and you have Stoutmantle's trust.\n\nThor Modan is just to the northeast of us and the battle still rages between our Earthen brothers and the creations of those accursed iron dwarves. Help our brethren to even the odds and I'll start figuring out how we're going to accomplish this survey of Thor Modan.", objectives = "" }
WordHunterWoW_QuestEN[12003] = { title = "Uncovering the Tunnels", description = "The first place we'll search for entrances to the Thor Modan tunnel system will be the outlying buildings.\n\nAs I left the site with my men, it looked like the iron dwarf defenders were taking refuge inside the buildings. Be careful as you explore them.\n\nAny tunnel entrances are likely to be toward the back of the buildings. I'm not sure what Stoutmantle thinks we're going to find down there, but I doubt the iron dwarves will make the search easy.", objectives = "" }
WordHunterWoW_QuestEN[12004] = { title = "Prevent the Accord", description = "We need to kill two birds with one stone here, {class}. You're the stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.\n\nI require proof of their demise, if you would be so kind.", objectives = "" }
WordHunterWoW_QuestEN[12005] = { title = "Prevent the Accord", description = "We need to kill two birds with one stone here, {class}. You're the stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.\n\nI require proof of their demise, if you would be so kind.", objectives = "" }
WordHunterWoW_QuestEN[12006] = { title = "Avenge this Atrocity!", description = "These so-called mage hunters came here and destroyed our resting place.\n\nAvenge us, or I will see to it that your base of operations is overrun with the spirits of the dead!", objectives = "" }
WordHunterWoW_QuestEN[12007] = { title = "Sacrifices Must be Made", description = "I've got it, mon!\n\nTo da north, on da Ziggurat at Zeb'Halak be a stone head with ruby eyes. One o' dem be da Eye of the Prophets! Bring it to the brazier there and drink my elixir.\n\nAgain, ya be needing some mojo for my elixir to work - dis time from da warlord, Zim'bo. He be hidin' in one of da huts in Zeb'Halak.\n\nIt be a shame to kill Zim'bo, mon, but he swore da blood oath to defend Drak'Tharon and he done failed. Now at least his mojo be helpin' us to reclaim Drak'Tharon.", objectives = "" }
WordHunterWoW_QuestEN[12008] = { title = "Agmar's Hammer", description = "Directly east of this refugee camp stands Agmar's Hammer - testament to the Hordes' power in the Dragonblight.\n\nWhile I have no doubt that our Horde brothers and sisters are already seeing the result of your efforts to bring the taunka into the Horde, I want you to deliver news of your success to Overlord Agmar in person.\n\nGo now, {name}! Race the winds! East to Agmar's Hammer!\n", objectives = "" }
WordHunterWoW_QuestEN[12009] = { title = "Tua'kea's Crab Traps", description = "With all of the troubles, I've lost my assistants. I was wondering if maybe you could help me?\n\nI have many crab traps under the waves of the harbor. Will you retrieve them for me? I'm too old for that sort of thing and the waters can be very dangerous.\n\nPlease, take this bladder. It will help you to breathe while you're down there.", objectives = "" }
WordHunterWoW_QuestEN[12010] = { title = "The Fate of Orlond", description = "When we began excavating the city, I sent Surveyor Orlond to check the stability of the tunnels in Thor Modan. I didn't see him escape when we withdrew at the beginning of the battle, and I worry he may still be trapped inside the city.\n\nIf we're going to get an army through Thor Modan, we'll need the information he was collecting. Stoutmantle and his superiors would have my hide if the tunnels collapsed on one of their brigades!", objectives = "" }
WordHunterWoW_QuestEN[12011] = { title = "Signs of Big Watery Trouble", description = "This crab trap appears to have been destroyed by something much larger than the nearby circling sharks.\n\nPerhaps Tua'kea, the fisherman at Moa'ki Harbor, should be told about this?", objectives = "" }
WordHunterWoW_QuestEN[12012] = { title = "Inform the Elder", description = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", objectives = "" }
WordHunterWoW_QuestEN[12013] = { title = "End Arcanimus", description = "There is one last thing that I would have you do, {name} the {race}. I would have you destroy Arcanimus!\n\nThe sorcerers to the west used that giant device in the sky to bore a massive pit into our resting place. When they did that, they unleashed a monstrosity!\n\nI would not care if it were only a concern for mortals, but Arcanimus feeds upon the spirits of the dead.\n\nYou will put an end to it now!", objectives = "" }
WordHunterWoW_QuestEN[12014] = { title = "Steady as a Rock?", description = "Orlond's notes indicate that he brought a piece of equipment called a portable seismograph with him, but the device is nowhere to be seen.\n\nThe survey log shows that Orlond completed all his readings in the Thor Modan tunnel, save one labeled the 'east end of the exposed tunnel.'\n\nThe last entry in the log indicates Orlond tried to take refuge in the water and was attacked by subterranean threshers. They might've taken his equipment.You'll need to recover it before you can take the last reading.", objectives = "" }
WordHunterWoW_QuestEN[12016] = { title = "The Bait", description = "I'm sure of it... our ancient aquatic nemesis, Tu'u'gwar, \"He Who Plays With Food\", has returned. We must lay a trap for him, you and I.\n\nIf Tu'u'gwar has one weakness it's his stomach. There's one meat for certain that he'd never be able to pass up.\n\n\"Two Huge Pincers\", the mother of all crabs, Kili'ua, paces upon her island out in the waters to the southwest. You must pay her a visit and return with her meat.", objectives = "" }
WordHunterWoW_QuestEN[12017] = { title = "Meat on the Hook", description = "The time has come my friend: Tu'u'gwar must be dealt with!\n\nI've prepped the meat so that the beast is sure to come once you bait the hook I have out in the water. Just follow the fishing line here down to it.\n\nWhatever you do, don't let Tu'u'gwar swallow you whole, {name}!", objectives = "" }
WordHunterWoW_QuestEN[12019] = { title = "Last Rites", description = "I served Arthas in death, because I had no choice.  He had control over my will and my body.  The Cult of the Damned serves Arthas in life... willingly.\n\nNow that we know the words of power to enter Naxxanar we can put an end to the cultist blight.  Go to En'kilah and look for the teleportation orb beneath the floating citadel.\n\nWork your way up and meet me at the top.  Arm yourself with what courage you can, we might not make it out of this alive.", objectives = "" }
WordHunterWoW_QuestEN[12020] = { title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Boxey and explain your heroic triumph over the Dark Iron dwarves.", objectives = "" }
WordHunterWoW_QuestEN[12022] = { title = "Chug and Chuck!", description = "Hey there! You look like you can handle your brew.\n\nBut can you handle your brew mug?\n\nWe like to keep things lively around camp, and nothing says fun like a good old-fashioned mug toss!\n\nThink you've got the aim to hit S.T.O.U.T.? Just grab a sampler, take a sip, and see if you can land a hit. It's trickier than it looks, but that's half the fun. Step right up and give it a shot!", objectives = "" }
WordHunterWoW_QuestEN[12026] = { title = "The Damaged Journal", description = "This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps in the dwarven language.\n\nThe only text you're able to decipher is the name of Brann Bronzebeard scrawled at the end of one of the entries.\n\nThe back half of the book, containing the most recent entries, has been torn away. Someone thought the notes important enough to attempt to destroy them. Perhaps gathering the missing pages from the battlefield will yield some clues.", objectives = "" }
WordHunterWoW_QuestEN[12027] = { title = "Mr. Floppy's Perilous Adventure", description = "Excuse me, Mister, do you know the way back to the soldiers' camp?\n\nMr. Floppy and I decided to go for a walk in the woods, and my brother Walter was gonna come with us, but then he had squire things to do.\n\nSo Mr. Floppy and I went by ourselves, but we got lost, and there were a whole bunch of hungry wolves, but we found this tower.\n\nThe wolves went away, but we're still lost.\n\nI asked Mr. Floppy, and he doesn't know the way back. Would you help us? Please?", objectives = "" }
WordHunterWoW_QuestEN[12028] = { title = "Spiritual Insight", description = "{race}, we have not heard from our people at Indu'le Village since the ground shook and was torn apart!\n\nHave you ever been upon a vision quest? You've bested Loguhn, so you must be capable.\n\nI will give you a special incense to sprinkle into my brazier. Breathe deep from its vapors and your spirit will be sent aloft to view what has transpired at Indu'le.\n\nAs your spirit soars, I will be able to look through your eyes.", objectives = "" }
WordHunterWoW_QuestEN[12029] = { title = "Seared Scourge", description = "<Hic>... gotta burn these corpshes 'fore they shtart walkin' around again.\n\nPoppa always said, only thing worshe than havin' to kill a troll is havin' ta kill a troll twice.\n\nSay,<hic>... shpeakin' of Scourge, we can't get into tha' troll keep up north 'til we get them trolls thinned out a bit.\n\nHow 'bout ya take shome o my grog here and put them bashtards outta their misery?", objectives = "" }
WordHunterWoW_QuestEN[12030] = { title = "Elder Mana'loa", description = "My people....\n\n<The mystic is on the verge of breaking down.>\n\nWhile your spirit was flying through the village, I sensed that Elder Mana'loa took notice of you. {name}, he wishes to speak with you. The stone elders are revered by us as fonts of ancient wisdom.\n\nThe elder must want to help. Seek him in the northwest corner of the village.", objectives = "" }
WordHunterWoW_QuestEN[12031] = { title = "Freedom for the Lingering", description = "The sacred ground of the elves to the west has been torn asunder. Now their magic is moving through the land causing ruin where it flows.\n\nThe souls of the Kalu'ak are in danger as the blue dragons forces attempt to control the magic.\n\nThe power came up through the lake, instantly slaying most in the village. Those that survived were driven insane.\n\n{name}, you must release these spirits so that they may move on. Leave the deranged living alone; they may yet regain their sanity in time.", objectives = "" }
WordHunterWoW_QuestEN[12032] = { title = "Conversing With the Depths", description = "The watery goddess, Oacha'noa, must be consulted; only she will know what the destiny of the Kalu'ak is to be. And only The Pearl of the Depths can call her forth from the murky nether.\n\nOff the coast to the southwest rises The Briny Pinnacle. Atop it sits the altar upon which the pearl rests.\n\nCommune at the altar and Oacha'noa is certain to hear your call. Do as she says lest you incur her wrath and bring ruin upon all of the tuskarr.\n\nShould you survive, return to the mystic.", objectives = "" }
WordHunterWoW_QuestEN[12033] = { title = "Message from the West", description = "<Torvus shakes your hand, giving you a letter in the process.>\n\n<Torvus speaks under his breath.>\n\nJust play along, {name}.\n\nIt is good to see you here, soldier! Lord Hellscream has undoubtedly sent his strongest warriors to Lord Agmar!\n\n<Torvus speaks under his breath.>\n\nRead it and then destroy it in the fire pot next to me.", objectives = "" }
WordHunterWoW_QuestEN[12034] = { title = "Victory Nears...", description = "There remain only two primary threats that stand in our way. One is the dread citadel of Naxxramas, far to the east, above the Alliance fortress of Wintergarde and the other is the Pit of Narjun, exit point for the undead armies of Azjol'Nerub. It is from the Pit of Narjun that the Anub'ar Nerubians assaulted and ultimately razed the taunka village of Icemist.\n\nWe will destroy the Anub'ar and close off the Pit of Narjun.\n\nReport to Senior Sergeant Juktok for your mission orders.", objectives = "" }
WordHunterWoW_QuestEN[12035] = { title = "Repurposed Technology", description = "Ok, I've got it!  The rewiring is a little complicated, but nothing a clever {class} like you can't handle.\n\nTake my tools and put some of the harvest collectors out of commission.  Once they're down use the tools to plug all the red wires into the blue sockets.  That'll make them go into self-defense mode.  Hurry, {name}.  Before long there won't be anything left to save.", objectives = "" }
WordHunterWoW_QuestEN[12036] = { title = "From the Depths of Azjol-Nerub", description = "The undead Nerubians that attacked Icemist Village came from a gigantic sinkhole known as the Pit of Narjun. If left alone, those fiends will no doubt flank our forces at the Wrathgate and end our march to victory.\n\nI need eyes on the ground, {name}. You are to head west and investigate the Pit of Narjun. We need to locate their primary exit point and seal it off! Find me that location.\n", objectives = "" }
WordHunterWoW_QuestEN[12037] = { title = "Search and Rescue", description = "Orcs... they just don't lissen <hic>. Know what I mean, {race}?\n\nKurzel's been with us fer years. You'd think she'd get a feel fer how we do things by now. Lure the fools in fer the dangerous work, then reap the rewards when it's safe. What's so hard to understand?\n\nNot her though... she goes off and takes matters into her own hands. Probably dead by now, but I'd feel horrible if we didn't follow after her, and I'm in no shape to do it myself <hic>.\n\nSo whatdya say, pal?", objectives = "" }
WordHunterWoW_QuestEN[12038] = { title = "Seared Scourge", description = "Whatcha waitin' fer, {class}? Them shcourged trolls ain't gunna kill themselves!\n\nYou know the drill. Git up ta Drak'Tharon up north... Take some o thish here grog and hurl it at 'em from a distance...<hic>.  Then jusht sit back an' watch 'em burn.", objectives = "" }
WordHunterWoW_QuestEN[12039] = { title = "Black Blood of Yogg-Saron", description = "Angrathar, the Wrathgate... I watched as the metal holding the gate together pulsed and undulated as if it were alive! In 50 years I've never seen metal \"breathe.\"\n\nOnly ones who knew anything about it were the tuskarr. They called it the \"Black Blood of Yogg-Saron\" and told me to keep my distance.\n\nThere's a sinkhole outside Icemist Village to the west called the Pit of Narjun. I've heard of these sinkholes being rich with this strange ore. If you head that way, could you try and get me some samples?", objectives = "" }
WordHunterWoW_QuestEN[12040] = { title = "An Enemy in Arthas", description = "We are in the midst of a civil war. At the heart of this world the last living members of my species defend themselves against total annihilation. The Lich King seeks to rule the kingdom of Azjol-Nerub at any cost. Those that do not acquiesce are branded enemies of the Scourge and marked for death.\n\nIn Arthas we both have an enemy...\n\nJoin our cause and rid this place of the taint of Anub'ar! Let Anub'arak himself hear the anguish of their death cries!", objectives = "" }
WordHunterWoW_QuestEN[12041] = { title = "The Lost Empire", description = "You have proven that you are willing to assist the Azjol Empire in its time of need and as such the Azjol Empire will assist the Horde.\n\nTake this scroll back to your leader. It documents the strengths and weaknesses of the Nerubians attacking Icemist Village. Consider it a gesture of good faith - a willingness to help your people. Use the knowledge on those pages to crush the Anub'ar and you will have done a service for us all.\n\nFarewell, {race}.\n", objectives = "" }
WordHunterWoW_QuestEN[12042] = { title = "Heart of the Ancients", description = "Secrets of da ages, be revealed to me now!\n\n<Drakuru peers through the Eye of the Prophets.>\n\nAhh, great be mah destiny, {name}. You be lucky ta know me....\n\nThere! I be seein' it, mon. The Heart of the Ancients. Dis be too easy!\n\nYou gunna find da heart lyin' near da corpse of a goblin east of here. He be up in a chamber, near a river of broken trees.\n\nHurry, mon, before someone else be findin' it!", objectives = "" }
WordHunterWoW_QuestEN[12043] = { title = "Nozzlerust Defense", description = "You, {class}!  These undead south of us are being a constant nuisance to our work.  Go clear them out, will ya?", objectives = "" }
WordHunterWoW_QuestEN[12044] = { title = "Stocking Up", description = "Hello hello!  The Scourge to the south are digging up some ancient dragon thing.  I could care less why they're doing it, but they're pulling cartloads of composite ore in the process.\n\nGo lift me a bunch of that ore.  That stuff should yield a pretty penny for all the weapons the Horde are crafting.\n", objectives = "" }
WordHunterWoW_QuestEN[12045] = { title = "Shaved Ice", description = "I've never seen you before... are you new to the Vice?  Glad to have you.  I could always use some more hands.\n\nYou get the materials, I'll finish my machine, then we can sell it to those commander types and all go home rich.\n\nI actually have most of the primary components, so I just need some of the materials for the weapon itself.  Narf said that jagged ice shards from those elementals to the north would make perfect shrapnel for my bombs - go nab some, will ya?\n", objectives = "" }
WordHunterWoW_QuestEN[12046] = { title = "Soft Packaging", description = "I need some new packaging for the shrapnel bombs.  All the stuff I have is too hard and the shrapnel doesn't spread when it bursts.  \n\nWhat we need is some really thin animal hide.  Those jormungar tunnelers to the west might work... or perhaps the condors sifting through the dragon bones.  Go get me whatever you can find.\n", objectives = "" }
WordHunterWoW_QuestEN[12047] = { title = "Something That Doesn't Melt", description = "No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel.\n\nI know! I'm brilliant. Bone splinters.\n\nThere are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.", objectives = "" }
WordHunterWoW_QuestEN[12048] = { title = "Scourge Armaments", description = "I can't make a damned thing out of this ore. It simply will not hold together! Despite my best efforts the Scourge metal will not bend!\n\nPerhaps if I had some samples of some forged Scourge armaments I might be able to reverse engineer the process by which the items are created.\n\nIcemist Village is crawling with armored Scourge Nerubians. Go there and get me some Scourge armaments! With your help I might actually succeed in creating something from this ore.\n\nYou'll find Icemist to the west.", objectives = "" }
WordHunterWoW_QuestEN[12049] = { title = "Hard to Swallow", description = "Those troops are sure to be needin' a hefty supply of food in their bellies.\n\nI'll let you in on a little secret that a squeamish {race} like you would never know... those jormungar worms taste just like chicken.\n\nGo provoke one of those giant hulking jormungar to the east.  You're not likely to be able to kill one straight out, so just toss this down its throat when it opens its mouth wide.  Bring me back as many of the slabs of meat as you can tote.", objectives = "" }
WordHunterWoW_QuestEN[12050] = { title = "Lumber Hack", description = "Next up, we need to haul in some lumber for all the towers the Alliance are building.  There are some thin trees to the south, but the trees the harpies are nesting in to the north look much more fit for structures.\n\nTake this.  When you get to the harpy nesting area, use the control and one of my Shredders should come to you.  Gather as much lumber as it can carry.  The harpies are sure to disagree with you chopping down their homes - just deal with them as necessary.\n\nHop to it!", objectives = "" }
WordHunterWoW_QuestEN[12051] = { title = "Rustling Some Feathers", description = "Those harpies have slowed our profits long enough!  Kill them all.", objectives = "" }
WordHunterWoW_QuestEN[12052] = { title = "Harp on This!", description = "{class}, did you see that? That's the harpy that's been leading the attack on our shipments to the gate! I've seen her in the back of Coldwind Heights before.\n\n Those harpies have slowed our profits long enough! Kill them all.", objectives = "" }
WordHunterWoW_QuestEN[12053] = { title = "The Might of the Horde", description = "The taunka are now our brothers in arms. We must show our solidarity and retake Icemist Village.\n\nYou will find Icemist Village west of Agmar's Hammer, sitting at the foot of the mountains. Travel there and challenge the Anub'ar Nerubians! Plant our beloved Horde banner at Icemist Village and destroy all that dare come to tear it down!\n\nLet the Anub'ar feel the true might of the Horde! Let our battle standard be the last thing that they see before death!", objectives = "" }
WordHunterWoW_QuestEN[12054] = { title = "Deciphering the Journal", description = "Vor'takh is right -- we cannot allow this opportunity to slip through our fingers.\n\nFortunately, I think I know of a way to translate the journal of this Brann.\n\nThe shamans of the Redfang furbolgs, who congregate at the Heart's Blood Shrine south of the camp, grow an herb known as spiritsbreath. An experienced mystic can use incense made from it to seek wisdom from the spirits of the ancestors.\n\nSeek out the shaman known as Grumbald One-Eye. He should carry the herb for his devotions to Ursoc.", objectives = "" }
WordHunterWoW_QuestEN[12055] = { title = "A Strange Device", description = "Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use.\n\nPerhaps the archmage back at Stars' Rest to the east of the Moonrest Gardens would be able to tell what it's used for?", objectives = "" }
WordHunterWoW_QuestEN[12056] = { title = "Marked for Death: High Cultist Zangus", description = "I witnessed his treachery with my own eyes! The traitor led an Anub'ar assault on this stronghold, taking out some of my best soldiers.\n\n<Gort shakes his head.>\n\nHe'd been working with the Scourge the whole time and we didn't have a clue! How many more like Zangus are there? We'll find 'em all and when we do...\n\n<Gort makes a cutting motion across his neck.>\n\nFirst on the list is Zangus. Our scouts report that he is hiding in The Pit of Narjun, west of here. Find him, kill him, bring me his head.\n", objectives = "" }
WordHunterWoW_QuestEN[12057] = { title = "The Flesh-Bound Tome", description = "The tome is bound in flesh and appears to be bleeding. Upon examination you discover page after page filled with strange symbols that appear to be written in blood.\n\nWhatever knowledge is held within the pages of this tome could be important. Return it to Captain Gort at Agmar's Hammer, east of Icemist Village.", objectives = "" }
WordHunterWoW_QuestEN[12058] = { title = "The Runic Prophecies", description = "Brann's journal also contained a guide to iron dwarf symbols. I've inscribed these on a keystone which will help you to understand the words inscribed on the rune plates.\n\nFrom the journal entries, it seems Brann may be chasing after clues to the origins of his people. Keep your eyes open for any clues as to his destination.\n\nReturn to Thor Modan, northeast of here, stand before each of the plates, and use the stone to determine the contents of each. We can't allow the Alliance to find him first.", objectives = "" }
WordHunterWoW_QuestEN[12059] = { title = "A Strange Device", description = "Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use.\n\nPerhaps the archmage back at Agmar's Hammer to the northeast of the Moonrest Gardens would be able to tell what it's used for?", objectives = "" }
WordHunterWoW_QuestEN[12060] = { title = "Projections and Plans", description = "This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the west.\n\nI need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off.\n\nI expect that once you teleport to the top of the surge needle, there will be some sort of apparatus on it to observe.\n\nYou should be able to use the teleporter from anywhere within the gardens.", objectives = "" }
WordHunterWoW_QuestEN[12061] = { title = "Projections and Plans", description = "This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the southwest.\n\n{name}, I need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off.\n\nI expect that once you teleport up to the top of the surge needle, there will be some sort of apparatus on it to observe.\n\nYou should be able to use the teleporter from anywhere within the gardens.", objectives = "" }
WordHunterWoW_QuestEN[12062] = { title = "Insult Coren Direbrew", description = "Coren Direbrew is in the next room, riling up Dark Iron dwarves for another attack on Brewfest.  Defeat him!\n\nGo to Coren and pick a fight.  Tell him his beer isn't fit for pigs.\n\nWhen you do that, be ready for a fight.  The last person who insulted his brew... was fed to dire boars.", objectives = "" }
WordHunterWoW_QuestEN[12063] = { title = "Strength of Icemist", description = "<Greatmother Icemist bows.>\n\nIt is an honor to meet you, hero. It is because of your actions that many of us are here now, alive and ready for battle against the Scourge.\n\nYou have done so much for us that it shames me to ask you for your assistance once more. Despite my pleas, my only son, Banthok, left here to go in search of his father, High Chief Icemist. He was last seen heading west, towards Icemist Village. Please find Banthok. I do not know what I would do if I lost my son.", objectives = "" }
WordHunterWoW_QuestEN[12064] = { title = "Chains of the Anub'ar", description = "They have my father bound by magical chains in the middle of Icemist Village. From what I have been able to gather, the prison is controlled by three powerful Anub'ar magi - each holding a piece of the key.\n\nScour Icemist and locate the magi. Kill them and take their key fragments. With all three pieces we might be able to free my father. Once he is free...\n\nRetribution will come swiftly.", objectives = "" }
WordHunterWoW_QuestEN[12065] = { title = "The Focus on the Beach", description = "The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it.\n\nNo doubt the captain will have some sort of controlling device on their person. Get the controller and use it on the focus.\n\nWith any luck, we'll be able to get some more information about what they're really up to out there.", objectives = "" }
WordHunterWoW_QuestEN[12066] = { title = "The Focus on the Beach", description = "The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it.\n\nNo doubt the captain of the force down there will have some sort of controlling device on their person. Get the controller and use it on the focus.\n\nWith any skill on your part, we'll be able to get some more information about what they're really up to out there.", objectives = "" }
WordHunterWoW_QuestEN[12067] = { title = "A Letter for Home", description = "You find a letter secreted in the lining of her robes. It reads:\n\n\"Father,\n\nI'm sorry for disappearing on you. If you're reading this letter, then I'm dead.\n\nI've been forced to work for Malygos's armies under threat that our family would be killed if I didn't. I feel so ashamed.\n\nIf there's anything that you can do to fight them, don't worry about me. I have them fooled and I'm sabotaging them from the inside.\n\nI love you, Daddy!\n\nEm\"\n\nCommander Saia Azuresteel will want to see this!", objectives = "" }
WordHunterWoW_QuestEN[12068] = { title = "Voices From the Dust", description = "<Drakuru places the Eye of the Prophets on his brow and the Heart of the Ancients on his chest.>\n\nWe be close, mon, very close!\n\nThe Drakkari Tablets be all dat remain ta be found. Nobody be knowin' how old dey be or what dey be sayin', but with the eye and the heart Drakuru can be readin' dem. Dey lie deep inside the crypt at Drakil'jin, due east of here.\n\nOnce ya got the tablets, get sacred mojo from the oracles and protectors so ya can summon me there. They'd be proud to be dyin' for such a cause.", objectives = "" }
WordHunterWoW_QuestEN[12069] = { title = "Return of the High Chief", description = "<Banthok hands you the prison key.>\n\nYou must hurry, {name}. Take the key and use it to unchain my father from the Anub'ar prison. Once he is freed, assist him in destroying the Anub'ar leader, Under-king Anub'et'kan. When the Under-king is defeated, take from his chitinous carapace a fragment as a trophy to present to the Horde at Agmar's Hammer. Let Agmar see the might of the High Chief!", objectives = "" }
WordHunterWoW_QuestEN[12070] = { title = "Rallying the Troops", description = "The sons of iron have used their runes to enthrall many of my brothers and are using them to break the siege on Thor Modan. I wish we did not have to fight them, but we have no choice.\n\nMy giants will not hold out long against them.\n\nI have imbued this earthen shard with a blessing that will aid our allies. Take it with you to the battle in the Boulder Hills to the north, and use it to reassure and fortify my brethren.\n\nKill any iron dwarves who would stand in your way.", objectives = "" }
WordHunterWoW_QuestEN[12071] = { title = "Attack by Air!", description = "They have seen the might of the Horde by land, now they must feel it from the air! I want you to report to Valnok Windrager at once! You will find him here, in Agmar's Hammer.\n\nValnok has already been briefed on your mission and is expecting you.\n", objectives = "" }
WordHunterWoW_QuestEN[12072] = { title = "Blightbeasts be Damned!", description = "You've no doubt seen the army of Anub'ar blightbeasts that are being constructed at Icemist Village. The Anub'ar have plans to send those monsters against our soldiers at the Wrathgate. This cannot happen!\n\nVenture west to Icemist Village with this flare gun and use it to call down one of my war riders. Climb on its back and command it to destroy the blightbeasts that are out of reach from the ground!\n\nOnce you have decimated their aerial forces, return to me for your reward!", objectives = "" }
WordHunterWoW_QuestEN[12073] = { title = "Pounding the Iron", description = "The Alliance isn't the only force opposing us in Grizzly Hills. The iron dwarves have firm control of the eastern coast, although Thor Modan, to the northeast, is besieged by stone giants.\n\nA skilled warrior uses an enemy's weakness against him and we would be fools to ignore the vulnerability of the iron dwarves at Thor Modan. Show the iron dwarves no mercy. Slay any and all who would stand in your way.\n\nThe 'sons of iron' will learn to fear the Horde.", objectives = "" }
WordHunterWoW_QuestEN[12074] = { title = "An Expedient Ally", description = "The old iron dwarf capital of Thor Modan, far to the northeast, is under siege by a mysterious band of stone giants and earthen.\n\nWhy the creations of the titans would war against each other is beyond my understanding and the Horde's interest, but there is an opportunity here to weaken a mutual enemy.\n\nTravel to Thor Modan and seek out this 'Kurun' who commands the giants and earthen. Make common cause with him and use his forces to crush the iron dwarves.", objectives = "" }
WordHunterWoW_QuestEN[12075] = { title = "Slim Pickings", description = "Cold out here, isn't it, {race}?\n\nKo'char has refused to meet with me. It seems he has more pressing things on his mind - namely, the jormungar that have been attacking them from the cavern below. Maybe you can help me convince Ko'char that I'm one of the good guys.\n\nI saw a giant being eaten by some of the worms at the entrance to the cavern north of here... I'm still puzzled as to how the worms are killing them so easily. Bring me a sample from one of his wounds.", objectives = "" }
WordHunterWoW_QuestEN[12076] = { title = "Messy Business", description = "Even at first glance, the sample you brought me shows obvious signs of some kind of corrosive spit. It would be a natural assumption that the same substance these worms use to burrow through the ground has allowed them a formidable weapon against the Ice Giants.\n\nTake this scraper and pick a fight with some of the worms. When they spit on you, use the scraper to remove it and bring it back to me.\n\nGet me a couple samples - I'm going to have to use it as the base for an elixir.", objectives = "" }
WordHunterWoW_QuestEN[12077] = { title = "Apply This Twice A Day", description = "This elixir should protect against their spit. Offer it to Ko'char for me, will you? Tell him there's plenty more where that came from if he'll return the favor.", objectives = "" }
WordHunterWoW_QuestEN[12078] = { title = "Worm Wrangler", description = "So be it. If the giants will not come to our aid, perhaps we can make use of these worms. There are sure to be some spawn with their brood mother in the cavern below. Take this box and capture 3 of their spawn and bring them to me.\n\nWhere diplomacy fails, enslaving is a perfectly viable alternative.", objectives = "" }
WordHunterWoW_QuestEN[12079] = { title = "Stomping Grounds", description = "Greetings little one.  I know not what madness has brought you to the Crystal Vice, but you are welcome in my presence.  \n\nThese ice worms... these jormungar have taken a taste to eating my brothers.  I doubt you will find my kind friendly by any terms during this time of battle, but if you are here to help with the worms, then you have my ear.\n\nIf we are to take the cavern back, we must first clear the canyon of these jormungar feeders.  Join us in battle, {race}!", objectives = "" }
WordHunterWoW_QuestEN[12080] = { title = "Really Big Worm", description = "The jormungar have a spawnmother in the caverns below. We call her Rattlebore - a name that was gifted to her by an adventurer from the Plaguelands. I saw her only briefly as I was fighting off their initial onslaught - she is large enough to devour one of my young whole. This cavern will not be ours until she is removed from it.", objectives = "" }
WordHunterWoW_QuestEN[12081] = { title = "Gavrock", description = "Without your help, we wouldn't have been able to turn the tide of the battle for Thor Modan. This ancient city has long been a battlefield between the forces of earth and stone. I can only hope we have silenced it for the last time.\n\nThe iron dwarves can still use their magic to capture and enslave my brothers. Gavrock is searching for a way to free the runed giants. Look for him on a small cluster of islands, called the Ruins of Tethys, off the central part of the Eastwind Shore to the south.", objectives = "" }
WordHunterWoW_QuestEN[12082] = { title = "Dun-da-Dun-tah!", description = "Listen, kid. This is no place for you to be playin' around.\n\nI'm about to make a break for it. Stick with me and I'll get you outta here.", objectives = "" }
WordHunterWoW_QuestEN[12083] = { title = "Atop the Woodlands", description = "I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though.\n\nMy guess is that you'll find another one atop the Lothalor Woodlands to the southeast. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own.\n\nBe careful, {name}, those woods are very dangerous.", objectives = "" }
WordHunterWoW_QuestEN[12084] = { title = "Atop the Woodlands", description = "I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though.\n\nMy guess is that you'll find another one atop the Lothalor Woodlands to the south. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own.\n\nBe quick about your business, {class}. I feel that time may be running out.", objectives = "" }
WordHunterWoW_QuestEN[12085] = { title = "A Letter for Home", description = "You find a letter secreted in the lining of his robes. It reads:\n\n\"Deino,\n\nTa'zinni sorry for disappearing on ya. If you're reading this letter, then I be dead.\n\nI been forced to work for Malygos's armies under threat that the family would be killed if I didn't. Ta'zinni wasn't gonna let that happen!\n\nDon't worry about me, just keep your kids safe. I have them fooled and I'm sabotaging them from the inside.\n\nI love you, sistah!\n\nTa'zinni\"\n\nOverlord Agmar is sure to want to see this!", objectives = "" }
WordHunterWoW_QuestEN[12086] = { title = "The Son of Karkut", description = "The man you seek went far to the east, to a place near the coast called Death's Stand, beyond Unu'pe.\n\nBe careful if you go in search of him, {name}.  He bore the mark of Karkut... he who watches over the dead.", objectives = "" }
WordHunterWoW_QuestEN[12088] = { title = "Thassarian, the Death Knight", description = "Well, {name}, you helped us out... so I figure it's only fair that we help you out as well.\n\nYou're looking for Thassarian?  He disappeared this morning.  We think he went off north to the Wailing Ziggurat.  If we hadn't fought side by side by him we'd even think he was a traitor.\n\nSee, he's a Death Knight... and I know they're on our side and all... but it wasn't too long ago they were servants of Arthas.\n\nBut not Thassarian, he's a good guy.  Go to the Wailing Ziggurat, see if he's doing okay.", objectives = "" }
WordHunterWoW_QuestEN[12089] = { title = "WANTED: Magister Keldonus", description = "By decree of Overlord Agmar:\n\nTarget: Magister Keldonus\n\nCrime: Treason\n\nStatus: Alive\n\nMagister Keldonus, once mage commander of Agmar's Hammer, is to be killed on sight in the name of the Horde.\n\nKeldonus was last seen traveling southwest towards Moonrest Gardens to join the blue dragonflight in their campaign against magic.\n\nApproach with caution as Keldonus is a powerful magus.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", objectives = "" }
WordHunterWoW_QuestEN[12090] = { title = "WANTED: Gigantaur", description = "By decree of Overlord Agmar:\n\nTarget: Gigantaur\n\nCrime: Attacks upon the Horde; \"Bein' ugly\"\n\nStatus: Alive\n\nThe magnataur lord, Gigantaur, is wanted in relation to a number of attacks against Horde soldiers and installations in the Dragonblight.\n\nGigantaur was last seen wandering the woods and roads south by southeast of Agmar's Hammer.\n\nGigantaur should be considered armed and extremely dangerous.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", objectives = "" }
WordHunterWoW_QuestEN[12091] = { title = "WANTED: Dreadtalon", description = "By decree of Overlord Agmar:\n\nTarget: Dreadtalon\n\nCrime: Attacks upon the Horde\n\nStatus: Alive\n\nDreadtalon is wanted for numerous attacks upon Horde caravans traveling to and from Venomspite.\n\nDreadtalon makes his home on a bluff overlooking the Ruby Dragonshrine, east of Agmar's Hammer. He should be approached with extreme caution.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", objectives = "" }
WordHunterWoW_QuestEN[12092] = { title = "Strengthen the Ancients", description = "It's not only the {race} race that has been impacted by what the blue dragonflight forces have done. The ancients of the Lothalor Woods to the southeast have been affected as well.\n\nSome have been corrupted-- avoid them at all costs--but most can still be saved. However, the treants of the woods seem to be immune to the magic seeping through the land and the arcane wyrms that have come with it.\n\nAsk the treants for their bark and feed it to the ancients. Hopefully that will be enough to save them.", objectives = "" }
WordHunterWoW_QuestEN[12093] = { title = "Runes of Compulsion", description = "Even as Kurun attacks Thor Modan, the iron dwarves work their magics against our brothers. Summoning our brothers from the earth, then binding them with runes, the sons of iron force them to war against the children of stone.\n\nAlong the Eastwind Shore, they use runes of compulsion to send enslaved giants to the battlefields of the north.\n\nFind the four runes of compulsion and force their overseers to appear by defeating the rune-weavers who man each rune. Without the overseers, the runes are useless.", objectives = "" }
WordHunterWoW_QuestEN[12094] = { title = "Latent Power", description = "While the runes of compulsion are dormant, there is a chance we can release the runed giants.\n\nI will give you a piece of stone that has been part of me since my creation. If properly imbued, it can be used to free the bound giants.\n\nTwo ancient stone markers sit atop places of power between the Path of Iron and the forest's edge -- locations your people would call the intersections of ley lines. The other is on an island at the southern end of these ruins. Charge the shard at each stone and return.", objectives = "" }
WordHunterWoW_QuestEN[12095] = { title = "To Dragon's Fall", description = "East of here, in the heart of the Dragonblight, is a field full of nothing but dragon bones and snow. The Scourge have set up multiple camps in the central tundra and are raising frostwyrms to send against our forces at the Wrathgate. While most of these frostwyrms are easily dealt with by Rokhan and his dragon hunters, one of them is proving to be a bit problematic.\n\nGo northeast and seek out Rokhan at Dragon's Fall. Help him and his men put down Sarathstra and you'll be rewarded handsomely!", objectives = "" }
WordHunterWoW_QuestEN[12096] = { title = "Strengthen the Ancients", description = "The ancients of the Lothalor Woods to the south are being corrupted by arcane wyrms... wyrms which have risen out of the ground!\n\nThose that are already corrupted are deadly and of no use to us, but most can still be saved. Luckily, the treants of the woods seem to be immune to everything happening up there.\n\nAsk the treants for their bark and when you get some, feed it to the ancients. This should strengthen them.\n\nNow leave me to my business! I have to keep an eye on these apothecaries.", objectives = "" }
WordHunterWoW_QuestEN[12097] = { title = "Sarathstra, Scourge of the North", description = "Me hunters be dead or frozen, {name}. You still want to do dis? Just say da word and me call for da dragon once more.\n\nIf ya kill it, take da beast's frozen heart back to Agmar's Hammer and present it to Gort. He sure to reward you good, mon.", objectives = "" }
WordHunterWoW_QuestEN[12098] = { title = "Search Indu'le Village", description = "I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, we've had absolutely no reports of there being one there.\n\nIf you would, please investigate the village for any signs of the focus or the mage hunters and their commander in the area.\n\nDon't forget to search in the lake if you have to.", objectives = "" }
WordHunterWoW_QuestEN[12099] = { title = "Free at Last", description = "The rock shard you imbued should be powerful enough to break the runic magic binding my brothers.\n\nTake it with you and find the runed giants walking north along the Eastwind Shore. Unleash the power stored in the stone and observe the results.\n\nIf it works, the runed giants should return to their senses and stop obeying the iron dwarves. If the stone fails to work, the giants may attack in a weakened state. But, what choice do we have? If we do not try, they will remain enslaved without hope.", objectives = "" }
WordHunterWoW_QuestEN[12100] = { title = "Containing the Rot", description = "With Scourge comes death and disease. We often overlook that the wildlife of a Scourge infested area is ravaged and ultimately destroyed by rot and contagion.\n\nFor most of the indigenous beasts of the Dragonblight it is too late. The festering disease that the Scourge brings has already infected the beasts and they are now rabid and rotting.\n\nYou must venture west, towards the Pit of Narjun, and cull the infected wildlife. Check their corpses for a preserved organ as we need one to devise a vaccine.", objectives = "" }
WordHunterWoW_QuestEN[12101] = { title = "The Good Doctor...", description = "Our Forsaken allies have sent their apothecary core here to assist us in destroying the Scourge at the Wrathgate. One among them, Doctor Sintar Malefious, is well versed in the Scourge rot and methods of containing the spread. I had previously worked out a deal with him in regards to devising a vaccine for wildlife. He's since been waiting on the organ.\n\nDeliver this rot resistant organ to Dr. Malefious and let him know it's from me. He'll direct you on your next task.", objectives = "" }
WordHunterWoW_QuestEN[12102] = { title = "In Search of the Ruby Lilac", description = "How fortuitous it is that the Ruby Dragonshrine lays just to the east. It is there that you will find a flower called the ruby lilac. This lifegiving plant is all that I need to concoct a vaccine for the untainted beasts of this region.\n\nTravel east and search the Ruby Dragonshrine for the lilac.\n\nJust one thing: The dragonshrine, like all the dragonshrines in this blasted wasteland, is beset by the Scourge. Watch your step. We wouldn't want you to be devoured by an emberwyrm.\n\n<Sintar laughs.>", objectives = "" }
WordHunterWoW_QuestEN[12103] = { title = "Before the Storm", description = "{name}! I have been looking all over this strange city for you!\n\nGrand Master Hight has requested all senior monks to return to the Peak of Serenity as soon as possible. That means you too, of course.\n\nI'll bet a week's worth of brew that this has something to do with the assault on the Broken Shore I've heard tales about!", objectives = "" }
WordHunterWoW_QuestEN[12104] = { title = "Return to Soar", description = "<Doctor Malefious hands you a vial full of murky liquid.>\n\nHere you are then, {race}. Take this back to the cow and let him know that all debts have been paid. We are officially \"square.\"\n\nNow leave me before I set Jennings upon you.", objectives = "" }
WordHunterWoW_QuestEN[12105] = { title = "Descent into Darkness", description = "The journal was written by a denizen of Silverbrook named Mikhail.  It details the arrival of a shadow-worshipping group called the \"wolfcult.\"\n\nThe villagers were reluctant to embrace the cult at first, but sympathizers sprung up gradually among town residents.\n\nUnsettled by this, Mikhail sent his daughter Sasha away from Silverbrook while he attempted to reason with the other villagers.\n\nMikhail's last entry mentions a meeting of local town leaders to discuss unspecified events in Hollowstone Mine.", objectives = "" }
WordHunterWoW_QuestEN[12106] = { title = "Search Indu'le Village", description = "I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, I've had absolutely no reports of there being one there.\n\nI need you to go investigate the village for any signs of the focus or the mage hunters and their commander in the area.\n\nSearch in the lake if you have to!", objectives = "" }
WordHunterWoW_QuestEN[12107] = { title = "The End of the Line", description = "Within his robes you find two things of interest.\n\nOne is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens.\n\nThe water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine.\n\nPerhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.", objectives = "" }
WordHunterWoW_QuestEN[12109] = { title = "Report to Gryan Stoutmantle... Again", description = "The Westfall boys were sent east to look for a path into the northern territories.  Their secondary objective is to secure strategic resource points, so I'm sure they wouldn't mind investigating a mine.\n\nLook for the Westfall Brigade encampment far to the northeast and seek out Gryan Stoutmantle.  You might remember him if you ever spent any time in Westfall.  Make sure to tell him I sent you.\n\nHe'll be more than happy to let you claim a functioning mine for the king.", objectives = "" }
WordHunterWoW_QuestEN[12110] = { title = "The End of the Line", description = "Within his robes you find two things of interest.\n\nOne is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens.\n\nThe fragile water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine.\n\nPerhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.", objectives = "" }
WordHunterWoW_QuestEN[12111] = { title = "Where the Wild Things Roam", description = "Inside this pack are several vials containing the vaccine that Sintar created. I now want you to search the nearby woods for Snowfall elk and arctic grizzlies. When you locate the animals, find a safe distance and throw a vial in their general direction. The vial will shatter and release a fine gas that will act as the inoculating agent. The beasts merely have to step inside the gas and they will be vaccinated - ultimately saved.\n\nInoculate as many of the beasts as you can and return to me.\n", objectives = "" }
WordHunterWoW_QuestEN[12112] = { title = "Stiff Negotiations", description = "Well it seems you were of a bit of use after all. It's not been my experience to meet many a {race} that are.\n\nWe don't have any more use for you here. Head into the Vice and see if my brother Zort could use a hand. He went to see if he could con the giants into laying down their lives so that we don't have to. He certainly wasn't known for having the brains in the family.  ", objectives = "" }
WordHunterWoW_QuestEN[12113] = { title = "Nice to Meat You", description = "G'day to ya, {class}! Have yerself a seat by me fire, eh?\n\nI'd offer to share a nice hot meal, only I ain't got one. I'm stuck here waitin' on an associate, or I'd be out tryin' to remedy that situation meself.\n\nSay, you seem to have nuthin' but time on yer hands and there be plenty o' meat in these parts. What say ya lend a hand and round up some grub? ", objectives = "" }
WordHunterWoW_QuestEN[12114] = { title = "Therapy", description = "Trolls... me hates 'em all! <Harkor spits.>\n\nI once got meself captured by a band o' tha beasts... came this close ta gettin' me head shrunk!\n\nMe friends tell me to just move on and put it all behind me, but that just ain't sittin' right.\n\nWanna know what would make me feel better, {race}? Seein' a pile of their corpses so high it blots out the sun! I've got good gold to spend if ya can make that happen.", objectives = "" }
WordHunterWoW_QuestEN[12115] = { title = "Koltira and the Language of Death", description = "There is one who recently joined our cause that might be able to decipher this tome. An unbound death knight known as Koltira Deathweaver has temporarily taken residence here at Agmar's Hammer. As he was once a death knight of Arthas and member of the Scourge, he might be able to translate the language of the dead.\n\nTake the flesh-bound tome to Koltira and ask him to translate the pages.\n", objectives = "" }
WordHunterWoW_QuestEN[12116] = { title = "It Takes Guts....", description = "Greetings, {class}. It is kind of you to stop and listen to Kraz's tale.\n\nFor many years Kraz has strained to hear the spirits and do their bidding.\n\nRecently,  many voices have been crying to Kraz from these ruins. They seek for a peace they cannot find on their own.\n\nIf you would help the spirits of those who have come before, enter this crypt and collect something that once belonged to those tormented souls.", objectives = "" }
WordHunterWoW_QuestEN[12117] = { title = "Travel to Moa'ki Harbor", description = "{race}, word just arrived from Moa'ki Harbor. Something very bad happened over there this morning!\n\nYou've been very helpful to us here. Would you consider using the boat from Unu'pe to travel to the great Dragonblight?\n\nBy the sound of things, Elder Ko'nani could certainly use your assistance.", objectives = "" }
WordHunterWoW_QuestEN[12118] = { title = "Travel to Moa'ki Harbor", description = "{race}, word just came in off the boat from Moa'ki Harbor. Something very bad happened over there this morning!\n\nYou've been very helpful to us here. Would you consider using the boat to travel to the great Dragonblight?\n\nBy the sound of things, Elder Ko'nani could certainly use your assistance.", objectives = "" }
WordHunterWoW_QuestEN[12119] = { title = "Gaining an Audience", description = "{name}, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz.\n\nThe temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it.\n\nI'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late.\n\nThank you for all that you have done on our behalf. Safe journeys!", objectives = "" }
WordHunterWoW_QuestEN[12120] = { title = "Drak'aguul's Mallet", description = "Corruption....\n\nEven before you delivered these jars, Kraz could sense it. This corruption fills the ancient Drakkari spirits with great angst and prevents them from entering the rest they seek.\n\nKraz will not lie, {class}. Cleansing this place will require great sacrifice, but we shall speak of that at another time.\n\nThere is one among the living here who holds the key to its cleansing. Seek out Drak'aguul and return to Kraz with the mallet he carries.", objectives = "" }
WordHunterWoW_QuestEN[12121] = { title = "See You on the Other Side", description = "These Drakkari have met you with nothing but savage hostility. You owe them nothing. Few indeed would carry out the task that Kraz asks of you today.\n\nTo cleanse this place and send the spirits to their eternal rest, you must join them in death.\n\nThere is one inside the crypt who awaits you - on the other side. He holds the knowledge we seek, {name}.\n\nUse the mallet on the gongs. The spirit of he who corrupts this place will surely deliver you to the spirit world.\n\nKraz awaits your return.", objectives = "" }
WordHunterWoW_QuestEN[12122] = { title = "Gaining an Audience", description = "{name}, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz.\n\nThe temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it.\n\nI'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late.\n\nThank you for all that you have done on our behalf. Safe journeys!", objectives = "" }
WordHunterWoW_QuestEN[12123] = { title = "Informing the Queen", description = "<The dragon steward pulls your letter of introduction out of his sleeve.>\n\nYes... yes, I think that you are ready to see the queen now.\n\nWhen you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.", objectives = "" }
WordHunterWoW_QuestEN[12124] = { title = "Informing the Queen", description = "<The dragon steward pulls your letter of introduction out of his sleeve.>\n\nYes... yes, I think that you are ready to see the queen now.\n\nWhen you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.", objectives = "" }
WordHunterWoW_QuestEN[12125] = { title = "In Service of Blood", description = "The blood of innocents was once used to sate the thirst of the blade. Alas, such options are no longer available to me.\n\n<Koltira pauses to think.>\n\nWe must improvise. South of here, upon the high bluffs, is the tuskarr village of Indu'le. Having been recently overrun by the Blue Dragonflight's chaotic magic, the resident tuskarr of Indu'le have gone mad.\n\nTake this blood gem and use it on a deranged villager. If I cannot take the blood of innocents, I shall have the blood of the meek!", objectives = "" }
WordHunterWoW_QuestEN[12126] = { title = "In Service of the Unholy", description = "The power of the unholy is coveted among my kind. It makes up the very fiber of our existence, granting death to those that dare make a mockery of it! Thankfully there is a font from which I may draw from in my time of need.\n\nTake this unholy gem and make your way to the Ruby Dragonshrine, east of here. It is there that you will find Duke Vallenhal, death knight of Arthas. Weaken his resolve in battle and unleash the power of the gem upon him. It will finish him off and steal his unholy energy!\n", objectives = "" }
WordHunterWoW_QuestEN[12127] = { title = "In Service of Frost", description = "The biting cold protects the death knight while repelling his enemies. He that commands the power of frost can incite chaos and destruction!\n\nTake this frost gem and travel far across the open tundra of the Dragonblight until you come upon the Mirror of Dawn, east of Wyrmrest Temple. It is there that you are to battle the legions of ice revenants that dwell upon the lakes surface and take from them the essence of frost. Utilize the power of the gem when they are weak, {name}!", objectives = "" }
WordHunterWoW_QuestEN[12128] = { title = "Check Up on Raegar", description = "With all the excitement about the army trying to move through Thor Modan, I'd almost forgotten about Raegar's crew down at Prospector's Point.\n\nI sent Raegar and his assistants, along with a mountaineer friend, down to establish a small post near Dun Argol, at the southern end of the Eastwind Shore.\n\nThey were to investigate the iron dwarf presence in the southern hills, but I haven't received any reports yet. Could you check up on them if you're going down that way?", objectives = "" }
WordHunterWoW_QuestEN[12129] = { title = "The Perfect Plan", description = "The iron dwarves are making no secret of the fact that they're preparing for war. With their giants, golems, and lightning elementals, they'd have a technological advantage against the Westfall Brigade. If they don't find passage north in time, the irons could take them by surprise.\n\nWe've got to tie them up here, and I've got just the way to do it. Dun Argol is full of rune-smiths churning out war golems. They carry plans for specific pieces, so you'll need to find and assemble all the parts.", objectives = "" }
WordHunterWoW_QuestEN[12130] = { title = "Why Fabricate When You Can Appropriate?", description = "We've got the blueprints, but we can't do anything with them without parts! We don't have access to a foundry, much less materials, but there's a whole load of parts up in Dun Argol.\n\nYour job?\n\nGive them a new home.\n\nThey're likely to be scattered around any of the buildings where the iron rune-smiths are working, and I wouldn't blame the irons for being cranky when you try to filch their handiwork. The more parts you can bring, the better we can make this golem.", objectives = "" }
WordHunterWoW_QuestEN[12131] = { title = "We Have the Power", description = "We're almost there, but the war golem won't run without power cells. From the information I was able to collect in Dun Argol before we were discovered, both Rune-Smith Durar and Rune-Smith Kathorn each create one power cell.\n\nWe'll need one power cell from each of the rune-smiths before our golem will work.\n\nYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.", objectives = "" }
WordHunterWoW_QuestEN[12132] = { title = "The Power to Destroy", description = "While you have done much for me, one task remains.\n\nBeside the world you know exists another world. It is from that world, the world of shadows, that my tormentors assault me. While I am powerless to face my own demons, you could end their reign of terror. You have the strength, I have seen it with my own eyes.\n\nEnter the world of shadows and face the demons that torment me!\n\nDo this and I will translate the tome, as promised.", objectives = "" }
WordHunterWoW_QuestEN[12133] = { title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpkin reveals an old, scorched holy symbol.", objectives = "" }
WordHunterWoW_QuestEN[12134] = { title = "Sasha's Hunt", description = "This thing... this curse... that's affecting Silverbrook and Solstice Village... it makes beasts out of people.\n\nMy father tried to warn them, but they all listened to the wolfcult instead.\n\nThey're too far gone now, it's time to put them down... for their own sake.", objectives = "" }
WordHunterWoW_QuestEN[12135] = { title = "\"Let the Fires Come!\"", description = "You must help us!  The Headless Horseman will attack the village at any moment!  Fires will be everywhere!  The children aren't safe!\n\nPlease, {name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", objectives = "" }
WordHunterWoW_QuestEN[12136] = { title = "The Translated Tome", description = "Here it is, {name}. I have translated everything printed upon the pages of the tome. Inside it you will find a list of the names of Cult of the Damned members spanning the entire continent.\n\nTheir network of spies and operatives is impressive, to say the least.\n\nFarewell, friend. May the book serve you and your people well.", objectives = "" }
WordHunterWoW_QuestEN[12137] = { title = "Chill Out, Mon", description = "It be as the prophecies said, mon. A {race} {class} be comin' to set our spirits to rest. We been waitin' for a long time now!\n\nThe Drakkari have become a lost people, fierce and savage.\n\nBut here we suffer by no fault of our own, mon. This place need cleansin' and only the living can do it.\n\nSpeak to me when ya be ready to rejoin your body. Then take the snow from the chest near me here and put my bruddas to sleep.\n\nTake their remnants to your spirit guide. He be knowin' what to do next.", objectives = "" }
WordHunterWoW_QuestEN[12138] = { title = "... Or Maybe We Don't", description = "You'd think the guys making the power cells would've thought to power them up, but no, they've got to make it difficult for us.\n\nFine, we'll charge those cells the hard way. There's enough power in them to run the golem for a short time, but don't expect it to be any good in combat.\n\nYou see the lightning sentries that the irons have posted around the perimeter of Dun Argol? Bring the golem with you, take it close to them, and use the golem to absorb the power as the sentries die.", objectives = "" }
WordHunterWoW_QuestEN[12139] = { title = "\"Let the Fires Come!\"", description = "The Headless Horseman will attack the village at any moment!  Fires will be everywhere!\n\n{name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", objectives = "" }
WordHunterWoW_QuestEN[12140] = { title = "All Hail Roanauk!", description = "Like the tauren, Forsaken, trolls and blood elves, so too do the taunka need a leader born of their own blood. The one you saved from Icemist, Roanauk, will be this leader.\n\n<Overlord Agmar hands you a parchment.>\n\nI give to you something familiar - the blood oath of the Horde.\n\nTake the oath to Roanauk Icemist and initiate him into the Horde as leader of the taunka.\n\nLet us not keep him waiting.\n\n<Agmar nods.>\n", objectives = "" }
WordHunterWoW_QuestEN[12141] = { title = "A Diplomatic Mission", description = "I see that you are very eager to help, {name}.  You didn't come all the way to Northrend to stay holed up in a city!  I've just the task for you... something that'll take you far away from here.\n\nWe've long sought to gain the favor of the tuskarr native to Northrend.  Recently a young tuskarr came to us seeking help, something we couldn't offer at the time.\n\nNow that you're around, maybe you can lend him a hand.  Look for Karuk near the Riplash Strand, southwest of here, and see what you can do to help.  ", objectives = "" }
WordHunterWoW_QuestEN[12142] = { title = "Pest Control", description = "Ugh! One of those little snobold runts trashed our camp while we were busy with that last dragon. They've been plaguing us whenever we turn our backs... I've had enough!\n\nTo the south you'll find the snobolds hiding under the skirts of some of the local magnataur. Go slaughter them.\n\nIf the magnataur interfere on behalf of their slaves, kill them as well.", objectives = "" }
WordHunterWoW_QuestEN[12143] = { title = "Canyon Chase", description = "I can't believe this! Another band of those vermin just tried to take off with more of our supplies. They're scurrying off towards that north canyon, get after them and deal with whoever they're going to!", objectives = "" }
WordHunterWoW_QuestEN[12144] = { title = "Pest Control", description = "Oi, mon! One of dose little snobold runts trashed our camp during da last dragon attack. Dey've been houndin us wheneva we turn our backs and I've had enough. \n\nTo da east you'll find da snobolds hiding under da skirts of some of da local magnataur. Go slaughter dem. If da magnataur interfere on behalf of deir slaves, kill dem as well.", objectives = "" }
WordHunterWoW_QuestEN[12145] = { title = "Canyon Chase", description = "I can't believe dis! Another band of dose vermin just tried ta take off with more of our supplies. Dey're scurrying down da canyon now, get after dem and deal with whoever dey're going to!", objectives = "" }
WordHunterWoW_QuestEN[12146] = { title = "Disturbing Implications", description = "The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur.\n\nTake the horn south down the Path of the Titans to Wyrmrest and seek out someone who might be interested in these threatening implications.", objectives = "" }
WordHunterWoW_QuestEN[12147] = { title = "Disturbing Implications", description = "The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur. \n\nTake the horn east across the Dragon Wastes to Wyrmrest and seek out someone who might be interested in these threatening implications.", objectives = "" }
WordHunterWoW_QuestEN[12148] = { title = "One of a Kind", description = "Such a strange seal to see among magnataur... it suggests an unusual amount of organization.\n\nMagnataur rarely put aside their aggressive natures to cooperate with each other.  I suspect they have their eyes set on raiding a large settlement.\n\nI very much doubt that this horn is unique, I need you to prove me wrong. In the canyon northwest of the Azure Dragonshrine you will find Bonesunder. Go challenge him and bring me back any evidence you find that might confirm my concerns.", objectives = "" }
WordHunterWoW_QuestEN[12149] = { title = "Mighty Magnataur", description = "Magnataur are hideously violent creatures... this is the main reason we rarely see them come together in any real numbers without killing each other. A powerful leader has stepped up somewhere among them and we need to hunt him down if we are to stop this threat. \n\nI will start asking around. I need you to disrupt them as much as possible in the meantime.\n\nEast of here there are 3 torches erected. Near them, there are 3 dominant Magnataur - put them down to buy us some time to hunt down this leader.", objectives = "" }
WordHunterWoW_QuestEN[12150] = { title = "Reclusive Runemaster", description = "Dregmar Runebrand is a magnataur runemaster... a rare breed. He's generally solitary, but has been known to associate with the more powerful and influential magnataur in Dragonblight for quite some time. He will know who this new leader is. \n\nIt is unlikely we will gain any aid with the increasing concerns with the Scourge and the blue flight, so I need you to procure the information from Dregmar by any means necessary.\n\nI was told he can be found amongst the cliffs overlooking the Mirror of the Dawn.", objectives = "" }
WordHunterWoW_QuestEN[12151] = { title = "Wanton Warlord", description = "There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this.\n\nFollow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge.\n\nWhen Grom'thar the Thunderbringer arrives, kill him and bring me his head.", objectives = "" }
WordHunterWoW_QuestEN[12152] = { title = "Jin'arrak's End", description = "It is good to see you back among the living. Many who travel the path of the dead do not return to speak of it.\n\nWhile you were away, a vision appeared to Kraz revealing what remains to be done.\n\nA sacred offering lies somewhere inside the crypt. Take this spirit dust fashioned from the remnants you collected and use it on the offering.\n\nThe infused offering will bring an end to the corrupted warlord and will release the many tormented souls.\n\nMay the spirits guide your actions, {name}.", objectives = "" }
WordHunterWoW_QuestEN[12153] = { title = "The Iron Thane and His Anvil", description = "Now that you've charged up your war golem, we're going to put all that energy to good use. Activate the golem inside Dun Argol to take control of it.\n\nOur  information about Dun Argol's leader, Iron Thane Furyhammer, suggests his bodyguard protects him from all harm.\n\nThat bodyguard is the construct he travels with, called The Anvil. Disable the construct, and his protection will disappear.\n\nThe thane stays in the building at the top of Dun Argol and supervises production from the bottom level.", objectives = "" }
WordHunterWoW_QuestEN[12154] = { title = "Blackout", description = "The large hall at the top of Dun Argol houses the power source for the entire area. If you can destroy the power core, it will cripple Dun Argol for some time.\n\nNo power means no golems, no sentries, and no more lightning armaments.\n\nWhen we were sent up here, they told us these explosives were for excavation, but thanks to Iron Thane Furyhammer, the research has been scrapped. We may as well get some use out of them, though. They're the only thing we have on hand capable of destroying the power core.", objectives = "" }
WordHunterWoW_QuestEN[12155] = { title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpkin reveals an old, scorched holy symbol.", objectives = "" }
WordHunterWoW_QuestEN[12157] = { title = "The Lost Courier", description = "We're lucky we made it this far, {name}.  We were ambushed by Scourge as soon as we landed.\n\nOne of our men turned out to be a spy for the Cult of the Damned.  Thassarian appears to have more evidence of cultist infiltration.  Apparently it goes all the way to the top.\n\nI've sent one of my best couriers to our outpost in western Dragonblight, but he has not yet returned. I fear he may have fallen to the Scourge. Will you go to Dragonblight and search for him? Courier Lanson is his name.\n", objectives = "" }
WordHunterWoW_QuestEN[12158] = { title = "Hollowstone Mine", description = "I've been meaning to send some of our lads to check out Hollowstone Mine.  Haven't had a chance to yet -- we've had our hands full between the Horde on the west and the iron dwarves to the east.\n\nIf Dumont sent you, though, the least I can do is point you in the right direction.\n\nYou'll find the mine entrance to the northwest, not far from here.  See if you think operations there can be salvaged.  We sure could use the additional resources until our mine in Farshire is operational again. ", objectives = "" }
WordHunterWoW_QuestEN[12159] = { title = "Souls at Unrest", description = "<Petrov looks deeply disturbed, breathing heavily and shifting his gaze nervously around the mine.>\n\nMy comrades... we must put their souls to rest!  I kill them and kill them but.. they just come back!\n\nI've had an idea for a while but I just don't have the heart to do it myself.\n\nMaybe you can do this for me?  Take this lantern and use its oil to burn their remains so they never get up again.\n\nI'll answer your questions later.  Help my friends first!", objectives = "" }
WordHunterWoW_QuestEN[12160] = { title = "A Name from the Past", description = "It worked!  It worked!  My comrades can finally enjoy their well-earned rest...\n\nI'll stay here and finish the job.  We Hollowstone miners always finish the job -- we never give up!\n\nThat's why Arugal made an example of us.  We wouldn't fall in line, you see?  We wouldn't join his wolfcult!", objectives = "" }
WordHunterWoW_QuestEN[12161] = { title = "Ruuna the Blind", description = "Hey there.  I overheard what you were saying to the captain and I just want you to know...  things aren't that simple in Northrend.\n\nJust because someone's dead it doesn't mean they're out of the picture.\n\nSouthwest of here, near Vordrassil Pass, lives a blind woman who goes by the name Ruuna the Blind.  They say she speaks to the dead and has visions of the past and future.\n\nI haven't heard your whole story but it sounds like she'd be right up your alley.", objectives = "" }
WordHunterWoW_QuestEN[12164] = { title = "Hour of the Worg", description = "It is time, then, {name}.  Arugal must be defeated.\n\nGet a couple of people you can trust and head for Bloodmoon Isle.  It's just off the coast, east of here.\n\nWe'll hit them fast.  Take out Arugal's lieutenants -- I'll catch up with you when it's time to take out the monster himself.", objectives = "" }
WordHunterWoW_QuestEN[12165] = { title = "An Intriguing Plan", description = "Prospector Rokar has decided to help us. He's concocted a plan to use the iron dwarves' strength against them.\n\nI must admit, our new 'friend' is more insightful than I'd given him credit for. He's correct in that our numbers are too few for a direct attack.\n\nTravel to Dun Argol, in the snowy regions to the southeast, and capture all the parts of their war golem blueprints from the iron rune-smiths there. Bring the assembled blueprint to Rokar and we'll see if his plan has any merit.", objectives = "" }
WordHunterWoW_QuestEN[12166] = { title = "The Liquid Fire of Elune", description = "{race} will you assist me?\n\nThe Scourge have moved into Icemist to the north. Wherever they go, they spread their taint, and the creatures of the land suffer.\n\nTake this vial, which is filled with the liquid fire of Elune from the moonwell. Please, use the liquid to cleanse the corpses of the blighted wildlife that you find.", objectives = "" }
WordHunterWoW_QuestEN[12167] = { title = "Kill the Cultists", description = "The Anub'ar cultists are indirectly responsible for the plaguing of the beasts, and we must put an end to it!\n\nThe fumes that emit from the cultists' suits seep into everything they come near, poisoning and corrupting their surroundings.\n\nYou must go north to Icemist Village and slay them. Bring back any of their suits that survive your assault and I will see to it that they are properly disposed of.", objectives = "" }
WordHunterWoW_QuestEN[12168] = { title = "The Favor of Zangus", description = "An inscription on the back of the favor reads,\n\n\"To my favorite pupil,\n\nIf you continue to show promise, I will teach you wonders beyond your imaginings.\n\nIf you do not, I will have you destroyed!\n\nAs ever,\n\nHigh Cultist Zangus\"\n\nNo doubt the warden at Stars' Rest will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[12169] = { title = "The High Cultist", description = "I have dreamed of Zangus before but without the context that you have discovered, I knew not what it meant. You have brought clarity to the vision that the goddess has bestowed upon me, and now I know that he can be found within the Pit of Narjun to the north.\n\nYou know your target, {name}. If there's to be an end to the suffering of the land, the high cultist must die!", objectives = "" }
WordHunterWoW_QuestEN[12170] = { title = "Blackriver Brawl", description = "The Venture Company abandoned operations shortly after we showed up.  Clearly they were afraid of what we were going to do to their greedy little hides.\n\nWith them gone, their logging camps are up for grabs.  Our war machine is a hungry beast... without renewing our supplies we won't make it to Icecrown.\n\nUnfortunately the Alliance seems to have the same idea and we must make sure we're the ones that prevail.  Head into the logging camp and help us fight the Alliance scum.", objectives = "" }
WordHunterWoW_QuestEN[12171] = { title = "Of Traitors and Treason", description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.\n\nHurry, {name}. Show the document to Palena Silvercloud here at Stars' Rest and explain the nature of your mission. She will put you on her fastest hippogryph to Wintergarde!", objectives = "" }
WordHunterWoW_QuestEN[12172] = { title = "Attunement to Dalaran", description = "Welcome, mage.\n\nBy now you must be wondering where Dalaran is and how to get there. I will help you.\n\nBut before I can teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you risk destroying yourself in the process.\n\nTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the west. Then you will be ready to learn the spell.", objectives = "" }
WordHunterWoW_QuestEN[12173] = { title = "Attunement to Dalaran", description = "Hello, mage.\n\nBy now you must be wondering where Dalaran is and how to get there. I can help you with this if you can survive a simple test.\n\nBefore I teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you will destroy yourself in the process!\n\nTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the southwest. Then you will be ready to learn what I have to teach.", objectives = "" }
WordHunterWoW_QuestEN[12174] = { title = "High Commander Halford Wyrmbane", description = "<Palena hands the missive back to you.>\n\nSnowstorm will take you to Wintergarde, {name}. I guarantee you that it will be the fastest flight you've ever taken. Go now!\n", objectives = "" }
WordHunterWoW_QuestEN[12175] = { title = "Gray Worg Hides", description = "Let me tell you something, mon.  When you get put in charge of outfittin' the armies of the Horde, you go through a lot of hides!\n\nConqueror Krenna, the she-wolf runnin' this place, she gave me a tight deadline.  If I don't outfit her whole regiment by week's end she's gonna have me wrestling bears in the pit.\n\nHelp me out and I'll pay you top price.  I'll be needin' hides from graymist hunters.\n\nYou'll find them all around in pockets to the north, hunting stag.  Remember, mon.  Top price!", objectives = "" }
WordHunterWoW_QuestEN[12176] = { title = "A Minor Substitution", description = "Krenna, she be wantin' worg hides for all the outfits.  There's not gonna be enough worg hides for her army, though.  Not now, not ever.\n\nThose worgs -- they be skinny, mon!  Here's what we're gonna do... if you can keep a secret that is.\n\nEast of Voldrune there be grizzly bears as fat as an ogre.  Those large hides -- those we can use!\n\nHurry, brother.  Krenna's not known for her patience.", objectives = "" }
WordHunterWoW_QuestEN[12177] = { title = "Jun'ik's Coverup", description = "Ah, we have a small problem.  Grizzly hides... they be brown, mon!\n\nThink... think!\n\nI got it, mon!  Is like this: gray is black an' white all mixed up.  You get me some coal an' some flour, I'll grind it all up and dust the hides with it.  No one will know the better!\n\nBlacksmiths sell coal for smeltin' an' you can get flour from the provisioner. ", objectives = "" }
WordHunterWoW_QuestEN[12178] = { title = "Delivery to Krenna", description = "This is it, mon.  Let's take these hides to Krenna and see if they pass the test.\n\nLet's hope for both our sakes Krenna doesn't notice anything.", objectives = "" }
WordHunterWoW_QuestEN[12180] = { title = "The Captive Prospectors", description = "Raegar sent a team of prospectors into Dun Argol to search for artifacts and information about the history of the settlement. Raegar's team never expected Dun Argol to be this heavily populated.\n\nThey're being held captive while the iron dwarves prepare for war. We haven't the men to charge in after them, and Raegar's too busy fantasizing about defeating the irons to be of much help.\n\nIt falls to you, {name}. Any of the irons or their servants could be carrying the keys to the cages holding our men.", objectives = "" }
WordHunterWoW_QuestEN[12181] = { title = "Give it a Name", description = "My, my, how long has it been? How long have we been working on this damned plague? Finally, after an eternity of failure, we are blessed with perfection. This... It doesn't even have a proper name yet! This blight... That's it, BLIGHT! This blight will tear down the very fabric of life!\n\n<Harris hands you a vial.>\n\nNow, find the bat handler, Tobias, and show him the specimen. He'll get you on your way to Venomspite.\n", objectives = "" }
WordHunterWoW_QuestEN[12182] = { title = "To Venomspite!", description = "I got a special bat all lined up for you, buddy. Fastest and smoothest ride I've got. He'll take you right to Venomspite - in style.\n\nJust hand that vial over to Chief Plaguebringer Middleton once you land. ", objectives = "" }
WordHunterWoW_QuestEN[12183] = { title = "Looking the Part", description = "If, as Prospector Varana said, only certain irons are permitted to communicate with this Loken, it'll probably be the overseers who have the privilege.\n\nWe have to get you in there to see what all this is about, but it won't be easy. The first step will be to get a proper uniform for you.\n\nThen, we'll worry about doing your makeup.\n\nFind one of the overseers at Dun Argol, kill him, and bring back his uniform. If you get blood on it, you'll have only yourself to blame.", objectives = "" }
WordHunterWoW_QuestEN[12184] = { title = "Cultivating an Image", description = "Now that we've got the uniform, we've got to get enough information to complete your camouflage.\n\nRaegar brought along this camera to document the team's finds, but I have a different use in mind. I want you to take it with you to Dun Argol and use it to capture the images of iron dwarves.\n\nOf course, your models aren't going to be a cooperative lot, so you may have to, err... subdue them first. Bring back the camera and the images when you're done.", objectives = "" }
WordHunterWoW_QuestEN[12185] = { title = "Put on Your Best Face for Loken", description = "Using the images you've captured, I've created everything you need for your overseer disguise kit. You'll make a fine iron dwarf, if I do say so myself.\n\nTake the kit with you to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.\n\nThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.", objectives = "" }
WordHunterWoW_QuestEN[12188] = { title = "The Forsaken Blight and You: How Not to Die", description = "The details behind the functionality of the blight are hardly important. All you need to know is that it does the job it was designed to do. I have managed to synthesize a strain of the blight that is inert.\n\n<Middleton uncorks a vial and inhales.>\n\nSee, my body is still, mostly, intact. Now mix this with a reactive agent and we'd all be turned to shapeless piles of goo.\n\nOn the beach south of here you will find pathetic specters of Alliance soldiers past. Slay them and bring me ectoplasmic residue.", objectives = "" }
WordHunterWoW_QuestEN[12189] = { title = "Imbeciles Abound!", description = "The shipment from New Agamand was to arrive at Venomspite last week and then be delivered to me after some simple field tests. It is a Horde imperative - the last piece of the \"victory puzzle.\"\n\n<Sintar sighs.>\n\nIt is quite disheartening to know that you are surrounded by imbeciles and incompetent boobs!\n\nYou must travel to Venomspite, near the eastern border of Dragonblight. Find that buffoon, Middleton, and let him know that I am waiting on the package.", objectives = "" }
WordHunterWoW_QuestEN[12190] = { title = "Say Hello to My Little Friend", description = "Harkor's gunna drop a gold brick when he sees these choice ingredients. All that be left is gettin' them to him.\n\nHe's camped out on the eastern coast near dem haunted ruins - Drakil'jin, dey be called.\n\nYou'll likely be makin' it there before I can finish up with these corpses... unless, ya think you'd rather try your hand at embalming?", objectives = "" }
WordHunterWoW_QuestEN[12191] = { title = "Chug and Chuck!", description = "Hey, you look like you've got a good arm!\n\nWe like to keep things lively around camp, and nothing says fun like a good old-fashioned mug toss!\n\nThink you've got the aim to hit S.T.O.U.T.? Just grab a sampler, take a sip, and see if you can land a hit. It's trickier than it looks, but that's half the fun. Step right up and give it a shot!", objectives = "" }
WordHunterWoW_QuestEN[12192] = { title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Bizzle and explain your heroic triumph over the Dark Iron dwarves.", objectives = "" }
WordHunterWoW_QuestEN[12193] = { title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", objectives = "" }
WordHunterWoW_QuestEN[12194] = { title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "" }
WordHunterWoW_QuestEN[12195] = { title = "The Unexpected 'Guest'", description = "A recent hunting expedition brought back more than just game.\n\nThey encountered a wounded dwarf fleeing the iron dwarf stronghold of Dun Argol. He may have information we can use to strike at our ancient enemy, but before he's of any use to us, we must bring down his fever.\n\nThe horns of the silvercoat stags, who roam the nearby forest, have long been used to make healing poultices. If you can bring enough of the horns to me, we'll see if the poultice can bring our 'guest' around.", objectives = "" }
WordHunterWoW_QuestEN[12196] = { title = "From the Ground Up", description = "We don't have enough time for me to forge the parts myself, but the foundries over at Dun Argol, to the southeast, are working day and night to churn out golem parts.\n\nI think you should go back there and pick up enough of them for me to make a golem from this blueprint.\n\nThey're probably scattered around any of the buildings where the iron rune-smiths are working.\n\nPlease hurry, {name}. That Tormak looks like he's just waiting for an excuse to carry out his threat!", objectives = "" }
WordHunterWoW_QuestEN[12197] = { title = "We Have the Power", description = "Well, we've got the shell of a golem, but that's not good enough for Tormak. He doesn't realize that these things don't just come together and miraculously start working! We're going to need power cells to animate it.\n\nWhen I was in Dun Argol, I noticed that Rune-Smith Durar and Rune-Smith Kathorn were the ones who manufactured the cells. We'll need one from each to power our golem.\n\nYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.", objectives = "" }
WordHunterWoW_QuestEN[12198] = { title = "... Or Maybe We Don't", description = "The golem's cells have just enough power to run it at the lowest levels, but it can't power any of its combat systems.\n\nThe good news is that the perimeter of Dun Argol is patrolled by lightning sentries. We should be able to use their power to charge up the golem's weapon systems.\n\nBring the golem with you, take it close to them, it will absorb the power as the sentries die.", objectives = "" }
WordHunterWoW_QuestEN[12199] = { title = "Bringing Down the Iron Thane", description = "Now that the golem is fully charged, it can be used against the leader at Dun Argol.\n\nWhen I observed Iron Thane Furyhammer, he was always guarded by a personal golem that shielded him from all harm.\n\nThat construct, called The Anvil, can be disrupted, causing him to drop the shield. Use your golem's EMP ability to do just that. You'll be able to activate and take control of your golem inside Dun Argol.\n\nThe thane is in the main plant at the top and supervises production from the bottom level.", objectives = "" }
WordHunterWoW_QuestEN[12200] = { title = "Emerald Dragon Tears", description = "With an inert specimen of the blight compound complete and the activating agent in hand there only remains a need for a suitable shell to house the components.\n\nSouthwest of here, on the shores of central Dragonblight, is where you will find the Emerald Dragonshrine. Within the shrine you will find the hardened remnants of a green dragon's tear drop. I don't know the whole story, but apparently they cry a lot right before they die. Go figure.\n\nGo to the Emerald Dragonshrine and gather tears.", objectives = "" }
WordHunterWoW_QuestEN[12201] = { title = "The Overseer's Shadow", description = "It sounds like this Loken is the mastermind behind the sudden preparations for war on the part of the iron dwarves.\n\nOnly the highest ranking irons are likely to have access to him, so we'll have to make you into an overseer to find out what's going on in there.\n\nI have a plan, for that, but we'll need some supplies.\n\nFind one of the iron rune overseers at Dun Argol, to the southeast, kill him, and bring back his uniform. ", objectives = "" }
WordHunterWoW_QuestEN[12202] = { title = "Cultivating an Image", description = "Now we have to finish the job of making you as repulsive as those iron dwarves.\n\nThe best way to do that is to base your disguise on the ugly mugs of real iron dwarves.\n\nWhen Tormak's hunting party discovered that wayward prospector, they took the camera he carried. Now, I suppose, we'll get the chance to use it.\n\nTake it with you to Dun Argol, kill some iron dwarves, and record their likenesses in this device. Bring it back once you have enough examples.", objectives = "" }
WordHunterWoW_QuestEN[12203] = { title = "Loken's Orders", description = "I've created everything else you'll need for your overseer disguise kit. Try not to retch when you put it on. I took pains to make it as true to reality as possible.\n\nTake the kit with you southeast to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.\n\nThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.", objectives = "" }
WordHunterWoW_QuestEN[12204] = { title = "In the Name of Loken", description = "The iron dwarves stand as one of the fiercest and most coordinated foes in Northrend. Wherever we have traveled, they have battled us with the name of Loken on their lips.\n\nWe must learn who this Loken is and what he seeks. The locals may be of help.\n\nTo the northeast, at the Redwood Trading Post, a human named Hugh Glass peddles his wares. Further east, at the Ruins of Tethys, you'll find a stone giant named Gavrock. Ask them about this Loken. They've got to know something of use.", objectives = "" }
WordHunterWoW_QuestEN[12205] = { title = "WANTED: The Scarlet Onslaught", description = "By order of High Executor Wroth all members of the illegal organization known as the Scarlet Onslaught are to be put to death immediately.\n\nNo quarter is to be offered, and those proceeding to action upon this decree should be aware that any who are captured by the humans will be left to die, or worse!\n\nIn the High Executor's words, \"Paint the snow red with their blood!\"", objectives = "" }
WordHunterWoW_QuestEN[12206] = { title = "Blighted Last Rites", description = "Have you read the wanted poster? What is the high executor thinking?!\n\n<Vicky looks around and continues in hushed tones.>\n\nWe can't very well have those Scarlet Onslaught idiots being raised by their priests, or worse, rising as the Scourge, now can we?\n\nNo, I'm in total agreement with you, we have to do something about the corpses.\n\nI have just the thing. Take this blight that we just created and test it on the prisoner in the cage right here.\n\nNo muss, no fuss, no returning enemies.", objectives = "" }
WordHunterWoW_QuestEN[12207] = { title = "Vordrassil's Fall", description = "Long ago, powerful druids planted a tree to the northeast of here.\n\nIt was called Vordrassil and it was to be a world tree.  It is not known why, but after the tree was fully grown, the druids decided it needed to be destroyed.\n\nEver since we arrived here, the earth has spoken to me, {name}.  Its cries of pain come from the places where Vordrassil's remains fell on the ground.\n\nCorrupting ooze roams those places.  Bring me samples of it so we may begin to heal the land.", objectives = "" }
WordHunterWoW_QuestEN[12208] = { title = "Good Troll Hunting", description = "Good for nothing wretches!\n\nThey could have had it easy. We extended our hand in peace. All they had to do was give us passage through Drak'Tharon and we'd have let them be.\n\nBut no, the prideful little ice trolls decided that they wanted it rough. Now they'll be destroyed and we'll pass through their precious keep to Zul'Drak anyway.\n\nWe've contracted a gang to deliver us captured trolls. Talk to Samir if you want in on the action. You can find him to the northwest of here, due south of Zeb'Halek.", objectives = "" }
WordHunterWoW_QuestEN[12209] = { title = "Materiel Plunder", description = "Ah good, new meat. Do you wish to prove yourself, new meat?\n\nThe Scarlet Onslaught, the most zealous and racist of the Scarlet Crusade, are in our backyard to the south. If we're going to fight them, we'll need more armor and weapons than I can make in such a short time.\n\nWhy don't we take theirs?\n\nMore to the point, why don't YOU take theirs?", objectives = "" }
WordHunterWoW_QuestEN[12210] = { title = "Troll Season!", description = "You, {race}! No sense standing around here when there's work to be done!\n\nDrak'Theron Keep is the most direct route to Zul'Drak. We MUST capture it to ensure safe passage for the Alliance. But until we get the numbers to make an assault, we'll have to content ourselves in thinning out the ice trolls and collecting intel.\n\nTo that end, we've conscripted a gang of thugs to capture and deliver live trolls for interrogation. Travel northwest and speak with Samir at Granite Springs. He'll direct you further.", objectives = "" }
WordHunterWoW_QuestEN[12211] = { title = "Let Them Not Rise!", description = "I don't understand it. The blight should have worked!\n\nNo sense worrying about it now.\n\n<The apothecary seems relieved for some reason.>\n\nThough it doesn't work on the Onslaught for some strange reason, we still need to keep their priests from raising them.\n\nI have another idea, one that their corpses shouldn't have any protection from.\n\n{name}, take a container of my rats and unleash them upon any Onslaught corpses you come across at New Hearthglen. I starve the vermin, so they should be voracious!", objectives = "" }
WordHunterWoW_QuestEN[12212] = { title = "Replenishing the Storehouse", description = "G'day, {class}.\n\nThe good lieutenant here says that there's been a Horde raid on our storehouse that's left our food supply dangerously low.\n\nNo doubt we'll make those cretins pay, but first we need to focus our attention on restocking. My men are doing all they can, but we're going to need every able body to contribute if we're to avert a crisis.\n\nYou should have no trouble harvesting venison from the local stag in these parts. Happy hunting!", objectives = "" }
WordHunterWoW_QuestEN[12213] = { title = "The Darkness Beneath", description = "Something... dark... happened to the tree Vordrassil.  After the druids decided to destroy it, its hollow remains grew roots deep into the ground.\n\nI want you to go to the three locations to the northeast where the tree's trunk shattered and go as far beneath the ground as you can.\n\nUse this orb once you get there to get an imprint of the energy surrounding the area.  This might shed some light on what happened to Vordrassil and why it failed to become a world tree.", objectives = "" }
WordHunterWoW_QuestEN[12214] = { title = "Fresh Remounts", description = "Hello. I am Hansel. Pleased to meet you, sir.\n\nThe high executor came to me and said, 'Hansel, I want you to get us new mounts.'\n\nWhere does he think dreadsteeds come from? The ground?\n\n<whispering> Actually, they do if you can find a horse graveyard.\n\nBut we don't have one of those, so what we need you to do is go south to New Hearthglen, kill the knights, take their riding crops, and steal their warhorses.\n\nRide the horse back to me here and hand over the reins, if you would.", objectives = "" }
WordHunterWoW_QuestEN[12215] = { title = "Them or Us!", description = "As if we didn't have enough to concern ourselves with....\n\nWith the present food crisis, we find ourselves competing for food with the local worgs. The situation is becoming more dire, and I fear that if we don't address the issue immediately we'll soon find ourselves with nothing to hunt.\n\nScour the forest, {race}. Kill any graymist you find. Recent reports have sighted a concentration of them on the other side of the river west of here.", objectives = "" }
WordHunterWoW_QuestEN[12216] = { title = "Take Their Rear!", description = "We've all been working hard and it's beginning to pay off, but we're still far from our goal. We need much more meat than we have and it's growing clear that the local stag population won't be enough by itself.\n\nI'm afraid we need you to turn your attention to more dangerous prey - the grizzlies that give this region its name. They're plentiful, and they're well fed from the abundant fish that swim in these streams.\n\nBe safe, {class}!", objectives = "" }
WordHunterWoW_QuestEN[12217] = { title = "Eagle Eyes", description = "Well, {name}, we've determined how the Horde was able to locate our hidden stores of food.\n\nIt turns out that they were binding their sight to the unsuspecting eagles that soar above the trees here. Using eagle vision, they were able to effectively spy on our every action.\n\nBy order of the lieutenant, we've got to hunt down these majestic birds in order to thwart our enemy.", objectives = "" }
WordHunterWoW_QuestEN[12218] = { title = "Spread the Good Word", description = "Before I can ship you off to Doctor Malefious with the good news, you will have to run a simple field test of the blight with the modifications I have made.\n\nThe hungering dead stream out from what remains of Old Wintergarde. Commandeer a vehicle from the east gate and drive it northeast through Vengeance Pass until you reach the twin towers at the southeastern edge of Wintergarde. Drop the blight bomb on the undead that cover the area. Report back to me with the results!", objectives = "" }
WordHunterWoW_QuestEN[12219] = { title = "The Failed World Tree", description = "My ancestors once planted a tree in the middle of the Grizzly Hills.\n\nIt was called Vordrassil and it was to become a world tree.\n\nFor reasons long forgotten, after the tree was fully grown, they decided it needed to be destroyed.  Its giant trunk splintered at three locations in the area to the north.\n\nWhere the tree touched the ground, foul ooze began to crawl the earth.  Bring me slime samples so I can begin my work and the earth can be healed.", objectives = "" }
WordHunterWoW_QuestEN[12220] = { title = "A Dark Influence", description = "When the tree Vordrassil fell, its hollow remains grew roots deep into the ground.\n\nI want you to go north of here to the three locations where the trunk shattered and go as far beneath the ground as you can.  You'll find them west of Grizzlemaw.\n\nUse this orb once you get there to get an imprint of the energy surrounding the area.  If we're to heal the land, we must first find out what caused Vordrassil to fail as a world tree all those years ago.", objectives = "" }
WordHunterWoW_QuestEN[12221] = { title = "The Forsaken Blight", description = "I have prepared a package that must be delivered to Doctor Sintar Malefious at Agmar's Hammer. The contents of the package include the final blight specimen along with instructions on preparation and samples of the reactive agent.\n\nYou will find Agmar's Hammer in western Dragonblight. Just look for the black, jagged metal orc buildings - that will be Agmar's Hammer.\n", objectives = "" }
WordHunterWoW_QuestEN[12222] = { title = "Secrets of the Flamebinders", description = "Even as we attempt to fight off the Horde, the Dragonflayer tribe musters in their village of Voldrune, near the coast to the south.\n\nThe most powerful warriors in the village are granted flame-imbued talismans that give them the ability to control powerful, savage proto-drakes. If we can gain control of one of these drakes, perhaps we can use it to neutralize the threat posed by Voldrune.\n\nThe Dragonflayer flamebinders create the talismans and imbue them with power. Kill them and take the talismans.", objectives = "" }
WordHunterWoW_QuestEN[12223] = { title = "Thinning the Ranks", description = "There's a flurry of activity down in Voldrune village to the south. Thane Torvald Eriksson and his huscarls are preparing for war. With most of our men in the field dealing with the Horde's treachery, Amberpine will be vulnerable.\n\nTravel to Voldrune, which is near the southern coast, and show those Dragonflayers we're no soft target.\n\nSlay as many of the huscarls as you can find. Make them think twice about taking advantage of our conflict with the Horde.", objectives = "" }
WordHunterWoW_QuestEN[12224] = { title = "The Kor'kron Vanguard!", description = "You have done well, brother. All that you have faced, you have done as a champion of the Horde. The Scourged Anub'ar of Azjol-Nerub, crushed under your foot! The taunka, brave and powerful new members of the Horde, because of you! Our super-weapon against the Scourge, tested and perfected by you!\n\nThe time has come, the moment is now - our elite soldiers at the Wrathgate need you. The son of Saurfang awaits your arrival at the Kor'kron Vanguard. Go now, northeast to the Wrathgate.", objectives = "" }
WordHunterWoW_QuestEN[12225] = { title = "Mmm... Amberseeds!", description = "Your stomach growls as the pungent smell of hearty nuts draws your attention to the bucket of seeds.\n\nSome thoughtful soul has obviously left these complimentary morsels here to rejuvenate weary visitors. Grateful, you take the remaining few and devour them.\n\nThe seeds do not disappoint. Finding yourself hungry for more, you set out to discover their origins....", objectives = "" }
WordHunterWoW_QuestEN[12226] = { title = "Just Passing Through", description = "We must act quickly, {race}! We can't risk letting those precious seeds become fully digested. They need to come out, NOW.\n\nForage up some blackroot from the riverbank just west of here and I'll make you a purgative that should get things moving.\n\nHurry now! And remember, you brought this upon yourself....", objectives = "" }
WordHunterWoW_QuestEN[12227] = { title = "Doing Your Duty", description = "Alright, {race}. Here's the juice.\n\nIt works immediately, so don't use it until you're safely inside the outhouse.\n\nNow go get me those seeds!", objectives = "" }
WordHunterWoW_QuestEN[12229] = { title = "A Possible Link", description = "Not long ago we sent an expedition to the east, where it was attacked by crazed furbolgs.  One of the survivors described slaying one of them and its body expelling a dark slimy substance.\n\nFor thousands of years, the furbolgs in this region have been peaceful.  It is possible that there is a link to the furbolgs' behavior and the dark energy we were able to detect earlier.\n\nBring me samples of the furbolgs' blood.  You will find them to the east in the Rage Fang Shrine and the Heart's Blood Shrine.", objectives = "" }
WordHunterWoW_QuestEN[12230] = { title = "Stealing from the Siegesmiths", description = "I'm tasked with the destruction of the Scarlet Onslaught's ballistae. Unfortunately, the apothecaries and I are at odds on the use of our resources, so I've nothing to destroy them with!\n\nTo the northeast are the Carrion Fields. The Scourge siegesmiths there at their forge and meat wagons are demolition masters.\n\nLuckily for us, they also leave their bombs lying about. \n\nI want you to retrieve them for me, off of the ground or the siegesmiths, I don't care which.", objectives = "" }
WordHunterWoW_QuestEN[12231] = { title = "The Bear God's Offspring", description = "It is possible that the furbolg of Grizzly Hills have the same taint that plagued Vordrassil.  They've been involved in a deadly tribal war recently after years of peaceful coexistence.\n\nThe shrines that they guard to the east are home to Ursoc's offspring.\n\nIf the corruption has affected the furbolg, it is possible that because of their lineage, Kodian and Orsonn have remained unharmed.\n\nIf that's the case, find them and listen to what they have to say.", objectives = "" }
WordHunterWoW_QuestEN[12232] = { title = "Bombard the Ballistae", description = "At last, our chance to strike at their siege engines! Don't flub it.\n\nI kid.\n\nA little.\n\n{class}, bombard New Hearthglen's ballistae with these bombs.\n\nWe'll show the Royal Apothecary Society how it's done old style. No concoctions required!", objectives = "" }
WordHunterWoW_QuestEN[12233] = { title = "[Depricated]Sewing Your Seed", description = "No, no... You hold on to these.\n\nYou didn't actually expect me to handle them after all of that did you?\n\nhere's what you're going to do....", objectives = "" }
WordHunterWoW_QuestEN[12234] = { title = "Need to Know", description = "I need to know what New Hearthglen is up to.\n\nI want you to steal their orders of the day so that I can find that out.\n\nHead south and in their abbey, in their barracks, and on their beach, find those daily plans!\n\nJust in case you're confused, the barracks is the large building right next to the smithy.", objectives = "" }
WordHunterWoW_QuestEN[12235] = { title = "Naxxramas and the Fall of Wintergarde", description = "Lord Fordragon has led a crushing assault against Arthas at the Wrathgate. In response to this affront, Arthas has sent Naxxramas down upon us. While Kel'Thuzad hides in the floating citadel, his ground commander, Thel'zan, lays siege to Wintergarde Keep. The lower village is already lost and any chance of extracting survivors from the ruins diminishes by the minute.\n\nWe must act quickly! Report to Gryphon Commander Urik at the gryphon station at once! He'll get you up to speed.\n\nLeave me!\n", objectives = "" }
WordHunterWoW_QuestEN[12236] = { title = "Ursoc, the Bear God", description = "The time has come, {name}.  Now we will learn whether our efforts will accomplish what we need or nothing at all.\n\nTake these ashes and seek the furbolg that Kodian told you about, Tur Ragepaw, near Ursoc's Den.  You will find the den to the north of Grizzlemaw.\n\nConvince Tur to aid you, for you will need all the help you can get.\n\nOnce you've defeated the bear god, use these ashes over his body.\n\nEven if his worldly form is destroyed, his spirit must be saved.", objectives = "" }
WordHunterWoW_QuestEN[12237] = { title = "Flight of the Wintergarde Defender", description = "With this whistle you can call down a Wintergarde gryphon. Mount the creature and head towards the ruins of Wintergarde Village, now known as the Carrion Fields, southeast of here. Once at the fields, keep your eyes peeled for helpless Wintergarde villagers. When you spot one, fly low and use the gryphon to pick them up. Return the rescued villager here, to the gryphon station.\n\nThere are Scourge all over the place so you'll need to keep your wits about you, hero. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[12238] = { title = "Cleansing Drak'Tharon", description = "Drak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", objectives = "" }
WordHunterWoW_QuestEN[12239] = { title = "The Spy in New Hearthglen", description = "I have a spy within the ranks of the Scarlet Onslaught. I need you to deliver these daily orders to her so that she can plan the next phase of our assault.\n\nShe goes by the name of Agent Skully and she's under a magical guise to appear as the Onslaught's cemetery caretaker.\n\nHere, take these orders to her, and then do as she asks. You'll find the graveyard on the side of the abbey.", objectives = "" }
WordHunterWoW_QuestEN[12240] = { title = "A Means to an End", description = "I received a few barrels of termites from my sister at the Bulwark back home in the last shipment. I think they're going to come in handy for something I have in mind for you.\n\nThe lumbermill operations at New Hearthglen are problematic for us, but so far we haven't been able to get anyone in there to take out their foreman.\n\nI think that if you were to unleash these termites on his precious woodworks, he'd be sure to come running.\n\nReady to take him out, {class}?", objectives = "" }
WordHunterWoW_QuestEN[12241] = { title = "Destroy the Sapling", description = "The furbolgs' work must be undone, {name}.  The best of intentions do not count for much when the result is tainted by such strong a corruption.\n\nThe sapling must be destroyed, for it is the source of this dark influence.  Take this torch and use it to set fire to the corrupted sapling and bring me its ashes.\n\nOnce cleansed, by fire, I will use what power I can to remove the taint from them.  You will need the ashes to purify Ursoc from the evil power that holds sway over him.", objectives = "" }
WordHunterWoW_QuestEN[12242] = { title = "Vordrassil's Seeds", description = "We must make sure that Vordrassil is never regrown.  The furbolg must have harvested its seed.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain all the seeds that you can find.  I will make sure they're properly destroyed.", objectives = "" }
WordHunterWoW_QuestEN[12243] = { title = "Fire Upon the Waters", description = "I have another mission for you.\n\nI was able to repurpose some of the blight to concoct my world-famous burning water. I want you to take it and set the sails of the Sinner's Folly ablaze!\n\nUse it from the dock. Once the sails are on fire, the deckhands will be busy putting them out, and you'll slip belowdecks to 'retrieve' the captain's rutters.\n\nYou'll find the ship on Crusader's Landing, below and south of New Hearthglen. Look for the captain's quarters on the first lower deck, behind the stairs.", objectives = "" }
WordHunterWoW_QuestEN[12244] = { title = "Shredder Repair", description = "Listen, pal. Why don't ya roll up your sleeves and grab a wrench? There's work to be done! They need these shredders refurbished and sent down to Venture Bay, and they need it done yesterday....\n\nNo wrench? Well what good are ya then? May as well go down with the rest of the lugheads and play with the Horde!\n\nWhile you're there, see if you can drive some of those broken-down shredders up here for repairs. Be careful! They're in pretty bad shape.", objectives = "" }
WordHunterWoW_QuestEN[12245] = { title = "No Mercy for the Captured", description = "We have more fools for you to kill.\n\nMy agents tell me that several of our good citizens have seen fit to fall into the hands of the Scarlet Onslaught.\n\nThis will not do.\n\nGo back to New Hearthglen and eliminate Deathguard Schneider, Senior Scrivener Kinnedius, Engineer Burke and Chancellor Amai.\n\nFrom what I hear, they're spread out throughout the area. No doubt they are being kept in cages awaiting torture.\n\nSpeak with them and then kill them!", objectives = "" }
WordHunterWoW_QuestEN[12246] = { title = "A Possible Link", description = "The furbolgs that live east of here are more aggressive and bestial than the ones we're used to.  Our forces have squared off with them more than once, and the survivors always speak of a dark, slimy substance dripping from their corpses.\n\nTheir condition could be linked with the contaminants we found on Vordrassil's remains.\n\nBring me samples of the furbolgs' blood.  You will find them in the Rage Fang Shrine and the Heart's Blood Shrine, far to the east.", objectives = "" }
WordHunterWoW_QuestEN[12247] = { title = "Children of Ursoc", description = "The furbolgs of Grizzly Hills carry with them a corruption of some kind, that is for sure.  Tribal war has broken out amongst them after years of peaceful coexistence.\n\nWhat remains to be seen is whether the bears they worship as gods have also been tainted.\n\nUrsoc's two children, Orsonn and Kodian, dwell in the Heart's Blood Shrine and the Rage Fang Shrine, south and southeast of Grizzlemaw.\n\nSee if they will speak to you regarding what has happened here.", objectives = "" }
WordHunterWoW_QuestEN[12248] = { title = "Vordrassil's Sapling", description = "The druids of old seem to have had good reasons for destroying Vordrassil.  We cannot let the furbolgs regrow it.\n\nOn the other hand, saving Ursoc's spirit hinges on the magic contained by the sapling.\n\nTake this torch and use it to burn the tree.  You will find it in the middle of Grizzlemaw, inside Vordrassil's old trunk.\n\nBring me Vordrassil's ashes.  It is my hope that once purified by fire, we may use its magic to cleanse Ursoc's spirit of its dark taint.", objectives = "" }
WordHunterWoW_QuestEN[12249] = { title = "Ursoc, the Bear God", description = "It is time, {name}.  Take these ashes and look for the furbolg that Kodian spoke of.  If he went to seek Ursoc, he will be near his den, north of Grizzlemaw.\n\nYou will need his help.  You won't be able to defeat Ursoc alone.\n\nOnce you've defeated Ursoc, use these ashes to purify his spirit.  Only then will we know whether our efforts have been in vain or not.", objectives = "" }
WordHunterWoW_QuestEN[12250] = { title = "Vordrassil's Seeds", description = "We cannot allow Vordrassil to grow again.  If the furbolg regrew it once, they can do it again.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain Vordrassil's seeds.  I will make sure they're properly disposed of.", objectives = "" }
WordHunterWoW_QuestEN[12251] = { title = "Return to the High Commander", description = "Return to High Commander Halford Wyrmbane at once, {name}. Let him know that your mission was a success and that the few remaining villagers that were rescued are back to work.", objectives = "" }
WordHunterWoW_QuestEN[12252] = { title = "Torture the Torturer", description = "Enough! I want you to put an end to the torture of my people!\n\nThe Onslaught's torturer, Alphonse, has been bleeding information out of everyone that gets caught by those fiends! I need to know what they know.\n\nMy sources tell me that he has set up shop in the basement of their barracks, which is right next to the smithy.\n\nI'll loan you my personal branding iron to see to it that the job is done right.\n\nFind him and get that information.", objectives = "" }
WordHunterWoW_QuestEN[12253] = { title = "Rescue from Town Square", description = "Just down this path here is Wintergarde's town square. Once a hive of activity for the citizens of Wintergarde, now a warzone, filled with murderous geists hell-bent on vengeance towards the living.\n\nIn the buildings surrounding the town square are trapped villagers that must be rescued! I ask much of you, now, {name}, but you are the only soldier I can spare. Free our people. Take this path down into town square and enter those houses. Kill anything that gets in your way! Return to me should you survive.", objectives = "" }
WordHunterWoW_QuestEN[12254] = { title = "Without a Prayer", description = "These plans indicate something imminent is being planned.\n\nBut first, there's the matter of this strange protection that the Onslaught forces have. If Venomspite is to deal with them once and for all, we must find out who's behind it and eliminate them.\n\nI've noticed that the bishop in the chapel on the far side of New Hearthglen, across from the lumbermill, has stepped up his blessing of the troops. Kill him and steal his prayer book.\n\nMaybe it will give us a clue.", objectives = "" }
WordHunterWoW_QuestEN[12255] = { title = "The Thane of Voldrune", description = "Now that you've captured the flame-imbued talismans and weakened Voldrune's defenses, we can strike at its leader, Thane Torvald Eriksson.\n\nThe thane's favorite mount is an unruly proto-drake he calls Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the talismans, you should be able to control it long enough to use it against the thane.\n\nOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and show him no mercy.", objectives = "" }
WordHunterWoW_QuestEN[12256] = { title = "The Flamebinders' Secrets", description = "Even as the Alliance cowards attack our positions, the Dragonflayer vrykul outpost of Voldrune, to the southeast, prepares for war. The vrykul are far from the strongest enemy we face here, but we must eliminate them before they can truly threaten us.\n\nTheir most powerful warriors are permitted to ride half-trained proto-drakes into battle. To control the beasts, their flamebinders create powerful talismans. You'll need to slay them and take the talismans if our plan is to work.", objectives = "" }
WordHunterWoW_QuestEN[12257] = { title = "A Show of Strength", description = "Preparations for war are underway in the vrykul village of Voldrune to the southeast. Voldrune's thane cannot field a large army, but with our forces spread thin, we are still at risk.\n\nWe cannot risk giving the thane and his men an opportunity to attack, so we must take the battle to them. If you are truly a {class} of the Horde, you will relish the chance to demonstrate our strength.\n\nCut down the huscarls and prove to this Dragonflayer clan that the Horde is not to be trifled with!", objectives = "" }
WordHunterWoW_QuestEN[12258] = { title = "The Fate of the Dead", description = "The town square, down this path, is overrun with the undead citizens of Wintergarde! Our own crypt provides a seemingly endless supply of soldiers for the Scourge to throw at us. Take no pity on them, though, {name}. While they were once mortal, capable of compassion and thought, they are now ravaging undead with only one purpose: our destruction.\n\nVenture forth to the town square and deliver the vengeful geists to their maker. Give them peace.", objectives = "" }
WordHunterWoW_QuestEN[12259] = { title = "The Thane of Voldrune", description = "With the flame-imbued talismans, we can finally challenge the thane.\n\nHis favorite mount is a ferocious proto-drake called Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the power of the talismans, you should be able to bend it to your will and use it against the thane.\n\nOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and use Flamebringer to destroy him.", objectives = "" }
WordHunterWoW_QuestEN[12260] = { title = "The Perfect Dissemblance", description = "You may wonder how I can maintain this guise; I use a magic mirror that was loaned to me by the spy mistress.\n\nIt only has so much power in it, but I think there's enough for the both of us. Here, take it. I want you to use it to impersonate one of the Onslaught raven priests.\n\nBe quick about it... I have no idea how long my glamour will last while you have the mirror.\n\nRealize that you won't immediately be perfectly disguised, so don't count on it being foolproof until I've had a chance to help you.", objectives = "" }
WordHunterWoW_QuestEN[12261] = { title = "No Place to Run", description = "They're drawing power from the bones of my dead brothers...\n\nI have no love for the cult, but I'm baffled by their audacity. There will be no mercy shown for them... not that I ever would have anyway.\n\nEnsure that they have no place to flee when the slaughter starts. Place a destructive ward at the end of the path leading out of the shrine... where the road starts to give way to snow. Defend it until it is fully charged.", objectives = "" }
WordHunterWoW_QuestEN[12262] = { title = "No One to Save You", description = "We will spare no one. \n\nOutside, lowly necrolytes and their skeletal servants shame my land with their presence. Slaughter them all.", objectives = "" }
WordHunterWoW_QuestEN[12263] = { title = "The Best of Intentions", description = "The Cult of the Damned has not come just to extract power from dead dragons. I suspect I know what they are up to, but I need you to prove me correct.\n\nI will grant you the guise of this dead necrolyte. Proceed to the back of the cave and confirm their intentions for being in this sacred place. I will watch through your eyes. \n\nBe cautious {name}, any damage done to you is likely to break the fragile illusion.", objectives = "" }
WordHunterWoW_QuestEN[12264] = { title = "Culling the Damned", description = "The cave beyond was swarming with Cult atrocities. There is only one way to deal with such creatures... you know what to do.", objectives = "" }
WordHunterWoW_QuestEN[12265] = { title = "Defiling the Defilers", description = "I sensed a large accumulation of magic in the runes that we witnessed when you were scouting the cave. I will not have you toy with extracting the magic... often the most straight forward solution is the most effective one.\n\nDestroy the runes... stamp them out and ensure that the Cult will not have access to whatever power that they've accumulated there.", objectives = "" }
WordHunterWoW_QuestEN[12266] = { title = "Tales of Destruction", description = "You can leave now, {race}.\n\nGo tell Nalice she missed out on a good slaughter.", objectives = "" }
